/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20181112-4","meetingId":"h30-c-settlement","date":"2018年11月12日","dateIso":"2018-11-12","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を158件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２９年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより決算特別委員会を開会いたします。 それでは、平成２９年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"おはようあります。私からは、１８３ページの空き家等対策事業、時間があれば、１７１ページの放置自転車対策事業についてお伺いします。はこの品川区で認識している現在の区内の空き家の戸数と、あとはここ５年の戸数が、伸びてきているのか、減ってきているのかという推移もあわせてお聞かせください。","respondent":"森住宅課長","answer":"空き家に関するご質問です。平成３０年９月末現在で、７９９戸の空き家を確認しておるところです。ここ５年というお話ですけれども、平成２６年に実態調査をいたしまして、そこからそれほど大きく数字としては伸びているものではございません。","voiceIndex":4,"id":"exchange-001"},{"speaker":"芹澤委員","kind":"意見","question":"特に増減はあまりないというお話で、全国的に空き家対策はかなり力を入れて、今、注目をされてきているところかと思います。区内で認識されているいわゆる危険な空き家、特定空家がこの７９９戸の中にどれほど含まれているのかということを、わかればで結構ですので、地区ごとにお聞かせください。","respondent":"森住宅課長","answer":"現在、７９９戸のうち、特定空家としてカウントしているものは、荏原地区に１戸あります。ほかの地区につきましては、特定空家等というふうに指定しているものではございませんが、不適正な管理があるものとして１０５戸と認識しております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"この特定空家、荏原地区にまずは１戸ということで、実態調査を含めて特定空家においては、さまざまなステップを踏んで解体等の代執行をすることになるかと思いますが、これまで品川区が代執行を行った件数と、区が特定空家として認識をしてから代執行をするまでの流れ、平均的な期間等がありましたら教えてください。","respondent":"森住宅課長","answer":"その後、法律や条例に基づきまして、助言・指導、勧告、命令という形で進めてまいりましたが、なかなか所有者の方のご理解、ご協力を得られず、最終的に代執行を行ったです。日数としましては、平成２７年度に認定をいたしまして、平成２８年度に実施をしたです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"特定空家の対応についてお示しいただきありがとうあります。条例の中身を見ると、特定空家に対する代執行に関する規定がほとんどでして、活用の具体的な指針は記載が特にないのですが、実際に品川区が空き家を認識してから有効活用を実際に促進してきて、このような事例がありましたとか、有効活用の具体的な内容がわかれば教えてください。","respondent":"森住宅課長","answer":"その中で少ない件数ではありますけれども、何かしらご協力をいただけそうな空き家もありますので、そういった方々に連絡をとりながら、どのような対策ができるか、どのような活用ができるかという検討をしていきたいというふうに考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"芹澤委員","kind":"確認","question":"現在、８００戸ほどの空き家があるというお話をいただきましたが、まずはこの空き家ホットライン、９時から１２時の電話窓口で対応が受けとめ切れているのかということを、区の認識をお聞かせください。もう１点、続けて、空き家ホットラインで確認した後に、専門機関および関係団体へ区から紹介を行うというふうにホームページに記載がありましたが、この流れに関しては、他の自治体も同じかと考えています。","respondent":"森住宅課長","answer":"今現在、つくっております空き家の対策計画の概要を説明させていただきまして、それを具体的に進めていくための方策として、他団体の方々とさまざまな協定を含め、どのような連携が図っていけるのかということを具体的に今後進めていきたいというふうに考えております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"芹澤委員","kind":"意見","question":"空き家対策の難しいところの１つとして、行政が代執行した際に、解体費用等の費用回収が困難ということが一番難しいところだと思っています。この代執行をした場合に、所有者が不在の場合、あとは所有者が判明しているが管理等もしておらず、その所有者にも財産がない場合の２つの場合において、債権回収をどういう流れでする予定なのかをお聞かせください。","respondent":"森住宅課長","answer":"今後、代執行を進めて、なかなか払っていただけないというようなところもあるかもしれませんけれども、それにつきましては、例えば土地などの財産を所有している場合がありますので、そのようなところも含めて、しっかり債権回収はしていきたいと考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"芹澤委員","kind":"意見","question":"今、８００戸ほどの空き家があるということで、まだ特定空家には至っていない、まだ管理がされている空き家もあるかと思いますが、これは当然、いずれは特定空家として管理がされない空き家になってくるかと思いますので、行政から早めにアプローチをしていただいて、情報提供等で空き家になる前に多くの方々と行政とが連携して問題解決に取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-007"},{"speaker":"新妻委員","kind":"提案","question":"シェアサイクル事業ですが、都の補助金２分の１を活用しての事業です。ちょうど１年ぐらいの事業になりました。私も登録し利用しております。そして、私が建設委員会の所属のときに、シェアサイクルの利用者が区の施設等を利用したときには、お得な割引クーポンを発行してみてはどうかと提案させていただきましたが、このことについて現状をお聞かせください。","respondent":"今井土木管理課長","answer":"利用者サービス、割引クーポン等ですけれども、導入前からいろいろフェスティバルとかイベントの際に活用していただいた事例はあるのですが、なかなか日常の中での割引クーポンは難しいところがありますので、今後もいろいろな区のイベント等のときに。","voiceIndex":18,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"５１ポートまで広がるということで、ぜひよろしくお願いします。月に１回発行される月刊しながわニュースの区長選後の区長インタビューの中では、インタビュアーから、「昔は品川区は都内初の施策がもっと多かったように思う」との質問に対して、濱野区長が、「９月に災害時のシェアサイクル利用を都内で初めて決めました」と、こう答えられているものが載っておりました。","respondent":"今井土木管理課長","answer":"シェアサイクル事業ですが、現在、都内９区で連携をしておりますので、なかなか１区だけでの協定締結は検討課題だったのですけれども、やはり品川区における木密地域等の現状を踏まえまして。","voiceIndex":20,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"詳細を伺いました。ですので、災害時に活用するということであれば、日常のサポート、見回りも非常に重要になってくると思いますので、ぜひそこの調整もお願いしたいと思います。続きまして、可動式ホーム柵整備助成について伺います。今年の９月の下旬に、下神明駅で視覚障害者がホームから転落し、駅に入ってきた普通電車にはねられ、お亡くなりになられる痛ましい事故がありました。","respondent":"鈴木都市計画課長","answer":"今後の整備予定駅ですが、今年度は、東急大井町線旗の台駅の３・４番線で整備が行われます。平成３１年度につきましては、東急大井町線旗の台駅の５・６番線、それから下神明駅および戸越公園駅、りんかい線の大井町駅が予定されてあります。","voiceIndex":22,"id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"確認をさせていただきました。今、課長からもお話がありました。この事故がありました下神明駅は、２０１９年の下半期につくというふうに報道でもされておりました。何とか１日でも早く、下神明駅に設置がされないかというふうに思うわけですけれども、このようなことが品川区、事業者との間で何かやりとりがされているのか、少しでも早い設置が可能なのかどうかという見通しをお伺いいたします。","respondent":"鈴木都市計画課長","answer":"製品発注等もあります。そうしたところでの下半期というところでございました。区としても、整備助成を行うものですので、その助成の協議の中で、少しでも整備が早急に行われないか協議しながら進めていきたいです。","voiceIndex":24,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"次に八潮のまちづくり検討についてお伺いいたします。そして、品川区内での実績をお知らせいただきたいと思います。あわせて、２回行われた会合で出された資料ですが、これは区側がこのような内容でとコンサルに依頼をしているのか、または逆に、コンサルから出された内容を区が確認をして、これでいきましょうというふうにしているのかお知らせください。","respondent":"鈴木都市計画課長","answer":"平成２９年度２回の懇談会の資料ですが、基本的には区のほうで、八潮地区の現状ですとか、そういったところをお示しする資料を区のほうから指示をさせていただきまして、修正を何度かやらせていただきながら資料として使わせていただいたです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"私もこのまちづくり検討の会合のところに一住民として参加をさせていただきました。資料に関しても、八潮の地元地域の方々は、地元のことに特化したことを知りたいという思いもある中で、その話の中でも出ておりました。回を重ねていく中で、いい方向性が見出されてくるかとも思いますので、そこら辺も踏まえて、今後もぜひお願いしたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"八潮団地は、昭和５８年に竣工し、入居が開始されてからおおむね３５年経過しています。","voiceIndex":28,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"どうぞよろしくお願いします。次に、しながわ区民公園の改修工事について伺います。さらに、ちょっと何か注意をするときに声がけをしたいのだけれども、いかんせんスタッフは日本語しかしゃべれないということで、言葉が通じないということで苦慮されておりまして、何か翻訳機みたいなものもここにあればいいのだけれども、そういうお声もいただいておりますが、今後の区のご見解をお伺いいたします。","respondent":"溝口公園課長","answer":"そのような中で外国人居住者も増えてきている関係で、やはり外国語の表記といったものは必要だと考えておりますので、まずは、今、レンタル自転車の注意喚起のところの多言語化、そういったものに取り組んでいきながら、また、利用状況等を踏まえ。","voiceIndex":30,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"品川区内の外国人居住者の方も本当に増えていると考えていますので、具体的に今後も前向きにぜひご検討をお願いしたいと思います。最後に、しながわ水族館です。しながわ水族館は、羽田空港から一番近い水族館、そして羽田空港に一番近い水族館、行きも帰りも活用されるようなインバウンドの誘致のところでお伺いしたいと思います。今後の予定をお知らせください。","respondent":"溝口公園課長","answer":"しながわ水族館のインバウンド、国際化に対しての取組みですが、１つは、１１月に台湾の国際旅行博への出展、そういったものを考えています。さまざまインバウンドについては取り組んでいきたいと考えているところです。","voiceIndex":32,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"１７８ページ、やさしいまちづくり整備費に関連して、西大井駅の混雑について、１８０ページの広町地区整備検討委託より、単独検討業務委託、この庁舎について、１８４ページの区営住宅より、同性カップルの申込資格を伺います。この混雑は問題だと、もはや危険だと思いますけれども、いかがでしょうか。ぜひＪＲに混雑解消を求めていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"西大井駅につきましても、こうした機会を捉えながら、区としても状況の確認や鉄道事業者としての捉え方などを確認しながら、必要な協議を行ってまいりたいというふうに考えてあります。","voiceIndex":35,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"必要な協議を行っていきたいということですけれども、ぜひ状況を把握していただいて、混雑解消をＪＲに申し出ていただきたいと要望しておきたいと思います。委託先はどこか。予算１,５００万円に対して決算額は幾らか。そして区に委託先から納品されている報告書には何が書かれているのか伺います。","respondent":"稲田都市開発課長","answer":"委託先です。ＪＲとの共同検討と、区単独検討ということで予算が組み立てられておりますが、今ご質問の区単独検討についてですが、予算は１,５００万円、決算額は２,３９７万６,０００円です。委託先は、日建設計に委託しております。","voiceIndex":37,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"この庁舎の建替えについて、日建設計に委託し、１,５００万円の予算に対して、ご説明ですと、決算額は２,３９７万円に膨れ上がっております。なぜなのか伺いたいと思います。この報告書の内容ですけれども、仮の規模などありますが、今の説明ではよくわかりません。何ページ分あるのか、目次には何と書いてあるのか、その報告書を公開していただきたいと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"この決算額が増えたことについてですが、これはやはり広町地区、５ヘクタールほどを想定しながら、今、ＪＲと検討方針の協定を結んでおりますけれども、さまざまな検討をしなければいけないです。","voiceIndex":39,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"区が２,３９７万円の税金を使って作った２００ページほどの報告書が、なぜ公開できないのかと思います。まさに２,０００万円の報告書は区民の財産です。なぜ見せられないのか、改めて伺います。庁舎の建替えについて、それを公開しないということは、計画当初から住民参加、議会の関与を否定するものだと思いますが、現段階で公開できないというのであれば、いつの段階で公開するのかあわせて伺います。","respondent":"稲田都市開発課長","answer":"広町地区、ＪＲの社宅跡地、区有地も含みます。そういうところにおきましては、しっかりと広町のまちづくりをやっていきたいというふうに考えて、現在、検討を進めているところです。","voiceIndex":41,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"隣の広町地区の開発とは切り離して、住民参加をしっかり位置づけて、この庁舎は区民のものですし、情報も区民のものです、ぜひその資料は公開するよう強く求めたいと思います。ならば、同性カップルも使用者資格の対象にすべきだと思いますが、いかがでしょうか。あわせて、２３区で区営住宅の入居対象に同性カップルを認めている区がありますが、他区の状況も伺いたいと思います。","respondent":"森住宅課長","answer":"同性カップルについては、親族関係が確認できないことから、現在、入居を認めておりません。他区の状況につきましては、渋谷区、世田谷区、文京区などで、それぞれ区営住宅への入居を認めている区があります。","voiceIndex":43,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"同性カップルは親族関係が認められないというのは、あまりにも偏見だと思います。同性カップルも事実婚として認めない理由は何か伺いたいと思います。事実婚であっても、異性カップルは認め、同性カップルは認めないというのは、なぜなのか伺いたいと思います。","respondent":"森住宅課長","answer":"親族の要件といたしまして、婚姻というふうに示しております。これにつきましては、民法や戸籍法に基づきまして、住民票に記載されているものをこちらとしては確認しています。同性カップルにつきましては、親族関係が確認できないというところで認めているものではございません。","voiceIndex":45,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"事実婚も届出を出した結婚も、どちらも２人の合意です。そういう意味では、同性カップルについて婚姻が認められないというのは偏見だと思いますが、いかがでしょうか。","respondent":"森住宅課長","answer":"事実婚につきましても、戸籍住民課窓口での申し立てに基づきまして、住民票に未婚の妻、未婚の夫というふうに書かれるですので、そういった意味で、区としては事実婚についても入居要件として認めているところです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"この規定の歴史的な背景は、親が決める婚姻から当事者２人が決めるとの変更ですので、両性が男女を示すものではなく、あくまで２人の合意との見解があります。実際の社会には、同性カップルが存在しているわけですから、区が同性カップルを対象にしないのは、性的指向を理由にした差別です。性的指向を理由にした差別をなくすというのが品川区の立場ではないのか伺います。","respondent":"森住宅課長","answer":"区営住宅の入居につきましては、そういった具体的な展開の１つとして、また検討していくものかと考えておりますので、関係所管と協議を進めながら、そういった対応を進めていきたいというふうに考えております。","voiceIndex":49,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"慎重に議論していきたいとのご答弁でありますけれども、同性カップルについて、住宅の確保は深刻な悩みです。ぜひ品川区自身も、アンケートなどをとって、今どういう状況に置かれているのか、どこに困難を抱えているのか、ぜひアンケートをとっていただきたいと思いますが、いかがでしょうか。差別をなくし、同性カップルも対象にすることは、住宅施策の大事な要だと思いますけれども、いかがでしょうか。","respondent":"森住宅課長","answer":"そのような議論を進めながら、区として１つの具体的な展開として、性的マイノリティの方への区営住宅の入居も１つ議論になるのかというふうには考えております。","voiceIndex":51,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"さまざまな声も聞いていきたいということですけれども、世田谷区でも住宅や暮らしに関するアンケートを集め、自治体の計画へ民意を反映しております。ちょうど第５次男女共同参画のマイセルフ品川プランの素案も発表されました。ぜひ同性カップルの区営住宅への対象拡大を強く求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-025"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私から３点お伺いしていきたいと思います。例えば、道路の構造上の課題、１７２ページの道路安全施設費には、区画線や道路反射鏡などの道路に付随したものはありますけれども、実際、構造上の改良は、道路課と交通安全担当と連携されてしっかりやられているのかどうなのか、具体的に交通安全を目的に道路や路面改良を行った事例があるかどうかを教えていただきたいと思います。","respondent":"今井土木管理課長、古郡交通安全担当課長、多並道路課長","answer":"公有地管理事務の測量委託についてですが、これは例えば法定外公共物などの売り払いに先立ちまして調べるものでしたり、あとは、さまざまに公園と道路。このほかにもさまざまなキャンペーンを実施しておりまして、その中で交通事故の悲惨さ、被害者の状況だとか。実際の管理としましては、今、委員からお問い合わせがありましたような状態がありますので、品川区民から問い合わせ等があれば。","voiceIndex":55,"id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問・要望","question":"用地管理に関しては、３社で区内業者が１社ということでありますが、以前にも多少、私が触れさせていただいたのですが、品川区内の土地家屋調査士の品川支部としっかり連携をとられたほうがいいのではないですかという部分を申し上げたいのですが、実際、そのような連携をとることはされているのかどうなのか、もし別の部分でされているのであれば、その業務内容を教えていただきたいと思います。","respondent":"今井土木管理課長、古郡交通安全担当課長、多並道路課長","answer":"公有地管理におけます土地家屋調査士との連携ですけれども、この公有地管理の中では契約の中に土地家屋調査士も単体で契約していただくことは可能ですので。その中で危ないところは、看板を設置したり、道路改良したりと、いろいろな部分でやっておりますけれども、今後も引き続き、児童・生徒の事故がないように。そのような観点がありますので、今後も隣の区とはよく連携を図りながら、その状況を伝えながら、また適切なタイミングで補修等を行うよう伝えながら。","voiceIndex":59,"id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"土地家屋調査士に関しては、しっかり連携をとっていただきたいと思います。ヒヤリハット地図というすばらしいものがあるわけですから、しっかりその辺は未然に事故を防ぐように努力をしていただきたいと思います。大田区とか区界に関しては、連携というか、それをはるかに超越した仕組みとか、そういうものも考えていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"１７９ページの天王洲公園改修工事ですけれども、平成２９年度の監査結果において工事監査の結果が書かれていますけれども、天王洲公園のＡ・Ｂ面の改修工事が監査対象になっているのですけれども、改めてこの工事を監査の対象にした経緯と、監査の結果について教えていただけますか。","respondent":"小川監査委員事務局長","answer":"委員ご指摘の天王洲公園を対象とした理由ですが、野球、サッカーをはじめとした人気の公園において、Ａ・Ｂ面が人工芝の張替えを行いまして、東京２０２０大会に向け、さらなる区民の利用に供するということで監査対象といたしました。","voiceIndex":65,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"その監査結果を受けて、所管の課はどういうふうにこれから考えてやっていくのでしょうか。それと、スポーツの面からも、監査を受けて所管はどういうふうに考えているのか教えてください。","respondent":"溝口公園課長","answer":"そういった中で監査を受けておりますので、今後も公園内のスポーツ施設の適正な維持管理、または時期を見た適正な改修、そのようなものをすることによって、区民だけにとどまらず、スポーツの推進に公園課としても取り組んでいきたいというふうに考えているところです。","voiceIndex":67,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"次、１８３ページの耐震改修についてお伺いするのですけれども、私は、９月に区民委員会の視察で北海道に行ってまいりました。だからこれからそれに対してやっていこうという形になっていると思うのですけれども、もし家屋が倒壊して、その場にいた方がけがをしたり、最悪の場合は、もし亡くなってしまったりしたら、誰が賠償責任というのでしょうか、損害に対しての責任を負うのでしょうか。教えてください。","respondent":"長尾建築課長","answer":"その際に、所有者または使われている方が、どの程度維持管理を適正にしているか、そのような点を含めての責任の所在の確認という話になると考えています。","voiceIndex":69,"id":"exchange-031"},{"speaker":"藤原委員","kind":"確認","question":"民法だと思うのですけれども、維持管理がちゃんと、ちゃんとというのは、しつこいですけれども、どこでどういうふうにするかわからないですけれども、天災でも自身が所有するもので被害に遭わせてしまったら、所有者に賠償責任が来るということを、ある意味、はっきり区民の方にお知らせをしていかないと、行政としてはいけないのではないかという思いもあるのですけれども。","respondent":"長尾建築課長","answer":"建物や塀の維持管理に関する部分につきましては、まず１つとしては、建てる際に法令をきちんと守ってつくっているかどうかというところがあると考えます。","voiceIndex":71,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"やはりここは、だから木造密集でもやっていたり、木造が多いわけですね。だから施策として応援しているわけですね。現実には、維持管理をしているお宅は少ないと思う。だけれども、いつ起きるかわからない地震で、そのような事故が起こることはもちろん望んでいないです。しつこいですが、私は、天災ならそういうふうに賠償責任はいかないと思っておりましたので、もう１回答弁をお願いします。","respondent":"長尾建築課長","answer":"適切な維持管理の内容につきましては、法令等で具体的にそこまで示されているものではありません。所有者個人の方からしますと、建物につきましては、かなり専門的な部分も出てきますので、全てご自分で確認するというところは、現実的にはなかなか難しい部分もあるかと思います。","voiceIndex":73,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"１８１ページ、４項都市開発費４目都市開発費の都市防災まちづくり事業費、１７１ページ、１項土木管理費１目土木総務費、駅周辺等放置自転車対策事業について伺います。先ほどもありましたが、私も北海道胆振東部地震を体験したことから、防災まちづくりの観点で質問をします。１点目は、どのような方法で配布しているのか。２点目は、配布対象となる件数と、実際に配布された件数を伺います。","respondent":"古巻防災課長","answer":"２０１７年度というようなことで今お話をいただきましたけれども、２０１７年度につきましては、戸別配布ということではなくて、このハンドブックにつきましては、マンションの防災対策アドバイザー派遣事業の中、それから、住宅課のほうで実際に行っている事業ですけれども。","voiceIndex":76,"id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"以前、「わが家の防災ハンドブック」が全戸配布されましたが、高層マンションは、居住者が高層マンション特有の対策を意識する必要がありますから、全戸配布の仕組みを検討されるべきと考えますが、区の見解を伺います。お知らせください。高層マンション以外の集合住宅でも、「高層マンション防災対策の手引き」、ハンドブックが居住者の全ての方にわたる仕組みとなっているのか確認をさせてください。","respondent":"古巻防災課長","answer":"今後の各戸配布に関しましては、防災対策に関しての一般的な冊子になりますけれども、「わが家の防災ハンドブック」、これは今年度改訂を進めておりまして、当然、マンションに関する在宅避難の考え方であったり、さまざまなマンションに関することについても触れておりますので。","voiceIndex":78,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"新規入居があったときにも、必ず住居者の手に渡る仕組みをぜひ持っていただきたいと思うのですけれども、見解を伺いたいです。「高層マンション防災対策の手引き」の１９ページでは、「トイレの水を流すのは安全確認がされてから！その方たちと意思疎通ができるよう、コミュニケーションボードなどのツールを検討し、管理事業者と共有することも必要だと考えますが、何か検討されているのか伺います。","respondent":"古巻防災課長","answer":"コミュニケーションツールに関しましては、これはマンションに限らず、災害があった際に、外国人対応ということは必要なことと考えておりますので、今現在、不十分な面もありますけれども、こういった形で外国人の方々の課題も出てきておりますので、今後。","voiceIndex":80,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ全庁的に取り組んでいただきたいと要望いたします。防災ではなく、発災後の話になりますが、公衆電話について伺います。ＮＴＴに伺ったところ、品川区内の公衆電話の設置数は３９０台で、うち屋外は２１９台ということです。災害の備えとして、品川区が一部の補助金を出すなどして、ＮＴＴに協力要請をして増設に向けた協議をぜひ進めていただきたいと考えますが、見解を伺います。","respondent":"古巻防災課長","answer":"品川区におきましては、そのようなこともありますので、避難所に災害時には使えるようにということで、災害時優先電話を５台ずつ備蓄をしておりまして、災害が起きましてからＮＴＴに要望して、避難所でそのような電話を使えるような体制をとっておりますので。","voiceIndex":82,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"そのような形でＮＴＴに協力を要請して増設に向けた協議をぜひ改めて進めていただきたいと思いますが、見解を伺います。次に行きます。駐輪場について伺います。駐輪場を新たに設置するときや、古くなった駐輪場の改修時、システム変更で改修になるときには、幅やラックの高さを現在の自転車に見合ったものに変更するよう求めますが、見解を伺います。","respondent":"古巻防災課長、古郡交通安全担当課長","answer":"公衆電話を増設するということでの連絡手段の確保ということについては、１つの考え方ではあるかと思いますけれども、区といたしましては、被災時に安全が確実に確保できる場所ということで、避難所での設置を進めているところですので。私から、品川区営の自転車等駐車場の関係でお答えします。区営の駐輪場に関しては、平成２９年度、ラック幅の変更ということで、３０cmだったものを４０cmから６０cm、電動アシスト車に対応できるような形で全て改修をしています。","voiceIndex":84,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"区では、在宅避難を勧めていると思います。なので、避難所で設置されている電話を使ってほしいというのは、ちょっと区の方向性と違うのではないかということを思います。公衆電話は本当に必要だったのです。実体験として語っています。放置自転車対策についても伺います。武蔵小山駅周辺まちづくりビジョンでは、区は自転車の利用について、推進する方向なのか、抑制する方向なのかお答えください。","respondent":"古郡交通安全担当課長、古巻防災課長","answer":"今現在、近い方は歩いてきてくださいという方針でいるところです。在宅の避難の方につきましても、例えば物資の配給場所については避難所になってきますし、情報も避難所に多く集まってくるというふうに考えておりますので、そういう意味で。","voiceIndex":87,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１７１ページ、駅周辺等放置自転車対策事業と、道路占用許可にそれぞれ関連して質問をまずします。１７７ページ、景観まちづくり推進事業、天王洲地区についてお伺いいたします。せめて民間の駐輪場が多く設定している１日１００円ぐらいに１日利用料金を値下げしてはいかがかと。料金の再検討をされてはいかがかと思っておるのですけれども、区のご見解をお聞かせください。","respondent":"古郡交通安全担当課長","answer":"区の駐輪場は、通学・通勤といった長時間を利用していただく方を対象としておりまして、短時間の買い物はこういった民間の方をご利用いただく、民間ですと、最初の２時間は無料なのですけれども、それに１時間ごと５０円だとか加算されていくものですので。","voiceIndex":91,"id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。それが多分、区民に伝わっていないから、民間に比べて割高感を、１日料金については感じてしまうことになっている原因かと思うのですけれども、その点、今後の区民への説明、周知という点は、どのようにお考えでしょうか。","respondent":"古郡交通安全担当課長","answer":"その辺の広報関係につきましては、ホームページ等を含めて広報啓発を行っていきたいと考えております。","voiceIndex":93,"id":"exchange-041"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり区民生活に一番密着した自治体の公共サービスなので、やはりそうした公共の、品川区の区営の駐輪場は高いのかという疑問を区民に抱かれないような方策を今後しっかり行っていっていただきたいと思います。続いて、道路の占用許可に関連して質問します。例えば、１０時以降にやっていただくとか、また土日の活用などをやっていただきたいのですけれども、その点はいかがお考えでしょうか。","respondent":"古郡交通安全担当課長","answer":"工事に関しましては、道路使用許可ということで警察のほうで許可をしているものでございまして、警察では、時間帯とか、早朝からやらないように指導していて、実施許可は８時半ごろから出していると思うのですけれども。","voiceIndex":95,"id":"exchange-042"},{"speaker":"筒井委員","kind":"意見","question":"個別の案件でそれぞれ対応されているということなのですけれども、そうであるならば、やはり狭い道路でそうした作業をやって停車する場合は、渋滞等を考慮していただいて、なるべく一般の方の通行の妨げにならないような配慮をお願いしたいのですけれども、その点のお考えをお聞かせください。","respondent":"今井土木管理課長","answer":"土木管理課におきましては、道路工事調整協議会という形で、いわゆる水道、ガスなどの占用企業者または区関係の企業者等と、どのように道路を使っていくかということを年４回協議を進めております。そういった中で、そのような確認事項については徹底していきたいと考えています。","voiceIndex":97,"id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひよろしくお願いします。それはすなわち、天王洲に来訪される方は、やはり周辺の隣接地域、例えば、東品川一丁目や東品川三丁目、最近では東品川五丁目にも大規模なマンションが建ちましたけれども、そうした隣接地域の区民の声もしっかりと聞いていただきたいのと、こうした景観まちづくりをやっていますという周知をもっと行っていっていただきたいのですけれども、その点、いかがお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"さらには、つくり上げていく過程では、広くパブリックコメント等を行いながら、より多くの方の声をお聞きして、重点地区化に向けた検討を進めてまいりたいです。","voiceIndex":99,"id":"exchange-044"},{"speaker":"筒井委員","kind":"質問・要望","question":"なぜそう思ったのかというと、「天王洲景観まちづくりＮｅｗｓ Ｖｏｌ.０１」で、アンケート結果があると思うのですけれども、「いつまでも住んでいたい街」という項目で、居住者は「そう思う」が７６.５％、事業者の方が１３.３％と、当たり前かもしれないですけれども、事業者の方はどうしてもモチベーションが低くなってしまうので、できるだけ実際に居住されている区民の声。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"成果報告書１７４ページ、道路新設改良費、大井町駅周辺バリアフリー工事費、１７９ページ、公園新設改良費の中の八潮北公園改修工事についてお伺いしたいと思います。これ、シナモロールのデザインのマンホールの蓋です。これが大井町駅のイトーヨーカドーのところに設置され、私もデザインの確認をさせていただきました。これ、非常に見やすいところですので、私も評価をしております。","respondent":"多並道路課長","answer":"問い合わせにつきましては、マンホール自体のお問い合わせというよりも、今多いのが、それに伴うマンホールカードの発行があるのかないのかという形のお問い合わせが、道路課のほうもそうですけれども、観光協会のほうにも来ているということで、そのような中で認識しています。","voiceIndex":103,"id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"意見","question":"事務事業概要を拝見しますと、平成３０年度は３カ所設置ですという記載があったのですけれども、これはいろいろ規制とかもあると思うのですけれども、平成３０年度中にまだ設置の予定があるのかないのかというところと、あと、マンホールカードはどれぐらいの配布数を見込んでいるのか、あるいは、あとは道路課のほうで配布をするのか。","respondent":"多並道路課長","answer":"マンホールカードにつきましては、もともと２,０００枚を予定したところでしたが、発行元といろいろ調整した結果、もう少し発行できるということで調整が整った関係で、いろいろ予算を流用させていただいて、今、６,０００枚ほどを予定して。","voiceIndex":105,"id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。どうもありがとうあります。続きまして、１７９ページ、八潮北公園改修工事に関連しまして、昨年の１１月２０日にオープンしましたスケートボード場についてお伺いしたいと思います。そこで、約１年たった中で、平成２９年度は１,１３９回というところで、区としては、スケートボードの愛好者の方を、今現在、どういうふうにお考えになっているのかというところをよろしくお願いします。","respondent":"溝口公園課長","answer":"そのような中、さまざまスケートボードの競技の拡大、そういったところに取り組んでいる中で、利用者が増えてきているというふうには感じておりますが、まだまだ利用者数は伸びる可能性があると考えていますので、私どものやっておりますスケートボード教室。","voiceIndex":107,"id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"あそこは自動販売機があるのですけれども、売店とかがないというところで、公園の管理上でいろいろ検討していただきたいというのが、区の駐車場、あるいはタイムズの駐車場の中に、移動販売車とか、定期的に月に２回とか、そういうことも検討の余地があるのかと思っているのですけれども、その辺のところをお聞きしたいと思います。よろしくお願いします。","respondent":"溝口公園課長","answer":"利用者のサービス向上について、ケータリングとか、そのようなものの導入を含めて、立地場所等、クリアしなければいけない課題等があると思いますが、さまざま検討して、運動施設としてより充実した施設にしていきたいと考えているところです。","voiceIndex":109,"id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"１７１ページ、交通安全啓発費、１８３ページ、住宅費、１７７ページ、治水対策費、１７９ページ、公園新設改良費について伺いたいと思います。その上で、ヒヤリハット地図ですが、それは反映していただく頻度は、どういうタイミングでやられるのか教えてください。","respondent":"古郡交通安全担当課長","answer":"ヒヤリハット地図に関しては、年１回、各小学校や新聞配達の業者だとか、高齢者クラブ等に調査をかけまして、１年間に１回、結果を反映しています。反映したものを地図とホームページ等で公開しております。","voiceIndex":112,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"年１回ということで、年間を通してさまざまなそうした、そういうことがなければいいのですが、交通事故とか、危ない思いをしたというようなところが、年１回ということで反映されるわけですが、先日も総務費のところで確認をさせていただいて、いろいろな各小学校のＰＴＡの方とかを中心に、ヒヤリハット地図、学校でももちろん児童生徒に対して、また保護者がそうした形で活用をいただいて対策をされている。","respondent":"古郡交通安全担当課長","answer":"今後も引き続き、こういった形で実施していきたい、検討していきたいと考えております。","voiceIndex":114,"id":"exchange-051"},{"speaker":"つる委員","kind":"提案","question":"住宅費について伺っていきたいと思います。住宅費の中で、これはずっと会派としては一番最初に提案させていただいたのは２０１０年、ちょっと間をあけて２０１５年に私が取り上げさせていただいて以降、会派で本当にこうした委員会等で設置を求めてきた居住支援協議会について伺いたいと思います。","respondent":"森住宅課長","answer":"東京都および先進他区へヒアリングを行いまして、情報収集を進めておりまして、今後、設立に向けて具体的に進めてまいりたいと考えています。","voiceIndex":116,"id":"exchange-052"},{"speaker":"つる委員","kind":"質問","question":"それがあって、どれだけ進むのかというのはまた別だと思うのですが、逆に言うと、それを設立したことによって、しっかりと品川区としてこれだけ住宅施策、特に高齢者の住まい、地域包括ケアと言われている中で、基本は在宅なのだと言っている中で、では、その住まいはどうなっているのだというところでは、非常に居住支援協議会、しっかりと実効性のあるものにしていただくことによって。","respondent":"森住宅課長","answer":"孤独死された方の対応ですけれども、昨年度は２件ほど実際に区営住宅の中でお亡くなりになられたという方がおられました。その方々につきましては、基本的には相続人の方だとか、親族に引き取りをしていただいて、家財の処分をしていただいたです。","voiceIndex":118,"id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"昨年度だと２件ということで、ただ、その上で、過去に区が家財処分をしたというケース、財産放棄をされたので区のほうで処分したということがあると思うのですが、その際は、どういう根拠に基づいて区が家財処分ができたのかということを教えてください。","respondent":"森住宅課長","answer":"基本的には、今、公営住宅法や民法の規定に基づきまして、そのときそのときの判断でやっているというところが１つですけれども、こういった家財処分につきましては、件数が少ないというところもありますので、１件１件。","voiceIndex":120,"id":"exchange-054"},{"speaker":"つる委員","kind":"質問","question":"そうすると、たしか２０１７年１月２５日に国土交通省から、「公営住宅における単身入居者死亡後の残置物への対応方針の策定について」ということで、おそらく都道府県を通じて各市区町村に通知をされた、対応方針がなかったので明文化されたというものだと思うのですが、それが出た後の対応だったのか、それの前だったのかというのは結構ですが、例えば区営住宅の場合は。","respondent":"森住宅課長","answer":"高齢者地域支援課で進めております住宅生活支援サービス事業につきましては、事業を進めるにあたりまして、住宅課、あるいは住宅課と日ごろおつき合いのあります宅建業界だとかともヒアリングを行いながら進めてきたところです。","voiceIndex":122,"id":"exchange-055"},{"speaker":"つる委員","kind":"確認","question":"事務事業概要を見ると、住宅課のところでは、空き家対策事業とか、都市計画法に基づく開発許可が他課との連携ということで一覧があるのですが、この事業も、もう１回確認ですけれども、他課との連携事業のうちの１つということでよろしいでしょうか。","respondent":"森住宅課長","answer":"事務事業概要のほうには具体的な記載はしておりませんけれども、今後進めていきます居住支援協議会も含めまして、福祉部、高齢者地域支援課とはしっかりと連携していきたいというふうに考えております。","voiceIndex":124,"id":"exchange-056"},{"speaker":"つる委員","kind":"質問","question":"だけど、今回、１５万円とか、１７万円、２０万円の金額が、年間所得約２５７万円以下の方が対象の中で、１５万円という金額を貯蓄するのがどうなのか、月換算は２１万円ぐらいですから、これまでの生活にもかかわってくると思うのですけれども、例えばそれよりも所得の低い方たちが、先日の質疑の中では１６０件相談があって、５件進めて、１件がまだ継続中と。","respondent":"森住宅課長","answer":"住宅課を中心としまして事務局となって協議会の設立に向けて動いているところです。その中でも支援サービス事業を１つのスキームとして、課題とか対応策について検討していきたいというふうに思います。","voiceIndex":126,"id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"私は、成果報告書の１８０ページ、都市開発費の中の五反田地区コーディネート業務委託にかかわって、旧第一日野小学校跡地について伺います。この土地は、現在、品川区からＴＯＣに貸し付けられています。この契約の起点は２０１２年９月６日ですから、この８年が経過するまでには、もう２年を切りました。そこでお伺いします。お伺いします。","respondent":"柏原企画調整課長","answer":"この跡地の関係ですけれども、我々といたしましても、そういった期限がある中で、その後の活用についてはどのような活用ができるのかというのは、内部的にはどのようなことができるかというのは検討に入り始めているといったところです。","voiceIndex":129,"id":"exchange-058"},{"speaker":"おくの委員","kind":"質問・要望","question":"ここでのそういう整備をしてほしいということは、私たち日本共産党としては、委員会等の場で伝えてきました。こういう近隣住民の方の要望を、区としてもアンケートで聞いたり、あるいは、そういう近隣住民の方が参加した検討会を立ち上げるなどの住民参加でこの土地の本格活用、利用を進めるような、そういう準備に着手すべきではないかと私は思うのですけれども、その点、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"いろいろな跡地の活用の検討というところには段階があるのだと考えています。そのような中で、このような契約の期間を見ながら、まずは区としてどのようなことができるのかというところを考えなくてはいけないという段階であろうと考えています。","voiceIndex":133,"id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"やはりもともと小学校だった土地で、まさに区民の財産ということですから、やはり住民参加で、ぜひこの土地が返ってきた後の本格活用の方向性を決めていっていただきたいと思います。この点、強く要望しておきたいと思います。ですから、私としては、これまで以上に強く８年間での返還を迫る交渉をこれからはしていくべきではないかと考えますけれども、その点、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"ＴＯＣのほうからは、建替えに関しましては、建替えの意思はあるというふうに今でも聞いてあります。オリンピック等が開かれる中で、その工事の関係で、人員であったりだとか、重機械の手配が難しいであったりとか、さまざま理由があるというふうには聞いてあります。","voiceIndex":135,"id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"その建替えの意思はあるというのが、常識的に見ますと、口先だけのような気もするのです。もし口先だけ、建替え目的というのが、どうも常識的に見て口先だけのように見えるという場合、つまり、建替え目的が失われてしまっているのではないかという場合には、この契約を民法の債務不履行で解除するというようなことは、法的には絶対に不可能なことなのでしょうか。この点、お伺いいたします。","respondent":"柏原企画調整課長、稲田都市開発課長","answer":"契約のところだけでいいますと、どの部分をもって債務不履行かということがあるのですけれども、ＴＯＣが建替えをしなかったというところだけでの契約不履行は法的には難しいだろうというふうに。ここの開発計画につきましては、一時期、協議してきたところですが、また最近、協議してきているというところで、都市計画手法等を使って建替えをやりたいというようなことで相談に来ているところです。","voiceIndex":137,"id":"exchange-061"},{"speaker":"おくの委員","kind":"質問・要望","question":"とにかく本格活用に向けて、いろいろ区としても準備を進めていくことを強く求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-062"},{"speaker":"木村委員","kind":"確認","question":"１７１ページの中ほど少し下にあります交通安全啓発費からの質問です。皆さんに理解と協力をお願いし、車や自転車を運転している人には十分に注意をしていただくこと、歩行中の人には、よく周りを確認して歩行してくださいとのお願いだと思います。お聞きいたしますけれども、事故件数の数は減ることは大変すばらしい喜ばしいことであると思います。","respondent":"古郡交通安全担当課長","answer":"一時不停止だとか、交差点の安全未確認だとか、信号無視、このようなものが多くなってきております。そのような中で自転車の安全教育はやはり必要不可欠だと考えていますので、今後も引き続きやっていきたいと考えています。","voiceIndex":143,"id":"exchange-063"},{"speaker":"木村委員","kind":"質問・要望","question":"本区でも多くの区民が自転車を利用し、日々活動をしておりますけれども、自転車事故が大変多く発生していると考えています。注意をすると、返答はなく、ぶつくさと言いながら去っていく、最悪の場合には逆に文句を言う人がいます。こういう場合の対処の仕方によい方法はないでしょうか。あれば参考にさせていただきたいと思います。","respondent":"古郡交通安全担当課長","answer":"本課では、自転車安全利用キャンペーンを実施しておりますので、安全教育をしっかりしていく、そうしていくことによって減少していく、そのように考えております。","voiceIndex":145,"id":"exchange-064"},{"speaker":"木村委員","kind":"質問","question":"本当に十二分に気をつけなければなりませんけれども、自転車は今言ったように、大変簡単である、いざとなれば周りが、また相手がよけてくれる、だから自分さえ注意していれば大丈夫と考えて心に油断ができてしまうものだと思います。お聞きいたしますけれども、もっと自転車事故の怖さを伝えていくには、どのように区民に周知、指導されるのでしょうか。","respondent":"古郡交通安全担当課長","answer":"区内では、スケアード・ストレートをやっておりまして、スタントマンを活用して、自転車事故の悲惨さを植えつけて、こういう運転をすると、このような事故になるということをさらに啓発しながら、さらに実施していきたいと考えております。","voiceIndex":147,"id":"exchange-065"},{"speaker":"木村委員","kind":"質問・要望","question":"今、学校でも自転車の乗り方を児童には大変厳しく教えているかと思いますけれども、今の子どもたちが、本当にそういう意味では、大人に成長するのにあわせて、善悪はしっかりと身につけていかなければいけないのですけれども、今の子どもたちは、そういう面において、私たちの子どものころとは違って、本当に屁理屈っぽくなっている子どももたくさんおりますし。","respondent":"大関教育総合支援センター長","answer":"そのほかヘルメットの着用を全児童に呼びかけて、家庭にも働きかけているところです。引き続き、交通安全教育に区立学校では努めてまいります。","voiceIndex":149,"id":"exchange-066"},{"speaker":"木村委員","kind":"質問","question":"ぜひお願いしたいと思います。お聞きいたしますけれども、保護者の方は、１３歳未満の子どもは、今言われたように、自転車に乗車するときは、ヘルメットを着用させるよう努めなければなりませんけれども、これからは高齢者の方々に対してもヘルメット着用を義務づけるというか、何かそういうことは可能でしょうか。","respondent":"古郡交通安全担当課長","answer":"高齢者に関しては、なるべくヘルメットを着用するように、高齢者交通安全講習会だとか、さまざまな場面で必要性を訴えているところです。今後もそのような活動をしていきたいと考えています。","voiceIndex":151,"id":"exchange-067"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は、１項の土木管理費で、１７１ページの屋外広告物等実態調査、それから４項都市計画費の都市計画総務費関係と、都市開発費の広町地区整備検討委託でお聞きしたいと思います。最初に、屋外広告物等実態調査に関してですが、これが１,９００万円ぐらい出ている、これについて細かく教えてください。それから、都市開発関係です。広町の関係です。","respondent":"今井土木管理課長、稲田都市開発課長","answer":"屋外広告物等実態調査に関してですけれども、平成２９年度の決算ですが、平成２９年度、平成３０年度の２カ年で区内全域を対象に、申請が必要な壁面の看板や屋上看板。それには４つほど主な部分を挙げたのですけれども、道路などの基盤施設の整備、土地の再編、歩行者ネットワークの整備、賑わい創出や防災機能を持つ広場の整備ということで。","voiceIndex":154,"id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その中に結構厳しいものというか、条例は知っているのだけれども、本人からすると、ちょっときつめの表現がすごく出されていたので、今まで何の指摘もなかったのに、急にどうしてしまったのかという話だったので、今すでにやったところはやむを得ないのですけれども、これから荏原地区をやっていく中で、何かもうちょっと事前に話ができないのかと、その辺が疑問があったので、それを教えてください。","respondent":"今井土木管理課長、稲田都市開発課長","answer":"こちらの調査の周知といたしましては、商業・ものづくり課で発行しております「しながわ産業ニュース」ですとか、中小企業支援ウェブマガジン等でもお知らせし。７月３日に建設委員会がございまして、そちらで検討方針の図面等をお示しさせていただいたところなのですが、あくまでも道路の点線ですが、既存の補助２６号線。","voiceIndex":160,"id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"広町地区、前に１つ、古いものを見つけました。もう１点、これは報道が出ている部分で、都市計画総務費のことで確認するのですけれども、京浜急行が１２０周年で駅名を変えるということが出てきています。区内に６駅あって、もし駅名が変わると、区の資料などの修正で、ほかの自治体も全部そうですけれども、相当な負担が出てくると思うのですけれども、こういうときは費用負担は区で持つものなのですか。","respondent":"鈴木都市計画課長","answer":"現在、１２０周年記念ということで、京浜急行電鉄がこの駅名変更の募集を行っておりまして、募集期間は既に済んでおります。これは事前に都市計画課も情報提供いただきまして、基本的には、例えば鮫洲駅などは公共施設があるということで変更しない。","voiceIndex":163,"id":"exchange-070"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"地域の方が相当気にしているところなので、情報が入り次第教えていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ほかの区についても大体これと同じつくりのリーフレットになっています。もう１つ特筆すべきこととしては、加入の窓口についてです。品川区では、この１年間、研究を進められてきたかと思うのですけれども、少額の保険料で交通事故によるけが、そして万が一、自転車事故での加害者になってしまった場合の区民を守る事業として、この区民交通傷害保険の導入を再度要望いたしますが、いかがでしょうか。","respondent":"古郡交通安全担当課長","answer":"区民交通傷害保険につきましては、先ほど委員が指摘されたとおりです。区といたしましても、安価で補償も手厚いということで、前向きに検討していきたいと思います。","voiceIndex":167,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"実は私もなるほどなと思って聞いておりました。改めて伺いますけれども、そのときにご答弁の中では、「研究をしていく」というようなご答弁がずっと聞かれてきたのですけれども、区内に民間の井戸、生活用水、飲用以外の目的として活用いただける井戸が何本あるのか、研究をされてきた成果、今の到達度、もし防災担当課でわからなければ、土木担当、どこかのところで教えていただければと思います。","respondent":"古巻防災課長","answer":"民間の井戸の活用という観点ですけれども、区といたしましては、防災計画上におきまして、飲料水および生活用水の確保という観点でいいますと、民間の井戸については計画の中で活用という考え方はしておりませんで、民間の井戸を活用せずとも区の用意しました拠点。","voiceIndex":169,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ということで、お聞きしたとおり、数については把握をされていないということ、また、防災計画上は位置づけられていないということで、これは今までもご答弁がありまして聞いておりますけれども、研究はおそらく進んでいないのかというところが確認ができました。今、こういうふうな発信をされているのですが、この点について、防災担当課はどのようにお考えなのか伺いたいと思います。","respondent":"古巻防災課長","answer":"ただ、どうしても区内の湧水・地下水ということで申し上げますと、飲用には当然適してこないというところもありますので、使い方等、十分に注意をしていただくということで、区の震災用の井戸、３カ所につきましても。","voiceIndex":171,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"なぜ難しいのかというところ、それは理由がよくわからないので教えていただきたいということ。断水をした場合、これを飲んでくださいと言っているわけではないですから、生活用水として、先ほど課長からもご丁寧なご答弁があったように、生活用水としてみんなで地域の方で使えるようにしてほしい。検討していただきたいと思いますが、前段も含めてご答弁をお願いします。","respondent":"古巻防災課長","answer":"ですから、区として地域防災計画ありきとはお話しするつもりはないのですけれども、どのような形で活用ができるのか、活用についての支援をどのような形でできるのかということは、しっかりと受けとめて考えてまいりたいと思います。","voiceIndex":173,"id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"課長、これは意識の問題だと思います。区民の方から活用したいという声がある。これは一方ではそうかもしれないと思います。区民の命を守る自治体として、選択肢を増やしていただきたいというふうに思うのです。ですから、品川区役所として、品川区として、区民の声があるから、それは当然そうなのですけれども、そうではなくて、選択肢を増やしていただきたい。課長、もう１回ご答弁をお願いします。","respondent":"古巻防災課長","answer":"井戸についても同様かとも考えられますので、繰り返しになりますけれども、そのような形で区として支援ができるのか、そういうところも含めまして考えてまいりたいと思います。","voiceIndex":175,"id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今までの区議会でのご答弁、質問も含めてなのですけれども、質問もどうしても井戸に対しての補助ありきの質問が今まで多かったので、そうではないと思うのです。やはり登録して、皆さんで活用できる、こういうことを進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"１７３ページ、道路改良費、１７８ページ、北品川駅前広場整備等検討委託、１８０ページ、大崎駅周辺地区再開発事業について伺いたいと思います。道路改良費にかかわって、道路の改良といいますか、整備について伺います。地域の方から、高齢者の方など、「車両が通る際に危ない思いを何度もした、何とかならないでしょうか」という声も伺っております。","respondent":"多並道路課長","answer":"区としましては、先ほどご案内があったとおりの道路も含めまして、いろいろ周辺のまちづくりの動向を踏まえながら、より安全安心な形で開発の歩道上の空地の整備のあり方などを含めながら、いろいろ一緒に検討しながら進めているところです。","voiceIndex":179,"id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"区として、三菱ＵＦＪ銀行に働きかけて、地域住民の要望にこたえて、車と歩行者が安全にすれ違える環境を実現するための対策をとるよう求めたいと思いますが、働きかけはいかがでしょうかということと、また、必要であれば、区として一部用地買収も含めて、具体的にこの箇所について安全な歩行環境を実現するために知恵を絞っていただけないかと、行動するよう求めたいと思いますが、いかがでしょうか。","respondent":"多並道路課長","answer":"ただ、やはり会社の今後の利用の観点があるので難しいというお答えをいただいているところです。","voiceIndex":181,"id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"五、六年前にという話ですけれども、今、研修所が休止しているのが、平成２７年４月６日からということで、その後にこういった動きが新たに出てきているわけですから、ぜひ区として、少なくとも三菱ＵＦＪ銀行に、そのような地域の住民の声が上がっているということをお伝えいただいて、もう少し安全に歩行できるような配慮をいただけないかということで要請していただきたいと思うのですけれども。","respondent":"多並道路課長、東野まちづくり立体化担当課長","answer":"私からは、峰原通りの件ですが、委員のお話もありますように、これからこの土地で活用のあり方について、開発部門とよく連携を図りながら情報収集して、よりよい形で進めていきたいと思っています。今後のスケジュールですが、広場の説明会、都市計画審議会等々につきましては、まだ決まったスケジュールは立っておりません。今のところ、来年５月の都市計画審議会に向けまして、見直しの作業を進めているです。","voiceIndex":183,"id":"exchange-080"},{"speaker":"安藤委員","kind":"質問・要望","question":"清水横丁も残す。しかしながら、客待ちのタクシーや送迎車を国道に滞留させないために、清水横丁と並走する形で貫通道路を拡幅整備する」というふうに考えを示されたと伺っております。同時に、１２ｍの拡幅をしてしまうと、不要な立ち退きも発生させてしまいます。以上の理由から、見直しにあたっては、１２ｍの拡幅道路もしっかり白紙に戻すべきだと思いますけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"具体的な計画につきましては、今後、東京都ならびに警視庁等々との協議が詰まり次第、また区としての方針を決定次第、議会のほうにも示させていただきたいと考えています。","voiceIndex":186,"id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"区画街路も含めて見直し検討に入るということで、今、答弁されたように思ったのですが、もう一度伺いますけれども、清水横丁は守る、清水横丁の脇に、５月２２日には、課長が表明されておられましたが、並走する道路、清水横丁と並走する形で貫通道路を拡幅整備するとおっしゃっていたようですが、この貫通道路を整備しない方向も含めて検討するということなのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"地域から、また議会からも求められています西側、国道側への交通広場をというようなお声がありますので、その辺につきましても、あわせて今、検討しています。区画街路につきましても、このような交通結節としての機能が必要かどうかも含めまして、現在、検討をしています。","voiceIndex":188,"id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"最初に伺いたいのは、この地域で容積率とかをいくら緩和したとしても、航空法で定められている高さの制限があると思うのですが、航空法の最高限度がこの地域は何ｍになっているのか伺います。あわせて、この大崎駅西口Ｆ南地区で計画されている３９階建てマンションの高さは何ｍの計画なのか、まず伺います。","respondent":"稲田都市開発課長","answer":"航空法でこの地区は１５０ｍという高さになってあります。それから、３９階建てで、高さは約１４９ｍです。","voiceIndex":190,"id":"exchange-083"},{"speaker":"安藤委員","kind":"質問","question":"だから、結局、航空法のめいっぱいぎりぎりということですね。現在、３月に都市計画決定がされて、次の手続は、本組合の認可申請に向けた事業計画案の提出、公告縦覧かと思いますが、現在の進捗と事業計画の提出、公告縦覧の時期はいつごろを予定しているのか伺いたいと思います。あわせて、予定される総事業費、補助金投入額はおよそ幾らと概算しているのか、概算でいいのですが、伺います。","respondent":"稲田都市開発課長","answer":"昨年度末に都市計画の決定等が行われていた地区です。現在の進捗状況ですが、組合設立に向けまして、現在、準備組合が詳細を検討しているというところとあわせまして、権利者の１００％の同意を目指しながら、現在、その辺をやっているです。","voiceIndex":192,"id":"exchange-084"},{"speaker":"安藤委員","kind":"質問","question":"住民と準備組合の話し合いが何度かもたれていまして、私も参加したのですけれども、なぜ１４９ｍ、３９階建てでないといけないのかと聞いても、合理的な理由は説明されません。住民の皆さんは、住友不動産がもうけを最大限に上げるために１４９ｍになっていると思っていますが、そうなのですか、そうではないのですか、伺います。","respondent":"稲田都市開発課長","answer":"こういう中におきまして、居住環境等を必要としながらまちづくり進めるという中において、最終的に出てきた結果がこのような形で居住環境等をつくっていくです。","voiceIndex":197,"id":"exchange-085"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、結局、住友不動産のもうけをマックスにするためには１４９ｍのほうがいいわけですね。最大限のもうけを得るための１４９ｍになっていると住民の皆さんは思っています。そうではないのですかと聞いたので、お答えください。","respondent":"稲田都市開発課長","answer":"現状の道路が狭かったり、老朽化した住宅があったり、こういうところを解決しながらやっていくまちづくりを進めております。","voiceIndex":199,"id":"exchange-086"},{"speaker":"本多委員","kind":"質問","question":"１８３ページの建築行政費、がけ・擁壁安全化支援、１７６ページ、１７７ページの河川費について質問します。初めに、がけ・擁壁安全化支援ですけれども、平成２９年度の新規事業ということで、アドバイザー派遣１１件について、予算は２０件だったのですが、１１件の決算、これが工事の実施につながったのかどうかの状況を教えてください。","respondent":"長尾建築課長","answer":"がけ・擁壁アドバイザー派遣からの工事への進み具合というところです。先ほどご紹介いただきましたように、アドバイザー派遣としては、平成２９年度は１１件ございました。その中で実際の改修工事に進んだ件数としては、今のところございません。","voiceIndex":203,"id":"exchange-087"},{"speaker":"本多委員","kind":"質問","question":"工事の実施につながればと考えていますけれども、擁壁とかの所有者などへの技術的アドバイスを行う専門家を派遣するということですけれども、肝心の所有者がそういう問題意識を持つかどうか、先ほども家屋倒壊に関して、所有者についての質問がありましたが、全く同趣旨で、所有者の意識で、意外と所有者意識がなくて、ブロック塀についてだったり、大谷石だったり、擁壁だったり。","respondent":"長尾建築課長","answer":"所有者の問題意識の部分ですけれども、実際に住まわれている家については、やはり日常的に使っている、見ているというところで、問題意識も比較的高いと考えますが、がけ・擁壁に関しましては、なかなかそのような観点を持ちにくいのが現状だとこちらとしても認識しております。","voiceIndex":205,"id":"exchange-088"},{"speaker":"本多委員","kind":"質問","question":"たけうち委員の本会議の一般質問の中で、ブロック塀ですとか、危険なもの、倒壊に対する質問がありました。昭和５３年６月１２日に宮城県沖地震が発生いたしました。このとき、私、小学校６年生だったのですが、ものすごく衝撃を受けまして、よく覚えております。私、議員になりまして初めての一般質問で、ブロック塀をなくし、生け垣助成の推進と、軽量で耐震性に優れた新建材の推進を取り上げました。","respondent":"長尾建築課長","answer":"そのようなところの所有者意識をきっちりと持っていただくことと、あとは、危険な塀と思われるところの除却を区としても支援して、安全な通行の確保を目指したいと考えております。","voiceIndex":207,"id":"exchange-089"},{"speaker":"本多委員","kind":"質問・要望","question":"わかりました。倒壊の危険があるブロック塀は、全区的に対象にして除去につながるような方法をとっていただきたいと思うのですが、今も道路沿いというところで答弁がありましたけれども、避難道路沿いの危険なブロック塀、そのようなものはこれまでにも調査をして改善、改修を品川区としても呼びかけをしてきました。避難道路に直面する危ないブロック塀です。","respondent":"長尾建築課長","answer":"今回の大阪府北部地震が発生した後につきましては、避難道路というわけではないのですが、通学路に関しては、教育委員会のほうでも各学校に安全点検を緊急に実施したというふうに聞いてあります。","voiceIndex":209,"id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"次の質問に移ります。１７６ページ、１７７ページ、河川費ですけれども、品川区内にモノレールの橋脚は１７７本あります。橋脚自体は東京モノレールが自社で耐震性とか管理はされているというのは伺っておりますけれども、水辺空間という点から、品川区と東京モノレールとどういう話を持たれているのか、持たれていないのか、考え方等あれば教えてください。","respondent":"鈴木都市計画課長、持田河川下水道課長","answer":"今、景観という視点でご質問をいただきましたので、私からお答えいたしますが、水辺の利活用につきましては、区のほうでライトアップも含めてさまざまな取組みを進めてあります。橋脚のペイント等とはちょっと違う部分もありますが、そのような形で賑わいをつくっていこうという方向性はございまして、区としても、ライトアップの考え方を踏まえながら取り組んでいきたいというふうに考えてあります。","voiceIndex":211,"id":"exchange-091"},{"speaker":"本多委員","kind":"質問・要望","question":"その水辺にあわせまして、散策コース、遊歩道の整備にあたりましては、暗い部分への対策と、道路にＬＥＤを埋め込む整備の考え方を聞きたいと思います。そして、将来的には、理想的な要望なのですけれども、品川区と大田区の区界がないぐらいに、品川と大田と連携をした散策路ができればと理想を持っているのですが、まずは品川区内でのＬＥＤ埋め込みの整備の考え方はいかがでしょうか。","respondent":"持田河川下水道課長","answer":"海水の満ち潮時には、水がかぶるということも十分考えられるところではありますので、そういったところにライトを設置しても大丈夫かどうかというような視点での検討も必要だと考えています。","voiceIndex":214,"id":"exchange-092"},{"speaker":"本多委員","kind":"意見","question":"ちょっと時間があるので、最後に１つだけ聞きます。１７２ページの道路維持費です。擁壁修繕、西品川一丁目と上大崎三丁目で平成２９年度に実施されました。このやり方ですけれども、区内の、いろいろ条件とかあると思いますが、この取組みはどういうふうに展開していくのか、同じような状況があるのかどうかも、いろいろなケース・バイ・ケースだと思うのですが、この点についてお聞かせください。","respondent":"多並道路課長","answer":"今後、耐震工事等の必要性があった際は、現場の状況を踏まえながら、より区民の皆様が景観上好まれるような整備ができるところがあれば、そこはまたいろいろ検討していきたいと思っているところです。","voiceIndex":216,"id":"exchange-093"},{"speaker":"松永委員","kind":"確認","question":"私からは、成果報告書の１７１ページの駅周辺等放置自転車対策事業について、１７２ページの道路安全施設費について、１７６ページの河川、運河水質改善について、関連して１７７ページの水辺の賑わい創出構想検討委託について伺います。はじめに、１７１ページの駅周辺等の放置自転車対策についてですが、最近、ある方より、自転車を撤去されてしまったということを伺いました。","respondent":"古郡交通安全担当課長","answer":"保管所の関係ですが、不動前が１,５００台、八潮が４,５００台ということで、不動前が１,０００台、八潮が２,２００台程度、まだ十分空きがあるような状況になっています。","voiceIndex":219,"id":"exchange-094"},{"speaker":"松永委員","kind":"確認","question":"それを聞いて安心しました。先ほど、シェアサイクル事業の推進の中で、今後、いろいろ台数も増やしていく、サイクルポートも増やしていくということなのですけれども、確認ですけれども、撤去の台数の中にシェアサイクル等は含まれているのか、また今後、そういったところも増えてくるのではないかと思うのですけれども、そうしたときにはどのような対策をとられていくのでしょうか。","respondent":"今井土木管理課長","answer":"その場合には、自転車の所有者の方、ＧＰＳ機能や利用登録内容が確認できますので、事業者であるドコモ・バイクシェアからご本人に通知が行きまして、原則として利用者の方に３,０００円の負担をしていただくということになります。","voiceIndex":221,"id":"exchange-095"},{"speaker":"松永委員","kind":"質問・要望","question":"１７２ページの道路安全施設費について伺います。そうした中で、あそこは、どちらかというと、すぐ大通りがあって、その次に小さな通りがあってという、距離もそれほどないので、自動車が優先的になってしまって、信号機に間に合わないので、猛スピードで行くという車をよく見かけて、あそこの道路に関しては、ぜひ対策をとっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"多並道路課長","answer":"これについても学校と警察と一緒に現地を見ながら、またさらなる対策ができないかということで、今後もいろいろ検討してまいりたいと思っているところです。","voiceIndex":223,"id":"exchange-096"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひいろいろ対策をとっていただきたいのですが、城南信用金庫の前に関しましては、ぜひ一灯式信号機の設置を要望いたします。最後に、水質改善について伺いたいと思います。ほかの地区についても大腸菌数は１００ml当たり最大で８万個でした。そこで質問いたします。この調査結果をどのような原因でこういうふうな数字になったのか、そしてまた、なぜ減ったのかお知らせください。","respondent":"小林環境課長","answer":"引き続き、調査結果が高い状態となれば、関係課とか周辺区と連携を図りながら、その推移は見守ってまいりたいと考えています。","voiceIndex":225,"id":"exchange-097"},{"speaker":"たけうち委員","kind":"質問","question":"１０５戸の不適正管理ということと、特定空家１戸ということでございましたが、先ほどもありましたけれども、補正予算が成立すれば、１２月１日からブロック塀等の撤去費用の新しいスキームが始まるということなのですが、１０５戸の不適正管理空き家の中で、そうした危険なブロック塀があるのかどうか把握されているのかどうか教えてください。","respondent":"溝口公園課長、長尾建築課長、森住宅課長、小林環境課長、持田河川下水道課長","answer":"ある程度、ＪＲとの事前協議が整ってきているところから、今後、設計の契約に向けて、今、手続を進めていきたいと考えているところで。所有者の方にもお話を伺いながら、擁壁の現状の課題点であるとか、今後考えられる改修の内容であるとか。ブロック塀の状況が悪いというところも数件ありますけれども、それにつきましては建築課と連携しながら所有者に通知を行っているところです。それぞれ各所管での井戸の把握状況です。","voiceIndex":229,"id":"exchange-098"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いろいろなところがありますので、そういうところをぜひ横串を通して検討していただきたいと思いますので、これは要望します。これは要望で結構です。今後、補正予算が成立した暁には、ブロック塀が危険なところがあった場合には、所有者に対して個別に、ブロック塀だけではなくて空き家の管理も含めてなのでしょうけれども、所有者を調べてご案内をしていただけるかどうか確認をさせてください。","respondent":"森住宅課長、溝口公園課長","answer":"万一の災害時におきましては、同様の措置をとるということもありますけれども、それでも不足する場合は、耐震性とか、使えるかどうかという部分の確認は必要になると思いますけれども、民間住宅も含めて取り組んでいけるように。そのような中でいきますと、やはりＪＲのほうで責任を持ってつけていくというのが本来あるべき姿と考えておりますので、今後、公衆便所の改修にあわせて、ＪＲと協議を進めていく中で。","voiceIndex":236,"id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問・要望","question":"災害時の活用ということで、今、防災課長から答弁がなかったので、後でいただきたいと思うのですが、そういった面でいきますと、日ごろから住宅ということでいうと、オーナーの方と、不動産関係者の方とか、宅建とか関係団体の方との密接な連携の中でそのような自然なコンセンサスみたいな部分も含めて、いざというときにご協力をいただける体制をつくっていかなければいけないと思います。","respondent":"森住宅課長、古巻防災課長","answer":"地域の方々も入っていただいておりまして、空き家、広い意味で言えば、賃貸空き室も含めて、品川区内２万６,０００戸ありますけれども、そういったものの使い方については。補足的なお話になりますけれども、仮設住宅に関しまして、災害時の住宅のそのような関係につきましては、住宅課のほうで、一時的にはさまざまな窓口が設置されるかと思いますので、防災課としましても、住宅課と連携しまして。","voiceIndex":239,"id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問","question":"それぞれよろしくお願いします。ちょっと時間があるので、１７２ページの街路灯管理費の中で、今年度取り組んでいます災害時消えない街路灯整備についての今の進捗状況と今後の取組みの広がりみたいなものがあれば教えてください。","respondent":"多並道路課長","answer":"今年度、各学校避難所の出入口に１カ所ということで、工事を今ちょうど進めているところです。来年度以降につきましては、水銀灯をＬＥＤ化する建替え事業の中で、状況を見ながら、防災課と協議しながら、今後の整備のあり方をちょうど今検討しています。","voiceIndex":242,"id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１８３ページの空き家等対策事業、それから１８４ページの空き家等対策計画策定経費、そして１７９ページの公園整備事業費についてお伺いしたいと思います。そういう点では、私はこの計画素案について、説明会を地域でぜひやっていただきたいというふうに思うのですけれども、その点についてもお聞かせください。","respondent":"森住宅課長","answer":"１２月２日からパブリックコメントを実施して、年度内に策定をしていきたいというふうに考えております。計画策定費につきましては、今年度、約１００万円を入れまして、計画の見直しといいましょうか、策定費用に充てているところです。","voiceIndex":245,"id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"計画をつくったときには、基本、説明会をやるというふうに、区の方針としてもぜひやっていただきたいということで、強くこれは要望をしておきたいと思います。具体的にお伺いしたいのが、本当に荏原地域は特に空き家が多いわけですけれども、既にきめ細やかな対応をしていただいた上で代執行もしていただいております。","respondent":"森住宅課長","answer":"荏原地区の１戸の特定空家についてご紹介いただきましたけれども、これにつきましては、平成２７年度から法令に基づきましてそれぞれ措置をとっている。","voiceIndex":247,"id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"代執行もそういう安全対策ということであれば、１日も早く地域の方が安心できるような対策として実施していただきたいというふうにお願いをしたいと思います。そして、公園のない町会にとっては、本当に公園をつくってほしいというのが切実な願いなのですけれども、具体的にどうしたら公園ができるのかについてもお聞かせください。","respondent":"溝口公園課長","answer":"やはり公園整備にあたっては、まずは公園として適した用地の確保が第一になると思います。そのようなところで、少しでも早い時期に全ての町会に公園ができるように取り組んでいきたいと考えているところです。","voiceIndex":249,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"具体的にどういうふうにしたらいいかということもお聞かせいただきたかったのですが、もう時間がありませんので、本当に地域のコミュニティとして公園は大事なものだと思いますので、ぜひ公園のない町会に整備をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":251,"id":"exchange-105"},{"speaker":"大沢委員","kind":"質問・要望","question":"１７７ページの都市計画費について伺いたいと思います。武蔵小山の件ですけれども、これは発展的に武蔵小山が変貌していくということの期待を込めての質問ですので、誤解のないように聞いていただきたいと思います。それについてどのような対策を練り、どのようなビジョンを持っていらっしゃるのか教えてください。","respondent":"稲田都市開発課長","answer":"目標を定めまして、このような住居等々もつくって、商業のさらなる活性化というところで取り組んでいるところです。ご指摘の東急の武蔵小山駅ですが、現状もすごく電車が混んでおりまして、ホームから乗ることができないというような声も聞くことがあります。","voiceIndex":253,"id":"exchange-106"},{"speaker":"大沢委員","kind":"質問","question":"品川区の事業だったと思いますけれども、立正大学の先生が来て、オリンピックとまちづくりみたいな講演をやったと思うのですけれども、そこの中で、本数を増やしたりとかで工夫をしたというような、これは鉄道事業者の役割でありますから、区のほうからどうのこうのということではないと思うのですけれども、そこの部分で工夫をお願いしたいと思いますし、今、武蔵小山のところも。","respondent":"稲田都市開発課長","answer":"確かにおっしゃるように、住居をつくっていけば新しい住民の方が増えてくるというところで、区もその辺は十分に承知しているというか、対応を今後、実際に地域の方々が交流できるような形を考えていかなければならないというふうには思っております。","voiceIndex":255,"id":"exchange-107"},{"speaker":"大沢委員","kind":"質問・要望","question":"かつてのバラックが並んでいた飲食街から比べれば、非常にすばらしい洗練されたアーバンな雰囲気の駅前になるわけで、そこら辺のところをしっかりと踏まえながら、商業地と住宅地が一体となっているわけですから、そこらの地域特性あるいは建物の特性を踏まえながら、当該地域、地元の合意形成、あるいは地域の活動形成に努めていっていただきたいと思うのですけれども、もう１回。","respondent":"稲田都市開発課長","answer":"そういう中におきましては、地域の皆さんとはよく話をするのですけれども、武蔵小山の商店街、商業、すごく底力があります。そういうところを利用と言っては失礼ですけれども、皆さんと考えながら、新しいコミュニティをつくっていきたいと考えております。","voiceIndex":257,"id":"exchange-108"},{"speaker":"大沢委員","kind":"質問・要望","question":"決して底力があるわけではないと私は……。長い歴史もあります。聞くところによりますと、戦後間もなく、駅前の近くのところに三軒長屋みたいなものをつくったところから小山の商店街が始まったということを昔の方から聞いておりますので、そこらのルーツを踏まえながら、しっかりと武蔵小山らしさを失わないようなまちづくりお願いしたいと考えています。お考えを聞かせていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"あるいは東京都は来年以降、都市計画区域マスタープランなども見直す動きもあります。そうしたところを踏まえながら、区として人口何万人を許容できるという数字はございませんが、そうした動向は常に意識としてしっかり持って取り組んでいきたいです。","voiceIndex":259,"id":"exchange-109"},{"speaker":"大沢委員","kind":"質問・要望","question":"わかりましたけれども、要は、これは本当にトレンドですから。急に増えることもあると思うので、そこらのところはしっかりと時代のトレンドを、課長にこのようなことを言うのは釈迦に説法かもしれないですけれども、読み解きながら進めていただきたいと思いますし、先ほど来の空き家の話があったように、現状あるスペースが少子化になると空いてしまいますね、どうですか。","respondent":"鈴木都市計画課長","answer":"空き家も戸建てからマンションの空き室、さまざまだと思います。やはり少子化が進んで世帯が減っていくですれば、やはりそのような部屋も増えていくのかというところは意識しています。","voiceIndex":261,"id":"exchange-110"},{"speaker":"大沢委員","kind":"質問","question":"いくのかなではなくて、やはりこれ対策、だから空き家対策計画の素案をつくっていただいていて、これは問題意識が非常に高くなってきたからこういうような委員会での質問もでてきたのです。住宅課長、そうですね。立ってご答弁をお願いします。","respondent":"森住宅課長","answer":"所有者が亡くなられて空き家になってしまった後も、すぐに適正管理ができる、あるいは市場の流通に乗せられるように、まずは発生予防ということでさまざまな相談会を開いていきたいと考えておりますし、適正管理をされていく中で、なるべく早く市場の流通に乗せて。","voiceIndex":263,"id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それともう一方で、ハード面の対策として、これは時間のかかることでありますので、すぐにできることとして、今現在、行われているものを下流でもやっていただきたいという地域の方のご要望がありました。委員長の許可をいただいたので資料をタブレットに送りました。ということで、上流にこれが設置された経緯と、下流のほうにそのような鉄板を設置していただきたいというご要望に関して、お願いいたします。","respondent":"持田河川下水道課長","answer":"当然、町会等へ周知する中では、さらに詳しくご説明をというような声も出るのではないかということは我々所管も認識してございまして、そのあたりは我々河川下水道課と防災課で協力しながら、よりしっかりと地域の方に周知するように努めていきたいと思ってあります。","voiceIndex":266,"id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ハード面のパネルについては、河川の管理は東京都だと思いますので、今お話あったように、検討して東京都のほうに強く働きかけをしていただきたいと思います。それからもう１つは、品川道踏切ですが、これは何度もほかの委員もお話になったと思いますが、エレベーター設置等のバリアフリー化に関してのＪＲとの協議の現状や今後についてお伺いします。こちらも地域の方の声があったので、その点を願いします。","respondent":"多並道路課長","answer":"我々のほうでも東京都の第二建設事務所に改修等の要望をしたところだったのですけれども、今後の改修の際に様子を見てやっていくという回答だったので、これについても、今後、いろいろなタイミングを見ながら都には要望していきたいと思っているところです。","voiceIndex":268,"id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。いろいろ大変かと思いますが、強く要望をお伝えいただくことをお願いいたします。最後、公園ですけれども、山中公園という公園がありまして、そこの滑り台の階段が、古い遊具なので抜けているというか、間に足が入ってしまったりするのです。ほかの公園は裏に板があって落ちないようになっているのですが、そういった遊具についての扱いはどのようになっているのでしょうか。","respondent":"溝口公園課長","answer":"山中公園の滑り台です。設置されてからそのままずっと皆さんに親しまれてきた遊具ですが、今回、長寿命化計画の中で改修する計画になっておりますので、今年度中に速やかに改修していく方向で、今、調整を進めているところです。","voiceIndex":270,"id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"改修の方向だということで理解いたしました。ほかの公園などでもそういった階段の部分が抜けていると、小さい子が落ちたり、挟まったりするので危険ですので、ほかの公園も含めて検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":272,"id":"exchange-115"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"健常者でも危ないと感じる狭さだったわけですけれども、このホームドアの設置が下神明駅には計画されているわけですけれども、もうすぐすればつく、だけどもう少し早ければという思いが込み上げますけれども、この事故において、品川区の考え、そして鉄道事業者に何を言ったのか、そしてホームドアがつくまでの間、障害者に駅員などの付き添いを徹底することが求められるのではないかと。","respondent":"鈴木都市計画課長","answer":"まさに委員と同じ思いでございまして、来年度、実施するということは伺っておりますが、できるだけ早い段階での設置を、補助金として区のほうで支援するという流れもありますので、その中でしっかり確認をしていきたいです。","voiceIndex":275,"id":"exchange-116"},{"speaker":"石田（ち）委員","kind":"質問","question":"視覚障害者の方が転落されたということですけれども、視覚障害者の方が持たれている白杖をこの方は持たれていなかった。ですので、障害者だということがわからなかったというのが駅員の話でした。それがなぜなのか、京急からさらに計画が出てくるということは聞いているのでしょうか。そして、こういう事態について、区としてはどう考えているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それで、２０２０年までには計画的には、例えば京急蒲田、京急川崎をはじめ、主要５駅についてはつけていくというところはもう計画として出てありますので、技術的な課題が大分解消されてきているのだというところは認識しています。","voiceIndex":277,"id":"exchange-117"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に事故が起きてからというのでは遅いので、ぜひ進めていくべきだと思いますし、区からも強く要望していただきたいと思うのですけれども、こうした区内の駅のバリアフリー化を進める声や運動は、区内でも各地で広がっていますけれども、南品川の新馬場駅南口も同様です。","respondent":"鈴木都市計画課長","answer":"新馬場駅の地域、特に南口側の地域の方々のお声は、この８月に、地域の方にいろいろ具体的なお話を直接伺ったところです。今、傾斜の解消というお話もいただきましたが、京急のほうでは、ユニバーサルゲートの設置の提案もあります。","voiceIndex":279,"id":"exchange-118"},{"speaker":"吉田委員","kind":"質問・要望","question":"東急でそのようなサービスがあるのか、そういうサービスを東急、京急などでも求めておられるのか、それであれば、ホームドアがつく前にも安全な乗り降りが確保できると思うのですが、それはお迎えのほうもあらかじめ申し入れておくと、ちゃんとそこで待っていて、改札まで案内してくださるというサービスをＪＲでは確認しているのですけれども、その辺、どのように確認して。","respondent":"鈴木都市計画課長","answer":"ソフト的な対策ですが、ご紹介いただきましたように、声かけサポート運動、これは東急のほうでも行っていると、私の認識では、各鉄道事業者、これはもう本当に全国的な取組みとして、駅職員の方だけではなくて、利用者の方も声かけをしていくというところで。","voiceIndex":282,"id":"exchange-119"},{"speaker":"吉田委員","kind":"質問・要望","question":"もちろんこれは事業者がやるべき事業だと認識しております。それから、声かけです。だから、見守りがあるかどうか、声をかけてくださらなかったので、気づかなかったと、その視覚障害者の方はちょっとお怒りでした。だから、その辺のことも品川区としてもこういうふうにやってほしいということをぜひ徹底していただきたいと思います。もう一言、ご見解があれば。","respondent":"鈴木都市計画課長","answer":"特に今、ソフト対策のところにつきましては、区のほうでやさしいまちづくり推進協議会等で、いろいろな視覚障害者の方とも意見をやりとりする場もありますので、そうした中で区としても鉄道事業者へのさらなるお願い、依頼、申し入れも含めてしっかりやっていきたいです。","voiceIndex":284,"id":"exchange-120"},{"speaker":"伊藤委員","kind":"確認","question":"成果報告書の１７５ページ、下水道管改修事業、それから１７６ページ、河川総務費に関連して、それから１７２ページの道路橋梁費に関連して質問いたします。そういうふうなことを考えていきますと、ここにある浜川雨水排水管であるとか、立会川雨水放流管であるとか、勝島運河その２、その３、これらはそういうことを十二分に見越した対応であるのかということの確認をお願いするのが１点。","respondent":"持田河川下水道課長","answer":"その後、立会川の能力を補完する第二立会川幹線という下水道管を設置したり、今、立会川の下流のほうで事業をやっています立会川雨水放流管、こういったものを整備しまして、そのような都市化の進展に伴う雨水流出量の増大への対応は進めているところです。","voiceIndex":287,"id":"exchange-121"},{"speaker":"伊藤委員","kind":"意見","question":"雨水放流管の説明は、ある程度は理解はしていたのですけれども、私はそれよりもさらに前に進んで、立会川は一時期、東京都の中でワースト３になりましたね、それをいろいろな方々が努力されてこられて今の状態に持ってきました。だから、そういうことを自由に織り交ぜていって、ここをはっきりとした将来像を持って変えていく。ワースト３に掲げられた川がこれだけ変わりましたよと。お願いいたします。","respondent":"鈴木都市計画課長、持田河川下水道課長","answer":"平成２９年度ですが、立会川、勝島地区のまちづくりビジョンの委託費を計上いたしまして、これまで地域の方のお声を聞きながら、当地区のまちづくり、将来的な方向性を検討してまいりました。そのようなことも見据えながら、事業を続けてまいりたいと思ってあります。","voiceIndex":289,"id":"exchange-122"},{"speaker":"伊藤委員","kind":"提案","question":"やっとここまで来た。そうすると、立会川は同時に水害が想定されますので、そのことの対応のための水門設置の状況と、それから、これはほかの委員からの要望でもあったのですけれども、水門開閉がオンライン化できるのであれば、例えば天王洲野球場の水門付近の施設を一部撤去し、球場を拡大してはどうかという提案もありますので、あわせて検討していただきたいと思いますが、いかがでしょうか。","respondent":"持田河川下水道課長","answer":"東京都の港湾の水門などでは、基本的には、２４時間、人が監視しているというところもありますので、そのような事例などを見ながら、何かあったときの責任の所在なども含めて、そのような大きな視点で水門の管理についてはまた検討していきたいと思ってあります。","voiceIndex":292,"id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問・要望","question":"１７２ページ、道路橋梁費、これはホームレス対策費に関連してであります。かつて議会でホームレス対策についていろいろ議論しました。もちろん私たち、何回も担当課にも話をさせていただきましたし、法令、条例に基づいた対応を求めてきましたけれども、現状は回復しておりません。だからこそ非常に困るという話がありまして、まずここの品川区のお考えを聞かせてください。お願いいたします。","respondent":"多並道路課長","answer":"ただ、なかなか国のほうの対応というところもあるので、動かなかったこともあるのですけれども、その際は、区の中でできることということで、まずは生活福祉課と連携をしております。","voiceIndex":294,"id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問","question":"確かにこれも勉強しました。法改正も考えたのだけれども、一般の利用者とホームレスの線引きが非常に難しいという話を聞きました。それはそのとおりです。だから、こういう事例も参考にしながら、国と連携をとっていくことも考えたらどうですかということと、それから、これは２３区共通の課題として、改めて区長会等で議論すべきと思うのですが、いかがでしょうか。あわせてお願いいたします。","respondent":"多並道路課長","answer":"都道であれば都であったり、あとは、先ほど申し上げた警察との連携です。今ご提案がありました２３区との連携という意味では、確かに共通する部分でもありますので、そのような３者で、今後いろいろな機会で話し合って、何か進めてまいりたいと思っているところです。","voiceIndex":296,"id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"１８３ページの親元近居支援事業、１７６ページの河川費について伺います。１つが、親と子どもの世帯間で介護や子育ての助け合いをしていただく。もう１つ、申し上げた２つの目的の達成状況をお聞きしたいと思います。そして、転入の誘引、定住促進についての効果、どのような効果が上がっているか状況をお知らせいただきたいと思います。","respondent":"森住宅課長","answer":"今まで７年間で２５８件に対し助成をしておりまして、一定程度、予算もほぼ使わせていただいているところでございまして、成果として一定上がっているというふうに考えております。","voiceIndex":299,"id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"平成２３年度開始ということで、当初も少しアンケートをとられて、そのときの議事録も残っておりますけれども、この制度があるからという動機では、今あったように今回のアンケートでもゼロということなのですが、その中でも３２％の方が考えてみようということで、徐々にではありますけれども、このサービス、政策の事業が浸透していたり、また。","respondent":"森住宅課長","answer":"近くに住むことでお互いに安心できるということも近居を選択した理由としてもアンケートの中でご回答いただいておりまして、これに基づいてファミリー世帯が２５８件あったということではありますが。","voiceIndex":303,"id":"exchange-127"},{"speaker":"若林委員","kind":"質問","question":"これは今後、ずっと今日は我が会派からも空き家の問題等々、また、住宅、居住支援協議会の話、長期基本計画の改定にあたっては、こういう特にファミリー世帯の方々に、どのように区内に来ていただくか、また同時に、介護、子育て、支え合いの社会をつくっていくか、こういう大きな観点で言うと、まだまだいろいろ検証して、または次年度、次々年度と改善をしていく、そういう事業だと思いますけれども。","respondent":"森住宅課長","answer":"なかなか所得の低い方とかも、転居したい、品川区に入ってきたいと思っていても、なかなか金銭的な面で難しいところもあると思いますので、引き続き、お互いに助け合いたいと考えている方に、少しでも助けとなるような制度設計につきまして。","voiceIndex":305,"id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"しっかりとまた検証を継続して、またアンケートもとっていただいて、よりファミリー世帯の方に品川へお越しいただけるような政策として、充実を検討していただきたい。大きな課題を抱える中でという意味で要望します。そこで、浚渫の目黒川における範囲をお知らせいただきたいと思います。毎年何月ごろやっているのか、浚渫は何日間程度かかるのか教えてください。","respondent":"持田河川下水道課長","answer":"平成２９年度につきましては、五反田駅の近く、大崎橋の付近という形でやってございまして、平成２９年度に実施した時期は、１０月の下旬です。実施した期間としては、大体１週間ぐらいという形です。","voiceIndex":307,"id":"exchange-129"},{"speaker":"若林委員","kind":"意見","question":"今年になりますけれども、先月、１０月の初旬に、目黒川はいつもながめるのですが、特に大きな黒いヘドロの固まりが川の大部分を占めて流れておりました。この浚渫の時期、年に１回、２回ということも……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":309,"id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"私は、１８１ページ、都市防災まちづくり事業費についてお聞きしたいと思います。今年の８月から９月にかけて、台風や地震などが列島各地で猛威をふるい、都市部において大きな被害をもたらしています。品川区には、国道、都道、区道がありますが、品川区は災害時の交通路の確保はできているのでしょうか。区内に非常用電源付信号機などは何台ぐらい設置されているのか、それもあわせて教えてください。","respondent":"古巻防災課長","answer":"災害時の道路の確保等ですけれども、緊急輸送道路等、災害時に物資等の輸送で優先的に使われる道路ということで指定がありますので、そのような道路を利用できるような形にするという体制につきましては、区をはじめ道路管理者、警察、消防等と連携をとって。","voiceIndex":311,"id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"私がお聞きしているのは、これだけ大渋滞が発生したのですね。緊急の場合、連携がとれていますと言いますが、適正に交通整理等ができるのですか、無理でしょう。例えば、この時間に一斉に大地震が来ました。はい、連携がとれていますから渋滞はありません、特定緊急輸送道路も確保されています、そのようなことはとあり得ないのではないですか。それに対して対策は考えていないのですか。","respondent":"古郡交通安全担当課長","answer":"私からは、信号機の設置に関してご説明をいたします。信号機は、大きい交差点だとか、そのようなものについては、発動発電機がついておりまして、一定時間は電源が確保できます。","voiceIndex":313,"id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"今、いざというときの話をしているのです。今、課長が、いや、警察官も配備しますと。今回、北海道でも交差点には警察官が立てなかったです。実際そういう状況が起きていました。全部立っていたわけではなくて、やはり一斉に配置などできないですよね。それに一人ひとり配置するだけの人員などいるわけないではないですか。これに対して全く区としても考えていらっしゃらなかったですか。","respondent":"古郡交通安全担当課長","answer":"主要なところに大体発動発電機がついたものを設置しておりますので、それである程度、交通路が確保できるということで、北海道に関しては、どういうふうになっていたかは把握していませんが、東京都の場合は、そのような形で、だんだん設置も進んでおりますので。","voiceIndex":315,"id":"exchange-133"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区内にはすごい量の自動車が通っています。ましてこの品川区を見ても、１０台か２０台とまってしまったら、全く動けないです。でも、大きな交差点にたどり着けないということが、今回立証されたと思うのてす。それについてはしっかり考えていただきたいと思います。街路灯もそうです。これも交通路や避難路の確保はできないのではないですか。この辺について、どのように対応を考えていますか。","respondent":"今井土木管理課長","answer":"当課では、東京電力など電柱の占用の許可の事務をしております。東京電力は、最大震度７を記録した阪神・淡路大震災に耐えられるよう、また、風についても風速４０ｍは耐えられるような電柱を立てているところです。","voiceIndex":317,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問・要望","question":"避難路、交通路に関しては、これからも、これだけの数があるのですから、私は的確に早くやって対応していただきたいと思います。この辺についてどのように対応を考えていらっしゃるのですか。では、いざとなったとき、どうぞ、ビルから離れて、マンションから離れてと言っても、上から落下してガラスが飛んでくるわけです。その辺についてどのようにお考えですか。","respondent":"稲田都市開発課長","answer":"都市開発課が関係している高層ビル等につきましては、そういう防災上の問題等々ありますけれども、まずは地震に対しては免震構造とか、そういうところで対応しているというところでございまして、また、ガラスにおきましても、複層型、二重ガラスとか。","voiceIndex":319,"id":"exchange-135"},{"speaker":"須貝委員","kind":"質問・要望","question":"現に専門家からこういうふうに言われています。割れて飛散して落下しますと。実際それだけ危険だと言っているのです。一部の建物、何分の１かわからない、１０分の１か、５％かわからないですが、実際、ペアだろうが、強化ガラスだろうが、強化ガラスもそうです、学校でつけていますけれども、あれも小さな石ころが当たったら、割れて落ちます。ぜひその辺の対応を早急に考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":321,"id":"exchange-136"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、まず１８３ページ、さっき、空き室とか空き家の話があって、そこから入りたいと思います。それから、１８４ページ、建設型区民住宅をやります。なれていると言ったほうがいいか、もう既にそういう状況になっている。それは防災協定を結ぶのかどうかは別として、そういうことはすぐできると思うので、そこら辺はもう一歩突っ込んでやれると思うので、そこら辺の見解を教えていただきたい。","respondent":"森住宅課長","answer":"そのような事業者の中でいろいろネットワークがあってということは、一部、今でも業界の方から聞いてありますけれども、空き室の１つの有効活用といいましょうか、災害時の活用につきまして、そのようなことが考えられるのであれば。","voiceIndex":323,"id":"exchange-137"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはどれぐらい数があって、どれぐらいお願いをしに行って、どういう体制でやられているかということと、あと、せっかくセットバックしたのに電柱がそのまま残ってしまっていてという、電柱移設も、多分非常にご努力をされていて、事業者だとか、ＮＴＴだとか、東電だとか、努力をされていろいろやっていらっしゃると思うけれども、数字的に依頼は、例えば、平成２９年度でもいいのだけれども。","respondent":"長尾建築課長","answer":"４２条２項道路、細街路の件につきましてですが、まず細街路の拡幅をした後に植木鉢などを置かれている場合ということですけれども、近隣の方であったりから、建築課の細街路担当のほうに連絡が入ります。","voiceIndex":325,"id":"exchange-138"},{"speaker":"石田（秀）委員","kind":"確認","question":"だけど、逆に言うと、都市計画道路などもそうですけど、４２条２項道路も指定しているわけだから、ということは、最初からそれは建物を建替えたときは、セットバックしたら、私道であったとしても、それは権利の問題がどういう形というのがさまざま議論されてきているわけではないですか。ここら辺のところは大変嫌なところではないですか。","respondent":"長尾建築課長","answer":"そのようなところとあわせて、先ほどの細街路について１件１件丁寧に対応していくところもあわせて、まずは今の体制で頑張っていきたいと考えております。","voiceIndex":327,"id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"確認","question":"どうしてそういうことを聞いたかというと、確認をおろすときは事業者の方に、こういうことがあるから、ここはこういうものもあるから、セットバックしたらこうしてくれとか、電柱がそこにあれば、こういうことをしてくれと頼めるではないですか。状況がわかるのだから。相談だけではわからないではないですか。歳入を見ると、使用料と国庫補助金と共益費で１１億８,０００万円ぐらい入っていると思います。","respondent":"森住宅課長","answer":"実際にどうなのかというのは、今、今年度の検討を待っている形ですけれども、そのような時代の変化といいましょうか、そのような地価の変動等々も加味しまして、柔軟に検討していきたいと考えています。","voiceIndex":329,"id":"exchange-140"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、１７６から１７７ページ、水辺利活用事業関連、１８０ページ、五反田地区、大崎地区の市街地整備事業費関連について、時間があれば、１７１ページの駅周辺等放置自転車対策についてお伺いします。はじめに、水辺関連ですが、建設委員会で行政視察に行った際に、名古屋市で堀川をきれいにしようということで、堀川エコロボットコンテストというものをやっていたそうです。","respondent":"持田河川下水道課長","answer":"区としましても、そのような川のほうに何とか注意を向けていただけるような取組みも今後いろいろと検討していきたいというふうには考えてあります。","voiceIndex":332,"id":"exchange-141"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひよろしくお願いします。水辺、そのまま行きます。実際、私もちらっと運河のところでホテルらしきものがぽつんと浮かんでいるのをこの間見たのですが、その辺の取組みについてお考えをお聞きします。西五反田二丁目の大街区化についても、どのように今進んでいるのか教えてください。よろしくお願いします。","respondent":"持田河川下水道課長、稲田都市開発課長","answer":"なかなか舟運のほうは事業者との収益的な部分を含めたルートの検討も必要になってくるものですが、そういった視点から水辺を結びつけていくような事業を進めていきたいと思ってあります。そういうところにおきましては、駅周辺の交通の流れや駐輪の問題等もありますが、そういうものを含まして、五反田駅周辺賑わいゾーンまちづくりビジョンもありますけれども、そういうものに沿いながら。","voiceIndex":334,"id":"exchange-142"},{"speaker":"石田（し）委員","kind":"提案","question":"いわゆる賑わいゾーンのまちづくりビジョンがあって、だけど、今大きくまちが変わろうとしている中で、やはりこれは見直しをしっかりして、本当に未来に向かってどのようにまちをつくっていくかということを考えていかなければいけないと思います。我々としても、できる限り提案できるところはしっかりしていきたいと思いますので、連携を深めていっていただければというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":337,"id":"exchange-143"},{"speaker":"南委員","kind":"質問","question":"駅周辺の放置自転車、これは減っているのか増えているのか、現状をどう見ているのかをまず伺いたいと思います。そして、この対策費について過去と比較してみると、定期利用は減っている、一時利用は増えている、そういうふうに見えるのですけれども、そういう状況、区の認識と評価を伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"駅の放置自転車については、年々減少傾向にあるということで認識をしております。定期利用と一時利用の関係ですけれども、利用率からすると、一時利用のほうが多くなってきているような認識をしております。","voiceIndex":339,"id":"exchange-144"},{"speaker":"南委員","kind":"質問","question":"つまり、一時利用が増えているということ、これは放置自転車対策としての効果はあるというふうに見ていいのでしょうか。その点を１つ伺います。","respondent":"古郡交通安全担当課長","answer":"そうですね、区では、駐輪場の整備と撤去、指導・警告ということを三本柱でやっています。ですので、効果が上がっているという認識をしております。","voiceIndex":341,"id":"exchange-145"},{"speaker":"南委員","kind":"質問・要望","question":"そうであるならば、大型店などの一時利用は２時間までは無料ですよね。つまり、民間が実施しているような２時間までは無料、それを超えたときには、できるだけ低廉に、民間にならって１００円ということでもいいと思うのですけれども、そういう仕組みに変えるべきだ、そういう声が区民の間にたくさんありますけれども、そういう点についてどうでしょうか。","respondent":"古郡交通安全担当課長","answer":"最初に、民間の駐輪場整備等の効果で放置自転車が減ったのかという認識ですけれども、区の方も駐輪場の整備、撤去等をやっておりますので、それで減っているという認識をしております。","voiceIndex":343,"id":"exchange-146"},{"speaker":"南委員","kind":"質問・要望","question":"大井町周辺を見ても、それほど放置自転車はないのではないかと思うのです。１日、学生だとか通勤者だとかの長時間というのは定期利用に誘導していけばいいわけですから、やはり一時的な利用をどういうふうにもっと利便性を高めるかというところを、もっと品川区として考えていただきたい。できるだけ無料にしていただきたい、こういうことを強く要請しておきたいと思います。","respondent":"溝口公園課長","answer":"３０年が経過して改修工事を計画的に進めているところです。実際、公園の改修につきましては、平成２８年、平成２９年、２カ年かけてやっておりまして、木としては、既存樹木が１,３８３本ありまして、やむを得ず、区のほうで木を切らせていただいたのが４５３本あります。","voiceIndex":345,"id":"exchange-147"},{"speaker":"南委員","kind":"質問・要望","question":"大変傷んでいる木が多いというふうに聞くのですけれども、日常的な公園の樹木の管理、あるいは手当て、そういうことはどうなっているのでしょうか。それで、やはりあそこのところはきれいに整備されたとは言っても、さっきも言ったように、かんかん照りですから、やはり何らかの木を植えたり、木陰をつくる、そういうことが必要なのではないかと考えています。","respondent":"溝口公園課長","answer":"木の管理につきましては、委員ご指摘のように、樹木診断も行いながら、または、春、秋、そのようなところでの剪定を行いながら適正に管理しているところではありますが、やはりこのような公園改修の機をとらえて、今後また２０年、３０年。","voiceIndex":347,"id":"exchange-148"},{"speaker":"南委員","kind":"質問","question":"八潮地区のまちづくり検討経費ですが、過去２回、検討会が開かれたと聞いておりますけれども、区がそもそも検討会をつくろうとした認識は何なのか、八潮のまちを今後どのように再生していこうとしているのか、具体的な項目、テーマを教えてください。","respondent":"鈴木都市計画課長","answer":"耐用年数を考えますと、２０年、１５年先のまちづくりを検討していくですが、やはりいろいろな事例、特に団地再生の事例をお伺いしますと、振り返ってみると、検討開始から１０年、１５年かかっているという声も伺っております。","voiceIndex":349,"id":"exchange-149"},{"speaker":"南委員","kind":"質問・要望","question":"私の問題意識はたくさんあるのですけれども、取り立てて幾つかに絞って言うと、１つは人口構成の問題があります。ＵＲ住宅の空き室もかなり感覚的に増えているのです。高齢者の皆さんは年金生活で、これを払うのが大変だと、こういう状況なので、やはりこの熱供給システムについて、抜本的に見直すような、そういうこともテーマに入れていただきたいと考えていますが、その点についてどうでしょうか。","respondent":"鈴木都市計画課長","answer":"今、さまざまな地域のお話をいただきましたが、冒頭申し上げましたように、やはり１５年、２０年先の大きなまちづくり、その先を見据えて、何年後かに振り返って。","voiceIndex":351,"id":"exchange-150"},{"speaker":"南委員","kind":"質問","question":"最後に、具体的に熱供給のことも聞いたのですが、そこの見解をお願いします。","respondent":"鈴木都市計画課長","answer":"さまざまな課題は大きい視点の中で今後も検討していきたいです。","voiceIndex":353,"id":"exchange-151"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、１７５ページ、橋梁費、１７８ページ、ＪＲ京浜東北線大井町駅エレベーター設置助成、そして同じく、公園・児童遊園維持管理費、この３点をお伺いしたいと思います。上神明歩道橋の撤去については、これまで我が会派のたけうち委員が求めてきたことであり、撤去実施に至るまで時間がかかりましたが、求めてきたことの実現をうれしく思っております。","respondent":"多並道路課長","answer":"歩道橋の撤去につきましては、東京都が基準を持っておりまして、それを準拠しております。撤去の要件としましては、利用者が少ないということで、２００人以下であったり、近傍に横断歩道が設置されている、交通管理者や地元の方々の理解が得られている。","voiceIndex":356,"id":"exchange-152"},{"speaker":"こんの委員","kind":"質問・要望","question":"今お伺いしました要件、基準、こちらに照らし合わせてみると、私も以前から、平成２５年、２７年、２９年の予算特別委員会でも要望してまいりました南大井の桜新道の歩道橋、ここはこの要件に当たるところというふうに思うのですが、この歩道橋については撤去、あるいは撤去できない場合は、エレベーターをつけていただきたいというふうに求めてきたわけですが。","respondent":"多並道路課長","answer":"ただ、今、委員のご指摘にありましたように、交通上、下が自転車しか通ってはいけないような構造になっている関係があって、非常に安全上の問題があるということで、地元からもご要望があって、学校や警察といろいろ協議した結果。","voiceIndex":358,"id":"exchange-153"},{"speaker":"こんの委員","kind":"質問・要望","question":"大変に危険です。次に、ＪＲ京浜東北線の大井町駅のエレベーターの設置について、関連してお伺いしたいと思います。ではなくて、改札口のほうに入口が向いていると、出やすいですし、乗りやすいということがありますので、このような要望が上がっておりますので、耐用年数の対応と方向性もある中で、どのようにこのことは考えられますでしょうか。","respondent":"鈴木都市計画課長","answer":"今いただいたご要望はＪＲのほうに、さまざまな機会の中で今いただいたお声は区としてもＪＲのほうに、まずそういった計画がどれぐらい先に予定されているのかを含めて、ただ、通常ですと、エレベーターが老朽化した部分の交換ということですから、今の向き。","voiceIndex":360,"id":"exchange-154"},{"speaker":"こんの委員","kind":"質問・要望","question":"その協議をするときに、もう１点、要望が、声があるのが、きゅりあん側にもエレベーターをつけてほしいという声です。これは要望で終わります。最後に、公園・児童遊園維持管理費に関連して、公園が保育園の園庭の代替地として使われていることについてお伺いしたいと思います。２台、３台持っているところもありますので、こうしたところで地域の協力も得られるバスのこうした送迎はいかがでしょうか。","respondent":"溝口公園課長","answer":"公園は誰もが利用できるところです。さまざまな方が利用しておりますので、そのようなところで所管と連携しながら、どういう形がいいのか検討していきたいと考えているところです。","voiceIndex":362,"id":"exchange-155"},{"speaker":"渡部委員","kind":"質問・要望","question":"時間があったら、別のことを聞きます。当然、環境未来館ができるときには、補助２６号線のトンネルが開通してというところで、車の流れとかも変わってくるようなところになるわけですから、そうした場合、その向かい側の文庫の森とも連携できるような仕組みもあるのかというふうには会派で考えていたりするのですが、その辺、戸越公園の改修についてどう考えているかということをお聞かせいただきたい。","respondent":"溝口公園課長、高梨木密整備推進課長","answer":"そのような中の１つとして、プレイパークですとか、また、どういう形で今後改修していくかということはありますが、そのようなことも含めて、戸越公園をさらに充実できるように、また環境未来館ができた後には連携できるような。用地の管理権限は東京都にありますが、防災に資する使い方等について、また東京都と積極的に協議してまいりたいと考えています。","voiceIndex":365,"id":"exchange-156"},{"speaker":"渡部委員","kind":"質問・要望","question":"機を見て要望します。それと、本日も私どもの会派の大沢委員から質問がありまして、例えば品川区のキャパシティというのはどうなのだろうというお話がございました。現実問題として。これは今後どういうふうに展開していかれますか。私たちとしては、鉄道事業者も入れて、いわゆる品川区の公共交通のあり方を全て包括的にもう１回話し合える場にしてほしいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"当然ながら、その整備の中では、今いただいたような各駅の利用状況などもご議論いただいて把握しながら、鉄道事業者に入っていただくかということはしっかり検討していきたいと思いますが、コミュニティバスを軸に区内の地域交通、公共交通のあり方については。","voiceIndex":368,"id":"exchange-157"},{"speaker":"渡部委員","kind":"質問・要望","question":"地域の交通は大事だと思います。区内には、さまざまな優良といいましょうか、大きな企業がありますので、ぜひそういうところから知恵をいただいて進めていただきたいと思います。それを幾つもルートを走らせると大変なことになるものですから、ある資源をしっかり活用するのが一番だと思いますので、品川らしい事業を構築いただければと思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":370,"id":"exchange-158"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1460#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":119074,"voices":371}},{"id":"h30-20181113-4","meetingId":"h30-c-settlement","date":"2018年11月13日","dateIso":"2018-11-13","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 おはようございます。ただいまより、決算特別委員会を開会いたします。 それでは、平成２９年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 おはようございます。ただいまより、決算特別委員会を開会いたします。 それでは、平成２９年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"おはようあります。私のほうからは、１８６ページ、生徒指導対策費、１８８ページ、ボルダリングを活用した体力向上の取組み、１９６ページ、学校給食費について、時間がある限りお伺いをします。しかしながら、その反面児童・生徒の自殺者数が過去３０年で最多となったという報道があります。区が行っている具体的な取り組みについて、この４つの観点でございましたら、具体的な説明をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"自殺予防教育に関するお尋ねです。学校現場では、若年層の自殺が、全国的に増えている部分に非常に危機感を持っておりまして、重要な課題として取り組んでいる最中です。やはり児童・生徒の悩みをどのような把握するのか、具体的な取り組みという観点からお答え申し上げます。","voiceIndex":4,"id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"今、スクールソーシャルワーカーであったり、匿名の電話であったり、ＳＯＳを受けとめるようなさまざまな取り組みをしているというお話をいただきました。では品川区全体で、このＳＯＳを年に何件ぐらい受けとめているのか、また過去３年ぐらいの推移もあわせて教えてください。","respondent":"大関教育総合支援センター長","answer":"子どもたちからのＳＯＳは、例えば各学校に設置しております目安箱、それから専用電話、ＨＥＡＲＴＳのほうにかかってくるものなどで把握し対応しています。","voiceIndex":6,"id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"では続いて、１９６ページの学校給食費についてお伺いをします。この検査を導入された時期としては、恐らく東日本大震災がきっかけなのかと思われますが、食材を検査していらっしゃるのだと思いますけれども、検査している中で実際にこれまで基準値を超えた件数がどれほどあるのかということを教えてください。この検査費用が半分程度になった理由もあわせてお聞かせください。","respondent":"篠田学務課長","answer":"こちらは、それまでは毎年全校実施をしてございましたストロンチウムの検査を３分の１の学校に縮小いたしました。要は３年に１回の割合で全校が検査できるような体制に変更したということで、減少したものです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"芹澤委員","kind":"意見","question":"被災から８年目に近づく中で、お金をかけて品川区が検査をする必要性がどれほどあるのかないのか、少し疑問に感じるところであります。食材費が高騰して、限られた給食費の中で栄養バランスや量など質を保つ観点から、来年も、そして再来年も検査をしていく予定なのか。そして、どれほど時間が経てばこの検査をやめることが選択肢に入ってくるのかということも、あわせてお聞かせください。","respondent":"篠田学務課長","answer":"委員ご指摘のとおり、現地でも食材に関してはきちんと検査をされているということがありますので、今後情勢を見ながら、この実施については考えていく必要があるとは思っていますけれども、現状、少なくともこれを拡充していく方向にはないということで。","voiceIndex":10,"id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"最後に、ボルダリングについてお伺いします。３年リースというようなお話を伺っていましたが、もうすぐ３年たつということで、この設備をどうする予定なのか、土地が少ない中で、ボルダリングであれば有効な活用ができるのではないかと思っているので、ほかの学校でも配備する予定があるのかも含めてお聞かせください。","respondent":"有馬庶務課長","answer":"したがいまして、今後も改築が予定されている後地小学校、後地小学校が終わった後は鮫浜小学校においても活用していこうかなというふうに考えているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"１８６ページ、教育指導費、１８８ページ、芹澤委員と同じですが、ボルダリングを活用した体力向上の取組みについてお伺いいたします。教育指導費では、重たいかばんの課題について確認をします。塚本副委員長が、第２回定例会での一般質問でも取り上げましたが、その後の品川区の対応について伺いたいと考えています。","respondent":"大関教育総合支援センター長","answer":"重たいかばんに関して、その後の対応に関するお尋ねです。文部科学省より９月６日付で出されました通知文を受けまして、その後東京都を通じて本区にも届いております。それを踏まえまして、翌日９月７日付で全校に通知を出しました。","voiceIndex":15,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"私もその通知を確認させていただきました。これを各学校にということで通知をされたというように確認をさせていただきました。貼るだけでなく、今後もしっかりと対策がとられているかどうかという確認も行っていただきたいと思います。一方では、余り重さが変わらないという声も聞いておりますので、そこのところをしっかりと今後も対応を進めていただきたいと思いますが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"担任がしっかりと子どもたちに、安心して置いていっていいのだよということを伝えられるかどうかにも大きく差はあろうかと思いますので、今後も引き続き、例えば次年度も新しい教諭を対象とした研修会などでは、重たいかばんについても話題に取り上げるなど。","voiceIndex":17,"id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"次にボルダリングについてお伺いいたします。先ほどの質問で、芳水小学校の後、別の学校でも使われるということが確認をされました。品川区内の小・中学生のボルダリングの競技人口を、どのように把握されているのかということをお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"ボルダリングがどれほど品川区民に定着しているか、浸透しているかという数値はまだ把握できていない状況ですが、区役所の隣にも最近はボルダリングボードができたりなど、ニュースポーツとして注目を浴びているということは把握していますので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"プロクライマーの尾川とも子さんが、登れたときの達成感を味わってほしいというふうにメッセージを贈られていますが、気軽にできるスポーツであるということです。そこでオリンピックを目指して、先ほど大関教育総合支援センター長からもありましたが、お隣のスポル品川大井町のボルダリング設備を使い、ぜひ品川区の大会の開催を要望いたしますが、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"スポル品川大井町のボルダリングですけれども、昼間も大勢の方が楽しみ、そして土日となりますとお子さんも参加して気軽に楽しんでいる様子、私も拝見させていただいているところです。こちらのほうはぜひ何とか、考えていきたいと思います。","voiceIndex":21,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"１８５ページの学事制度検討経費より、学校統廃合と学校建て替えについて、１８６ページの教育指導費より、学校スタンダードの検証と見直しを求めて質問したいと思います。学事制度についてですが、新たな人口推計が示される中、学校統廃合を検討する必要は全くないと思いますけれども、いかがでしょうか。","respondent":"篠田学務課長","answer":"学事制度審議会の中ではさまざま検討されてきたものですけれども、基本的に現在、学校の統廃合というと、当然子どもの数、就学人口等が関係してくると思うのですが、現状品川においては就学人口はどんどん増えているという状況ですので。","voiceIndex":24,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"こうした中で、小・中学校の改築、建て替えの時期を迎えますが、私の近所にある伊藤小学校、冨士見台中学校、大井第一小学校、山中小学校について伺いますけれども、建築年数が大分経過をしております。保護者からも、そろそろ建て替えの時期なのではないかという声も伺っております。先ほどの４校について、改築、建て替えの時期はいつなのか伺いたいと思います。","respondent":"有馬庶務課長","answer":"本来であれば先の見通しを全部立てて、何年にはどこの学校というような計画が立てられればいいのですけれども、なかなかそういったことが難しい状況もありまして、今の４校のところについてを含めて、どこの学校は何年にやるというような具体的な計画は立ってございません。","voiceIndex":26,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校の建て替えについて、ＰＴＡも保護者も関心の高いところなのですけれども、ぜひ学校やＰＴＡの要望をよく伺いながら、話し合いながら、決めていただきたいと思います。次に、学校スタンダードについて伺いたいと思います。区立小学校の「学校スタンダード家庭保存版」を読みました。この１５ページにわたるルールづくりについて、子どもたちはどのようにルールの策定に参加したのか伺います。","respondent":"大関教育総合支援センター長","answer":"だんだん年齢を追っていく中で、児童会や生徒会の活動において自分たちで考えていく場面というものは、これはもうまさに市民科の中で主権者教育をやっておりますが、自治的活動領域の中で自分たちで話し合いをしていく、学級会活動をやっていく。","voiceIndex":28,"id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"話し合いというよりは、決まりを、ルールを守りましょうということは、この策定に子どもは参加していないということでいいのか確認したいと思います。子どもたちはこれらのルールづくりに参加しているのかいないのか伺います。","respondent":"大関教育総合支援センター長","answer":"やはり教員が保護者たちと意見を交換しながら、まず１年生は学校生活をどのように進めるべきなのか、教室で授業のときにはどのような正しい姿勢で座るべきなのか、姿勢を崩さずに姿勢正しく座りましょうということはこのような座り方なのですよということを絵も交えて。","voiceIndex":30,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"例えば５分休みを遊びの時間ではないと指導をしておりますが、多様な子どもたちに画一的な指導方法でよいのでしょうか。私はむしろ窮屈で納得のできないルールとは、大人の見ていないところでルールを破ることをひそひそと楽しんでしまう、また、ルールに従うだけで疑問や質問を挟む余地をなくし、自主的な力にふたをしてしまう、子どもの豊かな成長をゆがめてしまうと思いますが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"そのときには、今日は天気がいいから先生と一緒に外でボール遊びをやろうよという声をかける担任もいますし、図書室で静かに本を読みたい子は図書室に行きます。それは個別の対応をやっているところです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が心配していることは、これが学校のルールだと示され、それに従うことがルールだと思わせることは、子どもの自由な気持ちや発想にふたをし、鬱積した気持ちを増幅させることであります。さまざまな家庭がある中で、この宿題のルールが正しいと決めることは、そこから外れる子どもは窮屈な思いをするのではないでしょうか。学校スタンダードの検証と見直しを求めますが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"個別の対応というものが大前提かと思いますので、まずは１つの目安、スタンダードなものを示してあげることで、そこになかなか難しいお子さんがいれば、どのような手だてが必要なのか、配慮が必要なのか、個別に対応しています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"先ほどから目安と言いますが、学校で配られているものには、我慢することや励まなければならないことがたくさんあります。このルールを守りなさいと記されております。子どもの気持ちをないがしろにするような、こうした学校スタンダードは見直しが必要だと強く思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"私からは、成果報告書の１９４ページの校庭人工芝生化について、１９６ページの学校給食費について、１９８ページの浜川小学校の敷地測量委託について伺います。初めに小学校で進められている校庭の人工芝生化について伺います。そして、子どもたちの膝に影響があるのではないかということがよく聞かれるのですけれども、実際のところどうなのでしょうか。あわせて伺います。","respondent":"有馬庶務課長","answer":"学校の校庭を人工芝生化していくことのメリットですけれども、委員ご指摘のとおり砂ぼこりの飛散への対応というものが一番大きいところです。それ以外にも、水はけの悪い校庭が改善されるということも大きなメリットになっています。","voiceIndex":38,"id":"exchange-017"},{"speaker":"松永委員","kind":"意見","question":"この人工芝生化についてなのですが、先ほど、小学校、中学校によっては人工芝生の長さが違うということであったのですけれども、例えば以前ブラインドサッカーの国際大会が行なわれた天王洲公園は多分長目の人工芝だったかと思います。今回それは置いておきますが、人工芝生についてさまざま議論されている中で、今後、本区の小学校は全校人工芝生にされるのか、また中学校についてもお知らせください。","respondent":"有馬庶務課長","answer":"そういったことを考えますと、基本的には今後は人工芝を中心に、進めていくということを考えているところです。中学校も同様です。","voiceIndex":40,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"次に学校給食について伺います。そうした中、近年完食指導がネット上で話題になっております。そこで現在本区では、給食での指導について食材のありがたさや、また一生懸命献立をつくって、料理をつくってくださっている給食センターの方々についてなど、どのように小・中学校の生徒に指導しているのでしょうか。話題になっている完食指導について、本区はどのように考えているのかお知らせください。","respondent":"大関教育総合支援センター長","answer":"給食に関しまして、子どもたちがどのように給食をおいしく食べられるかというさまざまな工夫、それから完食という２つの観点についてご質問いただきました。","voiceIndex":42,"id":"exchange-019"},{"speaker":"松永委員","kind":"提案","question":"防災給食について伺います。防災の意識を高める効果もあり、ぜひ本区でも防災の日のみでもいいので、防災給食を行っていただきたいということを提案させていただきまして、この件については終わりたいと思います。関連しまして、給食の残菜について伺います。現在残菜などを少なくする本区の取り組みがありましたらお知らせください。そして残菜の量は年々どのように推移しているのか、改めて伺います。","respondent":"篠田学務課長","answer":"給食の残菜についてのお尋ねです。基本的に給食で最終的に残る残菜につきましては、週に２回ほど生ごみの回収を行いまして、それが最終的には動物の飼料に変わっていくといった形で、利用がされてあります。","voiceIndex":44,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ取り組んで、残菜を減らしていただきたいと思います。浜川小学校の改築についてなのですけれども、今後どのように変わっていくのか、そのスケジュールを、わかる範囲でいいので教えていただければと思います。","respondent":"有馬庶務課長","answer":"浜川小学校ですけれども、現在、今年度基本設計をやってあります。来年度は実施設計ということで、ここで基本的ないろいろ工事の工程が決まってくると思います。その中で具体的な工事がどのように進んでいくのかが、ある程度はっきりわかると思います。これが来年になります。","voiceIndex":46,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"私は１８６ページ、教育指導費についてお聞きしたいと思います。品川区内の公立中学生の学力について質問します。見過ごされてきた学びの貧困といいますか、低学力層が今、問題視されています。区内の公立中学生の低学力層の実態を、どのように把握しているか、そしてどのような状況になっているのかお聞かせください。","respondent":"熊谷指導課長","answer":"どのようにして把握しているかというところなのですけれども、こちらは今申し上げた国の調査、都の調査、そして経年で行っている区の学力定着度調査で確認をしています。","voiceIndex":49,"id":"exchange-022"},{"speaker":"須貝委員","kind":"確認","question":"実際にお子さんが学力をしっかりと身につけているかということを、教育委員会として確認しているとは思うのですが、ある程度身についている子はいいのですけれども、逆になかなかそこまで行き着かない、そしてそのまま学年がどんどん上がっているという、そのような実態をどのように捉えられていますか。","respondent":"熊谷指導課長","answer":"こういった一貫教育を行っておりますので、６年生から７年生に上がったときでも、昨年度までどういった学力傾向にあったか、そういったものが教員にも、また子ども、保護者にもわかるように、そういった状況で子どもたちの学力を捉えているところです。","voiceIndex":51,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"それをわかる範囲で教えていただきたいということと、先ほどテストを全国でやっているというお話でしたが、例えば数学Ａ、数学Ｂをピックアップしてみたときに、公立中学校の場合には、数学Ｂの正答率が全国平均で４６.９％と出ています。その前に先ほどお聞きした、今の疑問点もそうですが、どれぐらいの割合の子がどれだけの点数領域にいるのか教えてください。","respondent":"熊谷指導課長","answer":"分布なのですけれども、把握はしておりますが、今手元には資料がございません。ただ、正規分布の５段階だと７％ぐらいが、いわゆるＡ、Ｂ、Ｃ、Ｄ層のＤにいるかなです。","voiceIndex":53,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"それはもう３回目ぐらい聞いているのです。だから私は申し上げましたよね。なので、いや品川区はいいのだという根拠にはならないのではないですか。この辺は少し勘違いされていないのかなと思うのですが、同じ問題をやって公立、国立、私立で、このようにはっきりと正答率に違いが出ている中で、いや、うちは全国的にみていいからいいのだという理屈は通るのでしょうか。もう一度ご見解をお聞かせください。","respondent":"熊谷指導課長","answer":"国立の正答率は約７０％でしょうか。品川区の場合は数学に関しましては７０％ですので、国立と同等というふうになろうかと思います。","voiceIndex":55,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"平成２９年度の全国学力統一テストの、今、正答率というものがありますけれども、あくまでこれは昨年のものですからあれですが、数学Ｂが５１％、数学Ａが６７％。そして、あなたは大体このくらいのところにいますよと。このような実態があるではないですか。０点から２０点が十七、八名もいるという実態に対して、どのようにお考えなのですか。ご見解をお聞かせください。","respondent":"大関教育総合支援センター長","answer":"さまざまな配慮もしながら学んでいるところです。やはり無回答ということで０点になってしまうお子さんも、現実にはいらっしゃいます。","voiceIndex":57,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"今、お手伝いや部活動というお話をされました。でも、学校というのはそもそも子どもに知識を身につけさせるためにつくったのです。そうではないのですか。それで今、いや、そちらが優先だと言いますけれども、私立だって部活もやる、勉強ももちろんやっています。でも４０点以下だと落第するのです。留年する。もう１回ご見解をお聞かせください。","respondent":"大関教育総合支援センター長","answer":"ただし学校は教科の学習以外に社会活動、社会参加するための学校の役割というものがありますので、さまざまな観点から立派な区民に育っていただくために学んでもらっているところです。","voiceIndex":59,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"皆さん、小さなお子さんでも夢があります。私は将来弁護士になりたい、医者になりたい、あの職業につきたい、そのときに必要な基礎学力、基礎知識がなければ、そこを目指すこともできないではないですか。結局塾が支えている。このようなことではいけないではないですか。それに対してこのまま、悪い言い方をすれば放置しているのと一緒ではないですか。それに対してもう一度ご見解をお聞かせください。","respondent":"熊谷指導課長","answer":"そういう中で補習が有効と考えています。今、委員から補習についてご指摘ございましたけれども、全学校で補習を行っております。教員が行う補習を行っておりますけれども、それに加えて本年度から、コミュニティ・スクールが全校展開になりました。","voiceIndex":61,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"きちんと補習をしているのか、ではいつの何時から何時までやっているのだとか、地域の人に頼んでいるのならどのようにしてやっているのだとか、やはりそういう義務があるのではないですか。そのような部活推薦も今あるそうです。だけれども、最低限、このような低学力層というのですか、定着しないという子に対して、やはりもっと力を入れるべきではないですか。自分の子どもだと思って、いかがですか。","respondent":"熊谷指導課長","answer":"大学生、教員になりたいという大学生や、教員のＯＢ、地域の方、それから実際に区の講師等をやっていらっしゃる方が行っている中、校長や先生方も、やはり自分でも教えたいということで補習を行っているところですので、やっていないという学校はないと私は信じております。","voiceIndex":63,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"課長、では何で、このような成績の子どもが残ったままなのですか。申しわけないけれども、補習をきちんとして、子どもたちを支えているなら、このような状態になるでしょうか。０点から２０点が１８名、２１点から３０点が１０名、３１点から４０点が１１名、４１点から５０点が１５名、このような状況が生まれているのです。補習をしているかどうか本当に行って聞いてください。お母さんに「どうなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"学校の給食食材放射性物質検査費について伺います。検査の継続はもちろん、食材の単品検査への変更をやはり要望いたします。福島で検査している努力は私たちは重々承知しております。これからも学校の給食食材放射性物質検査は継続し、子どもたちの食の安全を守っていく姿勢を継続していただきたいと改めて要望いたしますが、いかがでしょうか。","respondent":"篠田学務課長","answer":"そういったことを踏まえまして、これまでもさまざま給食の放射性物質検査については、方法、対象、検査内容等を考えながら進めてきたところですけれども、ただいま申し上げたような状況も踏まえつつ。","voiceIndex":67,"id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"安全を継続し、確認していくことがとても重要です。放射性物質検査を継続していることにより、生活者ネットワークには保護者の方々から品川区の姿勢に対し感謝の声が多く届いております。今後も継続し、そして単品検査への検討をお願いいたします。次にＨＥＡＲＴＳのことについてお聞きします。ＨＥＡＲＴＳの相談件数、相談の多い項目についてお知らせください。","respondent":"大関教育総合支援センター長","answer":"その次が「家庭環境」、これも２０％を超えております。家庭環境といいましても、さまざまな要因があります。中には保護者自身に支援が必要なケースもありますので、どちらかというと、そちらに関しましては継続的にさまざまな、家庭訪問も含めました対応をしています。","voiceIndex":69,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"今のご答弁の中にも、ヤングケアラーの状態にある子どもの存在があると考えます。現在ヤングケアラーの状況にある子どもの数を把握されていたら、お知らせください。ヤングケアラーであることがわかったときには、どのような支援につなげているのか伺います。","respondent":"大関教育総合支援センター長","answer":"その中の全てが要支援の保護者の方ばかりではございませんが、個別のケースですので、具体的な部分を申し上げることはできませんけれども、親御さんに同行して保健センターの保健師につなぐ、あるいはさまざまな福祉の手続をするために一緒に行く。","voiceIndex":71,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"介護者本人の人生の支援は、介護する側、される側ともに救う制度です。ＨＥＡＲＴＳに助けを求めている介護に追われている子どもや、自分の介護のために子どもに頼る状態にある保護者、どちらも歯がゆい思いをされていると考えます。ヤングケアラーについては教育委員会も担当課と協力して取り組んでほしいと思いますが、見解を伺います。","respondent":"大関教育総合支援センター長","answer":"ただ見逃さずに、学校は１つの発見する窓口として重要だというふうに考えております。これは不登校であったり、あるいは虐待の可能性という部分も含めて気づく、１つの機能が十分にあるというふうに教育委員会も考えておりますので、引き続き関係各課との連携を努めてまいります。","voiceIndex":73,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほども支援策について伺いました。教育委員会としては義務教育の中で考える姿勢であると伺っております。次にまもるっちの使い方の指導について伺います。教育委員会の事務事業概要では、まもるっちについての記載が見つけられませんでしたが、子どもの健やかな成長を見守る教育委員会としては、この事業をどのように評価されているのか伺います。","respondent":"大関教育総合支援センター長","answer":"「１人になると危ないよ」という単元の中でしっかりと、万が一怖い目に遭ったときにはまずその場を離れる。離れてからまもるっちを引く、その上で１１０番をしたり、お店の人とか、近くの大人に助けを求めましょう、ここの指導を各学校では徹底しています。","voiceIndex":75,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"これまで子どもたちへのまもるっちの指導、認識が、教育委員会、生活安全担当や携帯電話事業者で共有されていないことを指摘してきました。その指導は、事業者と警察署の指導で行われており、危険を感じたらすぐにブザーを引くように子どもたちに伝えられていました。こういったそごが発生する原因について、教育委員会はどのようにお考えなのか伺います。","respondent":"大関教育総合支援センター長","answer":"その後、このまもるっちの指導については、まずその場を離れる、まもるっちを鳴らす、それから大人に助けを求めるということを、大人向け、教員向けのテキストの部分を関係警察署とも共有をしたところです。","voiceIndex":77,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"わかりました。ただ、教育委員会が市民科で子どもたちに伝えているまもるっちの指導について、先ほど紹介したセーフティー教室で指導していた警察署と事業者に伝えたところ、その指導については知りませんでしたと答えられました。まもるっちの指導は学校の先生が行うよう見直すことで、認識の違いを生まず、子どもたちも混乱をしないと考えますが、教育委員会の見解を伺います。","respondent":"大関教育総合支援センター長","answer":"各警察署のスクールサポーターの方、あるいは生活安全担当を中心に、毎月の生活指導主任会にもご出席いただいておりますので、その中で引き続き共通理解を今後とも継続して図ってまいりたいと思います。","voiceIndex":79,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"ですので、事業者任せではなく、教育委員会が主体として、やはり進めるべきなのではないかと考えています。機能に追加されたＨＥＡＲＴＳについて伺うと、担当課では答えられないとのことでした。子どもたちが利用するまもるっちについて、やはり子どもたちに直接かかわる教育委員会が主体となるべきだと、そのときにもやはり思ったのですけれども、見解を伺います。","respondent":"大関教育総合支援センター長","answer":"そのほか、実際には私立、国立等へ通っている区民に対しても、まもるっちは対応されているというふうに伺っておりますので、区民全体の部分は教育委員会の枠だけではとどまらず、区長部局全体で連携しながら進めているところです。","voiceIndex":81,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"そうなのです。品川区に住む小学生だったら、希望のある方はどなたでもまもるっちを所持できます。でも、そのチラシにも、やはりすぐに身の安全を守るという記載はなかったのです。それもＫＤＤＩの事業者が知らなかったのでそうなってしまったのだと思うのです。次に、人工芝生について伺います。教育委員会は校庭を人工芝生化していくことをいつ、どこの会議体で方針として持ったのか伺います。","respondent":"大関教育総合支援センター長、有馬庶務課長、菅生活安全担当課長","answer":"まもるっちの内容ですが、引き続き教育委員会といたしましては、生活安全担当とも連携をとりながら、さらに充実に努めてまいりたいと思います。そのような中で平成２７年から平成２８年にかけまして、少し学校の校庭のあり方について人工芝生化を導入してきた実績が少しずつ出てきてたため。まもるっちのパンフレットにつきましても、これも児童や、主に保護者あと協力者になるかと思いますけれども、こういった方に対しまして。","voiceIndex":83,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"まもるっちは防犯システムではなかったですか。児童見守りシステムだったと思います。ですので、今の答弁ではちょっと違うのかなと。ですので、教育委員会としてしっかり把握していく、それでも生活安全担当でというのであれば、きちんと趣旨が共有されるようにしっかりとしてほしいです。でなければ子どもたちが混乱してしまいます。本来の目的を忘れないでくださいということを申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"私からは１８９ページ、マイスクール運営費、品川英語力向上推進プラン、１９０ページ、図書館経費、８３運動経費についてお伺いをいたします。１点目にマイスクール運営費についてお伺いいたします。この通知を受けての指導内容の年間の変化につきまして、また、品川区適応指導教室設置要綱の目的の部分の解釈につきましても、ご説明をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"不登校児童生徒への対応の指針といいますか、考え方、それから実際のマイスクールの状況、それから学校への働きかけという３点のご質問をいただきました。","voiceIndex":89,"id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"区内のマイスクールの体制なのですけれども、五反田、浜川、八潮ということで充実していただいているということです。２点目なのですけれども、図書館経費についてお伺いしてまいります。平成２９年のレファレンスサービスの受付件数と実態を教えてください。","respondent":"大関教育総合支援センター長、横山品川図書館長","answer":"今中学校には、特別支援教室が全校配置されましたので、この特別支援教室を週１回程度だけの活用ではなく、それ以外の日には。平成２９年度のレファレンスサービスの実績ですが、全館合わせまして４万３,６５３件です。荏原地区の部分も含めまして、マイスクール五反田がもう少し充実することでカバーできるのではないかと現段階では考えているところです。","voiceIndex":91,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"レファレンスなのですけれども、こちら今件数のほうお伺いしましたが、件数だけではなかなか評価というものが難しいのかなとは思っております。レファレンスは、評価の仕方というものがしにくいというようにも言われておりますけれども、ぜひ区民の皆様のあらゆる調査研究を助けるレファレンスの評価の重要性について認識していただくとともに、その重要性について区のお考えのほうをお伺いしたいと思います。","respondent":"横山品川図書館長","answer":"ただ、委員ご指摘のように、中には調査研究のためにテーマを絞っていただいて、それについて図書館員が一緒に考えて、どのような分野の本がいいかということを照らし合わせたり、また、難しいケースにつきましては。","voiceIndex":95,"id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"３点目に８３運動についてお伺いをいたします。８３運動の目的と現在の取り組み状況を教えてください。４点目として英語教育、品川英語力向上推進プランについてもお伺いしてまいります。TOKYO GLOBAL GATEWAYがスタートいたしました。英語を使う実践の場として、どのように活用を現在されておりますでしょうか。","respondent":"有馬庶務課長、熊谷指導課長","answer":"８３運動についてお答えいたします。８３運動は子どもの登下校時に買い物や花の水やりなど、外に出る機会をつくって子どもを見守ること、これを生活の一部にして子どもたちの安全を守っていこうということが目的です。全３１校中１７校がTOKYO GLOBAL GATEWAYで活動を行いまして、既に５校が実施しております。来年度は２４校が実施する予定です。","voiceIndex":97,"id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"さまざまなカリキュラムがあると思うのですけれども、使える英語力を身につけるという目標のために、やはり実践の場というものが、今回このTOKYO GLOBAL GATEWAYの活用の状況をお聞きした上でも、やはり有効かと思いますので、今後各プログラムの参加の学校数を増やしていただいたり、また学年の幅を広げたりなど、いろいろ有効な方法を検討いただいて、推進していただきたいと思います。","respondent":"熊谷指導課長","answer":"毎年４０名ぐらいの子どもたちも参加しているのですけれども、そういったことも含め、今後はさらに一番近い江東区にあるTOKYO GLOBAL GATEWAYの活用なども考えて、さらに検討していきたいと考えています。","voiceIndex":100,"id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ推進していただきたいと思います。８３運動については大変いい取り組みだと思いますので、ぜひ地域の方に啓発を引き続きお願いしたいということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"１９２ページ、学校教育費、１８６ページ、教育指導費、１９０ページ、図書館経費について伺っていきます。それに関連して、すまいるスクールでの夏季休業中の配食サービスの活用は子ども未来部のほうに求めましたけれども、例えば給食室の改修となったときに、一、二週間ほど学校が始業した後も工事にかかる場合には配食サービスも視野に入れて検討していただきたい。","respondent":"大関教育総合支援センター長、菅生活安全担当課長","answer":"全国的には通学に非常に時間がかかる地域があったり、あるいは私立の学校のお子さんですと、電車に乗り継いで１時間半、あるいは２時間かけて通っているというケースもあると伺っております。そういったことで、この登下校のメール配信システムよりもさらに進化しているシステムだというふうに認識をしておりますので、この登下校のメール配信システムにつきましては、教育委員会やいろいろな部署ともそれぞれ相談しながら。","voiceIndex":104,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"今、生活安全担当課長にもご答弁いただきましたけれども、ご答弁いただいた内容をわかった上で、お聞きしております。ですから地域性もあると思いますが、今後さらにそうした防犯面、それから交通安全も含めて子どもたちの安全が確保されるような体制の構築をしっかりと連携をとってお願いしたいと思います。次に教育指導費についてですが、ＡＥＤ教育、それからがん教育について伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"家庭教育講演会として、家族ぐるみでがんについて考える講演会なども、教育委員会としては予定しておるところです。","voiceIndex":107,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に図書館経費について伺いたいと思います。外観としては。もう既に試写会等、まさに戸越の地域の方々がしっかりと応援していこうということで、いろいろな取り組みをしていることを伺っています。ですから、そのような情報や、いよいよこれから映画が始まりますけれども、そうしたものの活用も含めて、これからどのように魅力ある図書館をつくっていくのかというところを教えてください。","respondent":"横山品川図書館長","answer":"委員よりご指摘いただきました品川を舞台とした映画につきまして、承知しておりませんでした。これから調査に臨みたいと思います。所蔵についても、増やすように検討します。","voiceIndex":109,"id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"区民の本棚として、しっかりとこれから展開していただきたいと思います。読むことというのは心を耕すこと、本そのものの中に知恵や幸福があるわけではない、本来それは全部自分の中にあるのだと。それを読書というくわで自分の心、頭脳、命を耕してこそ、それは芽を出し始める。まさに図書館がそのような存在になると思いますので、ぜひ区民の方の本棚として、これからも充実を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-050"},{"speaker":"おくの委員","kind":"質問","question":"成果報告書の１８７ページ、教育指導費の中の学力定着度調査経費にかかわって、いわゆる学力テストについて伺います。そこでお伺いします。先ほども少し回答されているのですけれども、この品川区で行われている全国学力・学習状況調査と品川区学力定着度調査において、この成績下位者、下位層はどの程度いるのでしょうか。そしてそれは着実に減っているのでしょうか。あるいは逆に増えているのでしょうか。","respondent":"熊谷指導課長","answer":"今、手元に具体的な資料はないのですが、ただ正規分布の５段階にしますと、１に当たるところが７％というような状況です。","voiceIndex":113,"id":"exchange-051"},{"speaker":"おくの委員","kind":"質問","question":"１に当たるところというのは最下位層、５分類の内一番最下位に分類されるのが７％、平成３０年度はいたという理解でいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-052"},{"speaker":"おくの委員","kind":"質問・要望","question":"ではまた後ほど、資料を別の機会に、増減変化なども交えて教えていただきたいと思います。そこでお伺いします。品川区は、この全国学力・学習状況調査、あるいは品川区学力定着度調査を行っている学校において、勉強好き、あるいは勉強嫌いの調査をされているのでしょうか。","respondent":"熊谷指導課長","answer":"こうした国の調査、それから本区で行っている保護者アンケート、児童・生徒アンケートありますけれども、そちらで勉強は好きかという大きくくくったものはないのですが、教科ごとの、例えば国語は好きですかですとか、英語は好きですかといった調査は。","voiceIndex":120,"id":"exchange-053"},{"speaker":"おくの委員","kind":"質問","question":"やはり全般的に勉強、つまり学ぶことが好きなのかどうなのかということを、私としては子どもたちに聞いてほしい。先生にも、あるいは教育委員会というか、教育に携わる方にはきちんと、喜びを感じながら学んでいるのか、言われるから仕方なく学んでいるのか、その辺を見きわめた上で、その喜びを感じてもらうような教え方をしてほしいのです。検討をお願いいたしますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"それを教員自身が、どこにつまずきがあったのか、１００人の教員で全部分析しました。それによって、子どもたちにとってわかる授業、そして子どもたちに真の意味で学力がつく授業への転換ということで、今回品川区立学校教育要領を改訂したところです。","voiceIndex":122,"id":"exchange-054"},{"speaker":"おくの委員","kind":"意見","question":"最後に、課題の見られた問題というものを見させてもらったので、少しだけ感想を述べさせてもらいます。この問題を見た限り、私は余りいい問題だと思いませんでした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-055"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは１８８ページの理科観察実験支援事業に関連して、理数系科目の教育についてお伺いをいたします。時間があれば１８９ページ、オリンピック・パラリンピック教育推進事業についてお伺いをいたします。理数系科目の教育についてなのですけれども、ぜひとも理数系科目を重視していただいて、どんどん充実していっていただきたいと考えております。","respondent":"大関教育総合支援センター長","answer":"今ご指摘いただいたように、理数系教育の充実は、本区にとりましても重要な課題の１つというふうに認識しております。","voiceIndex":127,"id":"exchange-056"},{"speaker":"筒井委員","kind":"質問・要望","question":"非常にユニークな取り組みをやられているということで、引き続き理数系教育を充実していっていただきたいのですけれども、課題があると思うのですが、今その理数系教育において、品川区の課題は何でしょうか。","respondent":"大関教育総合支援センター長","answer":"実際に実験活動を確実に学校で行った中で、実験器具の名称などは実体験の中から子どもたちは学んでいきますので、教科書で覚えるだけでなく、実験を確実に行える、そのための支援員の配置なども行っているところです。","voiceIndex":129,"id":"exchange-057"},{"speaker":"筒井委員","kind":"質問","question":"先ほど言った指導者の方が不慣れだとか、不足されているということも課題なのですけれども、この指導者不足、不慣れということと、理科の成績が余り伸びないということについて、今後品川区としてはその解決法をどのようにお考えになっているのでしょうか。","respondent":"大関教育総合支援センター長","answer":"先ほど申し上げました実験の強化以外に、やはり子どもたちがしっかりと興味を持てる題材、学習の場を提供できるように、教員の研修も充実が必要だと考えておりますので、次年度各校理科教員を対象とした研修の充実も含めた検討を、今行っているところです。","voiceIndex":131,"id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"成績が下がっているということについては、どうお考えになっているのか、そしてこれをどう克服していくのかということについて、何か対策というものは考えられているのでしょうか。","respondent":"熊谷指導課長","answer":"ですので、現在作成していますのが、理科を専門とする教員で、教育会でプリント教材をつくっているところなのですけれども、学年間のつながり、終わったところ、既習の事項についてもう一度学習したり、また小学校前期課程の内容を後期課程とどのように結びついているのか。","voiceIndex":133,"id":"exchange-059"},{"speaker":"筒井委員","kind":"質問・要望","question":"は興味を持っていただくということと、そして、そこで興味を持っていただいたというだけではなく、繰り返しやっていくと。そして知識を定着させていくということが非常に大事だと、私も今お話を伺ってそう思いました。","respondent":"大関教育総合支援センター長","answer":"これを機会に先方からは、ぜひほかの中学校とも連携を深めたいというご提案等いただいて、教育委員会としても前向きに検討を進めているところですので、今後とも高専などとの連携も含めまして、理数、あるいはものづくりまで発展させた形で。","voiceIndex":135,"id":"exchange-060"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひそうした教育施設との連携、そして繰り返しになりますけれども、やはり理数系科目に、まず興味を持っていただくと。そのためには授業の工夫というものも必要だと思いますので、その点もよろしくお願いします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-061"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"成果報告書１８９ページ、３目教育指導費の中のオリンピック・パラリンピック教育推進事業、１９０ページ、４目社会教育費、ＰＴＡ関係費について質問をします。初めに東京２０２０オリンピック・パラリンピック競技大会、オリンピック・パラリンピック教育推進事業なのですけれども、区内開催競技と応援競技の３競技について質問をします。その取り組み内容と、現状をお知らせいただきたいと思います。","respondent":"熊谷指導課長","answer":"他の競技体験なのですけれども、さまざまやっておりまして、例えば柔道、体操、マラソン、競歩、パラリンピックですと車椅子テニス、車椅子バスケ、ゴールボール、マラソン、トライアスロン、トライアスロンの場合は見るということが中心になりますけれども。","voiceIndex":139,"id":"exchange-062"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それぞれそういった体験ができて、子どもたちのオリンピックに向けての機運醸成になっているかと思います。それで、これは東京都の委託事業、今課長がおっしゃった事業の中で、オリンピック・パラリンピック教育アワード校と、あとはパラリンピックの競技応援校ですか、平成２９年度はアワード校が５校で、本年、平成３０年度は７校、あと２園の９つになるのですね。","respondent":"熊谷指導課長","answer":"今ご指摘のとおり、平成２９年度はアワード校が５校、そしてパラリンピック応援校が１校でございました。平成３０年度は昨年度の取り組みが都に評価されまして、アワード校が７校２園、そしてパラリンピック競技応援校が１校ということになっております。","voiceIndex":141,"id":"exchange-063"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうするとこのアワード校、平成２９年度、平成３０年度も城南小学校や京陽小学校、延山小学校、その辺だと思うのですけれども、学校の選定についてです。小中一貫校、そして分離型の小・中学校というのは、どのように選定をされているのかお聞きしたいと思います。","respondent":"熊谷指導課長","answer":"ですので、今回幼稚園が２園となっておりますけれども、それぞれ中身が異なっておりまして、八潮わかば幼稚園は日本人としての自覚と誇りを中心に、また、城南幼稚園はスポーツ志向を中心にというように、それぞれの園。","voiceIndex":143,"id":"exchange-064"},{"speaker":"高橋（伸）委員","kind":"意見","question":"それで、関連しまして、区内開催・応援３競技体験教室が当初予算ですと６３０万円余、決算が３５０万７,０００円で、それについての講演等講師謝礼が、当初予算ですと６２０万円で決算が７４５万円余なのです。予算と決算を比較したときに、区内開催・応援３競技体験教室が減っているのに、講演等講師謝礼が増えているということは、どのようなことでそうなっているのかお知らせをお願いしたいと思います。","respondent":"熊谷指導課長","answer":"本区の３競技体験教室なのですけれども、それぞれクラス単位でやったり、学年単位でやったりしております。その中で、学校によって学級数の差があったり、それに伴って時間が異なってまいりますので、実際行ってみたところ余裕があったというところです。","voiceIndex":145,"id":"exchange-065"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうしますと、来年度もそういった形がとられれば、金額の変動等はあり得るということですよね。そうするとオリンピアンを呼んだりなどということも、来年度も続けていくということでよろしいでしょうか。","respondent":"熊谷指導課長","answer":"オリンピアン、パラリンピアンにつきましては、次年度も引き続き招致してまいりたいと考えています。","voiceIndex":147,"id":"exchange-066"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１９０ページ、ＰＴＡ関係費に関連をしまして、質問をします。品川区内にも、さまざまな特色があり、地域性がある学校が当然あります。そのようなときの対策というものは、学校単独の場合もあるかもしれませんけれども、あとＰＴＡや近隣の、地元町会の人などとの連携性が当然かかわってくると思うのですが、学校としての近隣の対策はどのように取り組んでいるのか教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"あるいは楽器の音が漏れないように窓を確実に閉めたり、カーテンをするなどの配慮は個別に、可能な範囲で学校も配慮しつつ、近隣の方にも何とかご理解いただけるようにお願いに上がるということが基本的な対応です。","voiceIndex":149,"id":"exchange-067"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私もお手伝いをしたこともあったのですけれども、おやじの会で清掃をしたり、学校の用務員の人たちと一緒にやったり、ＰＴＡ単独でやったときもあったのですが、今、現状がそのような状態なので、私の言いたいことは、やはり地元の方たちがボランティア活動でせっかくきれいにしていただいているのに、肝心な池の水が濁っているというか、もう見えない、魚がいることもわからない状態なので。","respondent":"有馬庶務課長","answer":"ただ、学校活動だから全て認めるよう求める形はなかなか難しいのかなということを考えておりまして、例えばポンプの音をもう少し抑えるような工夫や、規模を少し小さくするなど、こちらもある程度条件を示しながら。","voiceIndex":151,"id":"exchange-068"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この問題は旗台小学校だけではないと思います。ぜひその辺のところは子どもたちのためにも、この環境学習のためにも、改善をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問","question":"１つ目は市民科に関連しまして、士業による外部講師の授業について伺います。私ども公明党からは区議が３名、自民党からは１名、国民民主党からも１名、模擬授業を体験させていただきました。そのほか、士業による教育というものは幾つか行われていると聞いておりますけれども、それについて、ほかにどのような教育を行っているのか、また、それに対しての品川区としての支援があるのかどうか伺います。","respondent":"大関教育総合支援センター長","answer":"昨今市民科の充実を図る中で、社会保険労務士の方、あるいはさまざまそういった士業の方のご協力をいただきたいという学校からの要望があった際に、専門的なプロの方にご指導いただくための講師料が必要かどうかも含めて。","voiceIndex":155,"id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問・要望","question":"さまざまな士業の方の授業については、恐らく各会派にも要望が来ていて、品川区では従来、今のところは志で、いわゆる交通費とか、人件費といいますか、報酬という形で会のほうで持っていると思うのですけれども、ぜひこれを品川区のほうでも、今若干、ご答弁ありましたけれども、最低限度の経費については、品川区としても、教育委員会としても支援をされていく必要があるのではないかと思いますが。","respondent":"大関教育総合支援センター長","answer":"どういった内容が必要なのかも含めて、ぜひ検討しながら、一度に全てということは難しかったとしても、ぜひ行いたいという学校を応援していけるように、準備はしていきたいと考えています。","voiceIndex":157,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１９６ページ、学校給食費から、関連して給食に使われる牛乳について伺いたいと思います。それに関して、ちょっと私ども区民からさまざまなご意見があったので伺いたいのですが、学校給食に関して、毎日牛乳を飲みますけれども、まず基本的なところから、なぜ牛乳なのかと。なぜ緑茶ではだめなのか、その理由について教えていただきたいということが１つ。","respondent":"篠田学務課長","answer":"国の補助等の話でございましたけれども、現在国からは牛乳１本当たり４銭の補助金が出ているということで、こちらの手続に関しても学校給食会が行っているものです。","voiceIndex":159,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問","question":"牛乳の安定供給のために東京都学校給食会で一括して手配をされているというご説明で、全国でほぼ一律の制度になっている。２３区全てでこの紙パックになっているのかどうかというところが１点です。それともう１点、プラスチックストローの件で伺います。給食を年間で何日間食べているのか、これについて教えてください。誰がこのストローを卸しているのか、いわゆる納入しているのか、簡潔に教えてください。","respondent":"篠田学務課長","answer":"それから給食ですけれども、実際実施日数はそれぞれの学校微妙に違ったりもするのですが、おおむね１つの学校で年間で１９５食程度の給食を食べさせているところです。","voiceIndex":161,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"確認","question":"教職員を入れると合計約２万２,０００人が、品川区内の小・中、義務教育学校で毎日ストローを２万２,０００本使っている。１９５日で換算をすると、大体年間で４２９万本が品川区内で消費をされているということを確認させていただきました。最後に英検について伺いたいと思います。いろいろ聞きたかったのですが余り時間ないので、平成２９年度の志願者数に対する合格者数とその割合を教えてください。","respondent":"篠田学務課長","answer":"平成２９年度の英検の志願者数です。今のところ、年３回なのですけれども、実は３回分がまだ英検協会から上がってきていないので、１回目と２回目の分だけですが、志願者数が２,０７５名、合格者数が１,２１９名で、合格率が５８.７％となっています。","voiceIndex":163,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私は英検自体にすごい思い入れがあって、私自身も、２０年前ですけれども、英検を順調に受けまして、大学時代までに準１級を取得して、その後、英検１級の１次試験だけ受かったのです。２次試験の面接でこてんぱんにやられまして落ちました。こういったことが必要ではないかと思うので、ぜひ研究をしていただきたいと思うのですが、いかがでしょうか。","respondent":"篠田学務課長","answer":"現在の英検の助成につきましては、まず英語検定に関心を持っていただくといった前提で、こういった形で幅広の制度となっています。この先、委員のご指摘のような形の導入もあり得るのかどうか、研究しながら現状の推移を見守っていきたいというふうに考えているところです。","voiceIndex":165,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"１９１ページ、大崎図書館について伺います。さまざまな多くの方に利用されていたことが、ここからもわかります。今からでも解体計画は中止し、生活圏が全く違う御殿山小学校西側敷地の図書館とは別の図書館として必要な補修をし、再整備することを求めます。初めに、もとの大崎図書館の解体はいつ着手するつもりなのか伺います。解体計画は中止するよう求めますが、いかがでしょうか。","respondent":"立木経理課長","answer":"大崎図書館のほうですが、こちらのほうは教育の行政財産から普通財産に今現在切り替わっておりまして、今解体の設計が終わり、これから解体工事の着手に移るというような段階になっております。","voiceIndex":169,"id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区はこれまで移転の理由を、老朽化を契機にしてＳＨＩＰとの連携、御殿山小学校の隣地で文教施設としての施設が求められたこと、そういったことを総合的に判断して決めたなどと説明し、２９号線整備の代替地の話は、移転判断後に都から話があったとの説明でした。大崎図書館の移転理由は、本当は２９号線道路のためだと、区民になぜ説明しなかったのか、理由を伺います。","respondent":"柏原企画調整課長","answer":"大崎図書館の移転にかかわる部分です。大崎図書館移転の理由といいますか、経緯です。これはこれまでもずっとご説明してきた中で、今委員もご紹介いただきましたけれども、ＳＨＩＰが新しい開発のエリアででき上がったと。","voiceIndex":171,"id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、今課長がおっしゃった答弁というものは、全く区長の挨拶と違うのです。２９号線で移転することになり、どうしたものかと思っていたが、こうした場所があって本当によかった。この区長の発言が２９号線と関係ないと主張されるなら、その理由をしっかりとご説明いただきたいと思います。","respondent":"柏原企画調整課長","answer":"結果として２９号線に関して東京都のほうからの打診があって、それでこうした移転にかかわったところでの場所について協力をするという結果になったですので、トータルとしてはそのような流れになっておりますけれども、委員おっしゃっているような形ではなくて。","voiceIndex":173,"id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"ここに区長もいらっしゃいますので、ぜひ、なぜそのような発言をしたのか、この大崎図書館の移転というものは、この２９号線のためだったということではないのか、区長にお伺いしたいのですがいかがでしょうか。","respondent":"柏原企画調整課長","answer":"その後に東京都のほうから道路に関する協力ということの要請があって、形としてはこのような経緯で、今動いているというものです。ですので、それをトータルの話でお話を申し上げたと先ほど申し上げたとおりでございまして、そういったところでは矛盾はないと考えています。","voiceIndex":175,"id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"矛盾があるのです。すごく矛盾があるのです。区長が挨拶でおっしゃったことは、今のご説明と全く違うのです。そうであるならば、この落成式の場で区長は、地域の方も参加した、この多くの議員も参加していましたけれども、こうした場で区の方針とは全く違う間違ったことをおっしゃったということなのですか。どうなのでしょうか。伺います。","respondent":"柏原企画調整課長","answer":"間違いということではなくて、私は再三ご答弁申し上げているのですが、今までの経緯をお話しいたしました。そういった経緯をトータルして挨拶のときにお話しさせていただいたというものですので、矛盾はないと思ってあります。","voiceIndex":177,"id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"この大崎図書館をめぐっては、もちろんそのもととなる道路の整備計画そのものに反対される方もたくさんいらっしゃいます。区長が答弁に立てないということは本当に、立たないのか、立てないのかわかりませんが、非常に私はおかしいと思うし、説明責任すら果たしていないと思います。なぜ２９号線の整備が、この大崎図書館の移転の目的だということを品川区は隠すのでしょうか。伺いたいと思います。","respondent":"柏原企画調整課長、横山品川図書館長","answer":"それに対して、そういった結果判断があって動くということが決まった中で、東京都のほうから２９号線のところで代替地がないか協力願えないかというお話をいただきました。大崎の移転に関しましては、惜しむ声もたくさんいただきましたが、移転後につきましては非常にご好評を得ております。","voiceIndex":179,"id":"exchange-081"},{"speaker":"本多委員","kind":"確認","question":"このことは４年半議論をしております。１９１ページを見ますと、わずか５週間で４,５５４冊を取り次ぎ、貸し出している状況がありますけれども、そうしたことをやはりこの大崎図書館、３５年間使ったところが使えなくなっても、西口取次施設とこれからできる芳水小学校の分館、ならびに移設した御殿山地区の大崎図書館で利用者が機能を、しっかりと使えるというところを確認したいと思います。お願いします。","respondent":"横山品川図書館長","answer":"今後も分館の準備を着実に進めまして、３館で大崎地区の図書環境を充実させていきたいと思います。","voiceIndex":182,"id":"exchange-082"},{"speaker":"本多委員","kind":"質問","question":"ぜひこの大崎図書館の機能をさらに充実できるように、利用者の目線に立って、しっかりこの４年半議論してきた、積み上げてきたもの、やはりこれは地域の声なのです。そうしたものをしっかりとまたアピールしてください。安藤委員のような質疑が、もうこれ以上出ないことを私は願います。本当に残念だと思って関連質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"私からは１８６ページの中段より少し下にありますけれども、いじめ防止対策費３,６８７万円余からですが、このいじめ根絶協議会４０万円余、そしていじめ対策委員会３０万円余ですけれども、協議会と委員会との違い、何となく、いじめ対策委員会というものは作戦を練るような委員会、そして根絶協議会というものは完全にいじめを根元からむしりとるようなイメージですが。","respondent":"大関教育総合支援センター長","answer":"もう一つございました対策委員会につきましては、これはいざ、ないにこしたことはないのですが、万が一重大な事案が起きた場合には、教育委員会が設置する調査組織にもなる委員会となりますので、学識経験者、弁護士、あるいは臨床心理士などの方々をメンバーに。","voiceIndex":186,"id":"exchange-084"},{"speaker":"木村委員","kind":"質問","question":"いじめは重大な人権侵害でもありますけれども、どこの子どもにも、そしてどの学校にも起こり得る。一般的にいじめ等は水面下で行われることが大変多いわけでありますけれども、学校側や先生はどのように察知をすることが多いのでしょうか。","respondent":"大関教育総合支援センター長","answer":"さまざまな形で発見、ＳＯＳを見逃さない仕組みについて、今充実に向け努めているところです。","voiceIndex":188,"id":"exchange-085"},{"speaker":"木村委員","kind":"意見","question":"自分の子どもがいじめに遭っていることがわかった場合、文句を言い、どなり込んでいく親御さんというものも、昔はよくあったものでありますけれども、今現在もそういうこともあろうかとは思いますが、冷静に考えた場合に、親は今どのような行動をとったほうがいいのか、その点もお聞かせください。","respondent":"大関教育総合支援センター長","answer":"保護者同士の話し合いの場面等に学校が立ち会う場合もありますし、あるいはあえて加害という言葉を使うならば、加害者側にも何か加害となった背景要因という部分があろうかと思いますので、そこにも丁寧にしっかりと教育指導者として学校は携わっていく。","voiceIndex":190,"id":"exchange-086"},{"speaker":"木村委員","kind":"意見","question":"いじめた児童・生徒に対して厳しく注意し、罰することも多くあろうかとも思います。私はその逆でありまして、いじめた本人に対する心の寂しさや、ほかの原因究明を含めたやさしさが必要と思いますけれども、そういった生徒の身になって、より一層深くかかわってほしいと思いますが、どのような接し方をするのかお聞かせをください。","respondent":"大関教育総合支援センター長","answer":"今、委員よりご案内いただいたように、いじめた側のお子さんの、何か寂しさ、背景要因は何なのか、やはりそこに気づくことは重要なことだと我々も認識しております。","voiceIndex":192,"id":"exchange-087"},{"speaker":"木村委員","kind":"意見","question":"いじめを通り越した事件と言うべき行為が過去にあったのか、もしあった場合にはどのように対処をしたのか、それを繰り返さないようにするためにはどのようなフォロー、そして手当てが行われたのか、お聞かせをください。","respondent":"大関教育総合支援センター長","answer":"個別のケースですので具体的なお話は申し上げられませんが、家庭での生活がその子自身にとってなかなか難しいようなケースも時にはあります。そのような場合には、やはり専門機関と一緒に相談しながら、本人のよりよい生き方のためにどうすべきか関係機関と相談をします。","voiceIndex":194,"id":"exchange-088"},{"speaker":"大沢委員","kind":"質問・要望","question":"１８６ページ、言語活動の充実を図る授業の工夫、それと１８８ページ、道徳教育推進事業、それと１８９ページの保幼小連携推進経費ということで伺っていきたいと思います。特色がその部分、従前のものと比べてあるのであれば教えてください。","respondent":"大関教育総合支援センター長","answer":"同時にあわせて言語能力を向上させるための研究校なども、これまでの間取り組んでまいりましたが、大きく流れとして、この１０年間の中で変わってきたといいますか、これはもう世の中全体の流れですけれども、アクティブラーニングの充実ということで。","voiceIndex":197,"id":"exchange-089"},{"speaker":"大沢委員","kind":"質問・要望","question":"この言語活動の充実において目的とする、最終到達点として子どもたちに求める目的、成果、どのようなものを想定されているのか教えてください。","respondent":"大関教育総合支援センター長","answer":"しっかりと自分の伝えたいことを相手にわかってもらう、それから相手の意図していることを読み取る、まさに発信と受信、この部分をしっかりと育てることによって、国際的な社会の中で日本人として通用していく、そこがまず基本として大事だと。","voiceIndex":199,"id":"exchange-090"},{"speaker":"大沢委員","kind":"質問","question":"思い起こせば、この一番顕著な例というか、わかりやすい例、かつてＮＨＫでやっていたサンデル教授の『ハーバード白熱教室』、あれがアクティブラーニングの一番わかりやすい、見ていてわかりやすい形だと思うのですけれども、この中でアクティブラーニング、今品川区では義務教育についての言語活動の充実で、アクティブラーニングになりますと、私の知り得る見地では、これは一歩進んだ段階、いわば高校。","respondent":"大関教育総合支援センター長","answer":"今、大きな広い意味でのアクティブラーニングについて、委員よりご案内いただきましたが、まさに高等教育機関の中で講義を受けるという形から、しっかりと考えていくためには、自分から発信していく、そして相手に伝える、相手の意図を読んでいく、そういった授業のほうに。","voiceIndex":201,"id":"exchange-091"},{"speaker":"大沢委員","kind":"質問","question":"その中で相手に伝える、双方向性という点から見れば、ディベートという手法もあるわけであります。ただ私は思うのですけれども、日本人はやはり相手の立場を考えつつ物事を進め、物事を話す、物事を考える傾向がありますので、ディベートは日本人になじまないのではないかなという気がしますが、そこの部分は教育委員会としてどのようにお考えなのでしょうか。","respondent":"大関教育総合支援センター長","answer":"こういったところをしっかりと指導を行っていきつつ、場合によってはディベートという場面も、市民科の学習の中では何かについて子どもたちが話し合う１つの手法、今この場では意見が対立するけれども、これは決してけんかではない。","voiceIndex":203,"id":"exchange-092"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど来きれいな日本語、きれいなという言い回しで、日本語の美しさを言われましたが、そこには語彙力が必要でありまして、語彙力を高めるための取り組みは、今どのようにされているのでしょうか。","respondent":"大関教育総合支援センター長","answer":"多分語彙力は、例えば文字で認識するだけではなく、日常生活の中からどのように自分がエピソード記憶していくのか、自分の体験に直接照らし合わせることで、言葉、語彙の意味がしっかりと自分の生活に結びついて。","voiceIndex":205,"id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"書いて自分の表現をまず外にアウトプットするという、これがまず語彙力を高める方法の１つだと思いますし、一番洗練された語彙をということでは身近に新聞というものがありまして、我々大学のときはよく朝日新聞の「天声人語」というものが試験に出てまいりましたもので、よくそこのところをチェックしたものですけれども、現場におきまして、先生方の裁量にもよるかと思うのですが。","respondent":"熊谷指導課長","answer":"そういった中で、これから戸越台中学校、山中小学校が、新聞を活用した授業を研究していくということを伺っておるところです。明治以降、特に明治時代の小説等にも、美しい言葉がたくさん出てきます。読書を通して語彙力を高めていくということも重要であろうかと考えます。","voiceIndex":207,"id":"exchange-094"},{"speaker":"大沢委員","kind":"質問・要望","question":"１つだけ、英語の語彙について伺いたかったのですが、和製英語というものがありますが、外国人にはこれが全然通じません。そこのところは英語教育の中で、言葉としてどのように教育をされ、子どもたちに教えていらっしゃるのか。和製英語という単元、１つのプログラムで先生方が１つのユーモア、ユーモラスな部分として教えていらっしゃる時間といういうものはあるのですか。","respondent":"熊谷指導課長","answer":"特に年代を越えて高齢者の方とお話しするときにも、和製英語でないと伝わらないということもあろうかと思います。ですので、日本人として和製英語は大事にしていきたい言葉の１つであろうかと考えています。","voiceIndex":209,"id":"exchange-095"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと、やはりアウトプットする先生方にいろいろとご苦労、毎日いろいろな予習等々で大変だと思うのですけれども、子どもたちに伝えるには先生方の話術なり、話し方のスキルが必要だと思うのです。研修等々で行われているとは思いますけれども、そこではどのようなことが行われているのか、ご披露していただきたいと思います。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"プロの方のお話を聞くような機会などもありますし、また民間のそういった講習会などを夏休み期間中などに自主的に受けている教員も多うあります。それから今年は劇団四季の方から発声法ですとか、それから子どもたちの前でどのように伝えればいいのかというような、そういった授業を行っていただいたところです。","voiceIndex":211,"id":"exchange-096"},{"speaker":"大沢委員","kind":"提案","question":"これが適切な提案かどうかはわかりませんけれども、やはり話のプロ、それははなし家でありまして、古今亭志ん朝、古今亭志ん生、三遊亭圓生、三遊亭圓楽という、はなし家の間合いというか、話すタイミングというか、聞き手との距離のとり方など絶妙だと思うのですけれども、その辺は身近に活用できるものですので、授業中にやってしまうとまた公務との境がつかなくなってしまいますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-097"},{"speaker":"たけうち委員","kind":"提案","question":"私は成果報告書の１８７ページ、市民科・各教科充実経費、１９４ページ、通学安全確認業務等委託について伺います。初めに市民科については防災教育についてです。その際、品川区としてこども防災手帳というものの作成を提案した際にご答弁いただいてきましたが、すでに、改訂版の防災ノートを品川区では７月に低学年から中学生まで漏れなくお配りをして取り組んでいるということを伺いました。","respondent":"大関教育総合支援センター長","answer":"発達段階に応じて３分冊の内容を利用するのですけれども、これはある単元の一部分で、防災教育の一環として、例えばＡＥＤの使い方で使う場面のことであったり、あるいは、低学年の子ですと。","voiceIndex":216,"id":"exchange-098"},{"speaker":"たけうち委員","kind":"質問","question":"ぜひ毎月訓練を行っているとおっしゃっていたので、その後に、本当に１ページでも２ページずつでも、かまわないのでしっかり取り組まれると本当に力になるなと思いましたので、お願いしたいと思います。この教材の中にも書いてありますけれども、毎月１日、１５日を中心に、１７１の災害用伝言ダイヤル。","respondent":"大関教育総合支援センター長","answer":"毎月行う訓練が、１日、１５日に当たるかどうかは、その月の状況もあろうかと思いますが、今ご提案いただいたように、例えば全校児童が体育館に集まった際に代表の電話機、校長の携帯電話を活用するぐらいしか今、方法は浮かびませんが。","voiceIndex":218,"id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問・要望","question":"次に行きますが、１９４ページの通学安全確認業務等委託についてですけれども、昨日もちょっと一部出ていたかもしれませんが、通学路のブロック塀の件で、いわゆる今回の大阪府北部地震を受けて、品川区におきましても通学路においての危険なブロック塀の場所なども各学校現場で調査をしていただいていると思いますけれども、その状況と。","respondent":"有馬庶務課長","answer":"それで今後の所有者へのアプローチというところですけれども、ここが非常に難しいところでございまして、学校の人たちが見て、他人の財産を勝手に危険だと指摘するのはなかなか難しいというところもありますので、まずは建築基準法で言われている２.２ｍ以上の壁があるかないか。","voiceIndex":220,"id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問","question":"それができるまでは、今おっしゃったように学校でも通学路の安全マップと危険マップというのでしょうか、これをつくっていらっしゃるかなと思うのですが、その中に学校で点検したものを反映させていくということも大事かなと思いますので、その件とあわせて見解をお示しください。","respondent":"有馬庶務課長、大関教育総合支援センター長","answer":"前段のほうの建築課との連携ですけれども、建築課ともそういった情報のやりとり、連携をとりまして、今通学路、小学校入学の全家庭の通学路につきましては建築課のほうに情報提供をして。その場面の中で、当然交通事故の観点以外にも、やはり危険な箇所という部分は今後は出てくることかと思いますので、関係機関ともその辺の部分は情報を共有しながら、よりよいものにしていくための検討を協議してまいります。","voiceIndex":222,"id":"exchange-101"},{"speaker":"たけうち委員","kind":"質問・要望","question":"あわせて、今通学路に、ここにあるとおり通学安全確認の業務を委託してやっていただいている、主にシルバー人材センターの方もいらっしゃいますが、今回の大阪府北部地震でそうした見守っていただいている方も被害を受けたケースがありました。","respondent":"有馬庶務課長","answer":"そういった方たちについても、学校で今回把握した危険なブロック塀の場所など、情報共有できればしながら進めていきたいところです。","voiceIndex":225,"id":"exchange-102"},{"speaker":"たけうち委員","kind":"質問","question":"一般質問でも質問いたしましたが、本当に今年は夏から秋にかけて災害が頻発しており、また東日本大震災以降、熊本地震も含めてもう毎年のように大きな災害が起こっている中で、公明党としてもこの防災、減災をしっかり政治の柱に、また社会の主流に据えて取り組みを行っていくということを、先般の参議院の本会議の代表質問で我が党の山口那津男代表がお伝えさせていただいたとおり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-103"},{"speaker":"飯沼委員","kind":"質問","question":"同ページ、学事制度検討経費のところから、学校の選択制についてお伺いいたします。月の平均残業数は、１人が６２.６時間、平均ですから毎週４０時間の労働のほかに毎週１５時間ずつ残業、つまり毎週５５時間働き続けるといった内容になっていて、私もびっくりしました。よい仕事はやりたくてもできなくなるのではないでしょうか。質問ですが、なぜこのような状況になっているのか教えてください。","respondent":"熊谷指導課長","answer":"それに加えて病気休暇の対応、それから体罰等の服務事故が起こらないように、またそういったことが発生したときの聞き取り、そういったこともあります。ハラスメントの相談窓口にもなっております。","voiceIndex":229,"id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問","question":"一定改善はされているということでお聞きしましたけれども、でも２５％の削減では、まだまだ足りないと思います。指導課２４人に対して仕事量が多過ぎるのではないでしょうか。人員増がされているということなのですが、職場からは、どういった要求が出ていて何人増員をされたのか、その辺も教えてください。教員の長時間労働の原因はどこにあるのか、改善策を具体的に教えてください。","respondent":"熊谷指導課長","answer":"さらに働き方改革を進めまして、それがそれぞれ小学校で３分、中学校で２分、平均で減っているところです。","voiceIndex":231,"id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１日８時間労働ではやり切れない仕事量が先生たちの肩にのしかかっているのではないでしょうか。どんどん増えています。大もとのところを変えていかない限り、改善はされないのではないでしょうか。１日８時間ではおさまらない仕事量があるということは、共通の認識になっているのでしょうか。この認識を持っていただきたいのですけれども、その点はいかがでしょうか。","respondent":"熊谷指導課長","answer":"先ほどご質問がありました指導課の人員ですけれども、平成２９年度は１名増、そして平成３０年度も１名増となっております。","voiceIndex":233,"id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教員の増員が必要です。そしてもう１点は、学校で教職員と話し合いをして、不要不急の業務を削減していただきたい。このことを求めます。運動部活動の在り方に関する総合的なガイドラインにありますけれども、この中には休養日週２日以上、そして土日どちらかを休みにする、こう書かれていますが、ぜひこれを現実のものにしていただきたいのですけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"部活動のあり方につきましては、各学校のほうに通知をするとともに、平日においても休養日、そして土日においても必ずどちらか１日は休みを設ける。固有教員につきましては、さまざま今固有教員のあり方等についても検討していますので、今後の課題というふうになるかと思います。","voiceIndex":235,"id":"exchange-107"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ現場の教職員の方々と話し合いをして、業務の見直し、大もとのところは職員を増やしていかなければいけないという、教職員を増やしていかなければいけないところがありますけれども、ぜひ業務内容で見直しができるところ、ぜひ校長先生や副校長先生だけではなく、全職員の意見をしっかりと聞いて、見直しをしていただきたい。ここのところはいかがでしょうか。","respondent":"熊谷指導課長","answer":"そのために、やはり業務内容の見直しということは非常に重要ですので、教員がやらなくてもできる内容、例えば学校だよりの印刷、そして数えて配付する作業、それから電話対応、学校行事の式典の補助ですとか。","voiceIndex":238,"id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろ現状でできる部分や工夫がされているのは、お話を伺いました。しかし、現場で働いている教員、職員の方々の意見をとにかく聞いて、現場主義でやっていただきたいと思いますので、そこのところは重ねてお願いをいたします。共産党は問題点を指摘し、中止すべきと主張してきました。今回の学事制度審議会の答申を受けての学校選択制の見直しに絞って、内容を教えていただきたいと思います。","respondent":"若生学校制度担当課長","answer":"学校選択制に絞ってですが、まず今般、品川教育ルネサンス、こういったものを進めている中で、地域とともにある学校づくり、そういったことをこれまで以上に強力に進めていく、そういった観点から学校選択制、これはさまざまアンケート等も審議会の中でとってまいりまして。","voiceIndex":240,"id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"中身についてですけれども、小学校は近隣ということで、近隣校から選べるということですが、実際的には４校から９校も選べてしまうのです。１００件の意見中賛成は１１件で、８９％が選択制を肯定していないといった中身でした。そして反対、疑問が２２件、改善を求めるが１０件だったのです。再検討をお願いしたいと思いますが、いかがでしょうか。","respondent":"若生学校制度担当課長","answer":"アンケート等ですけれども、区民アンケート、それから町会長アンケートのほう等もとっておりまして、そういった中では廃止すべきというものは１割に満たない数字で出ておりますので、そういったところからも続けるべきと考えております。","voiceIndex":242,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"確認","question":"私は成果報告書の１８５ページ、学校ＩＣＴ化推進経費に関連して、それから１８９ページ、保幼小連携推進経費に関連して質問します。もちろん教材や、あるいは各教員の指導方法は千差万別で、さまざまあっていいのですけれども、せっかく学校にＩＣＴ機器が導入されたのだから、インカムを含めた教材を活用して、児童・生徒にわかりやすい授業展開すべきと思ったのですが、いかがでしょうか。","respondent":"篠田学務課長","answer":"そのうちの毎日利用していると答えた教員が５３％ということで、３年前ですので、まだ毎日利用しているのは半分でしたけれども、その後こちらで把握している限りでは、全ての教員、特に書画カメラ等、ものを写し取るカメラ等は非常に使いやすい。","voiceIndex":245,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"確認","question":"方向性の確認はこれで終わりますけれども、要は効果的に使ってくださいということをお願いしておきます。そのときに品川区から配付されたパソコンはどうされているのでしょうかということが１点。だからそれを、ほかの学校に転用するということは非常にプラスになると思うのだけれども、そのデータの引き継ぎ方法や対応をどのようにされているのかなと思ったので、答弁をお願いいたします。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"ただ、一部教育系のデータなどの部分です。要は個人情報のないものに関しては、学校長の許可を得て持ち出しすることが可能となっております。有効な教材、あるいはプリントなどにつきましては、各教科ごとの教科会として共有フォルダーを区で設けておりますので、その中に保存して各学校の。","voiceIndex":247,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"確認","question":"もう少し確認したいのだけれども、教材の学校ごとのアイデアはわかったのですが、要は個々の教員の指導方法がありますよね。３年、４年いるわけだから、それに基づいていろいろなデータが集約されるわけです。お願いいたします。","respondent":"篠田学務課長","answer":"確かに委員ご提案のとおり、それぞれの教員のノウハウを持ち出して新しい学校で使っていくことは確かに有効な手法の１つだとは考えます。","voiceIndex":250,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"確認","question":"デジタル時代ですから、新しい課題といえば課題なのだけれども、でもうまく活用していかないともったいないです。改めて文部科学省のホームページをいろいろ確認していたら、２０２０年度から全ての小学校においてプログラミング教育が必修化されます。その目的はＩＴ力の向上、現状ではヨーロッパでは労働市場の９０％が基礎的なＩＴスキルが必要だということの表現がありました。お願いいたします。","respondent":"篠田学務課長","answer":"しかしながら、いずれにしても今後ＩＣＴ環境がどんどん進んでいくことは間違いございませんので、そういったところ、バランスを考えながら導入をしていくという方向は間違いないと考えておりますので。","voiceIndex":252,"id":"exchange-114"},{"speaker":"伊藤委員","kind":"意見","question":"それは今のパソコンの１００分の１ぐらいの性能です。このためにはハードウエアがどうしても必要なわけだから、それはさまざまな方法を考えながら、国からの予算を引っ張ってくるなり、いろいろなことを展開していって、プログラミング教育の具体化、予算化、そしてそれを品川区にも反映させていく仕組みをさらに検討すべきだと思うのですが、改めてご答弁をお願いいたします。","respondent":"篠田学務課長","answer":"いずれにしましても、今後ＩＣＴ化の進展がとめられないことは間違いないという認識は持ってありますので、教育的な効果、それからコストの面、それから今ご指摘のあったような特定財源等、さまざまな部分を総合的に判断しながら。","voiceIndex":254,"id":"exchange-115"},{"speaker":"伊藤委員","kind":"確認","question":"品川区に影響は出ないのかという確認だけお願いいたします。","respondent":"佐藤保育課長","answer":"私立の関係に関しましても連携をして、しっかり進めていきたいと考えております。","voiceIndex":258,"id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"１９２ページの学校管理費から自転車ヘルメットについて伺います。平成３０年度については、この自転車ヘルメットが、どのようになっているか寄附等のご様子もお聞きしておきたいと思います。それから自転車にかかわった死亡事故も含めた事故の傾向性を確認させていただきたいと思います。それから続いて１９０ページの特別支援教育費についてもお聞きをしていきたいと思います。","respondent":"大関教育総合支援センター長","answer":"自転車ヘルメットの今年度の状況ですが、引き続きご協力を得ながら、これはもう校長会の取り組みとして、今年度の新入生たちにもヘルメットを配るということで、引き続き１年生から６年生全員に渡るという状況をまずは担保した上で、交通安全指導を各校が進めております。","voiceIndex":262,"id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"それから特別支援のほうは、数をお聞きしておきたいと思います。傾向性としては対象となる子どもに、年度の前半当初配置をされて、そして後半になると子どもの人数が増えるというざっくりとしたものがあるわけですけれども、これも介助員、学習支援員の対象となっている子どもたちの、学年別の児童・生徒数がわかれば確認をさせていただきたいと思います。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"先に特別支援学級の免許の所持率ですけれども、こちらにつきましては２３.３％、３０名です。それから特別支援教室のほうになりますと、これは小学校段階では今年度４１６名に対応しています。","voiceIndex":264,"id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１９６ページの学校給食費について伺いたいと思います。子育て支援や教育の充実という点からも、ぜひとも学校給食費の無償化を求めたいと思います。品川区が給食費無償化をする場合幾らかかるのか、トータルで幾らかかるのかを教えてください。それを就学援助金と多子家庭の補助金を差し引いて、新たに幾らかかるかということの金額についても教えてください。","respondent":"篠田学務課長","answer":"そうしますと、先ほど申し上げましたトータルの１１億円から、この２つの金額を差し引きますと、新たに必要となる経費が８億７,７００万円余となるものです。","voiceIndex":268,"id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"学校給食法では目的に「学校給食が児童及び生徒の心身の健全な発達に資するものであり、かつ、児童及び生徒の食に関する正しい理解と適切な判断力を養う上で重要な役割を果たすものであることにかんがみ、学校給食及び学校給食を活用した食に関する指導の実施に関し必要な事項を定め、もつて学校給食の普及充実及び学校における食育の推進を図ることを目的とする」と書かれておりまして。","respondent":"篠田学務課長","answer":"委員ご指摘のとおり、学校給食の目的といった部分に教育的な見地が含まれること自体は、そのとおりであるものというふうに認識しています。","voiceIndex":270,"id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"教育の一部だという見解だということだと思うのですけれども、そうであれば、憲法第２６条では国民の教育を受ける権利を保障し、さらに義務教育は無償とするということで書かれております。それであれば、私はこの給食費も無償化が求められると思うのですけれども、いかがでしょうか。","respondent":"篠田学務課長","answer":"それから無償化の捉え方ですけれども、基本的には今申し上げたとおり、法の規定に基づいた形でそれぞれ必要な部分、要は実際にお子さん方の口に入る部分に関してだけご負担をいただいているですので、そういった意味で実質上。","voiceIndex":272,"id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということで、実際に全く給食費がかからない、本当の無償化ということは可能だと思うのですけれども、その点についてはいかがでしょうか。それから実質無償化ということなのですけれども、文部科学省が今回調査をしたところでは、この食材費の無償化というふうなところでのとり方をしています。その点についてもお聞かせください。","respondent":"篠田学務課長","answer":"しかしながら、それは逆に言えば必ず設置者のほうで負担をすべきものであるということでもないですので、法の規定に現状はのっとった形で区としては対応しているものです。","voiceIndex":274,"id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一般的に給食費の無償化ということであれば、この食材費の無償化ということになると思うのです。というのも、食材費の自己負担というようなことでなっていますので、それを無償化するということが給食費の無償化というようなことになるわけです。今、８２自治体が無償化をしております。これが全国的な趨勢ですので、ぜひとも品川区でも無償化に取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":276,"id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"質問","question":"教職員の方々の人事について、２つ目に１８６ページ、学級集団アセスメント、１８７ページ、学力定着度調査経費、時間があれば１８９ページ、マイスクール運営費をお尋ねします。そもそもこういった方々の異動等はどのような仕組みで決まるのでしょうか。区の固有教員の方が１人いらっしゃるとはお聞きしております。","respondent":"熊谷指導課長","answer":"Ｂ選考、いわゆる副校長を目指して学校で主幹教諭をする選考なのですけれども、そちらの方も昨今では指導主事になるということもございまして、教育総合支援センターの統括指導主事がＢ選考合格者です。","voiceIndex":278,"id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話あったように、都のほうとの協議でということですが、教科をお聞きしたところ、中学校では理科と音楽の方、小学校は、これは専門の教科はないのでご自分の専攻という言い方になるのでしょうか。ただ、残念ながらというか、その中には英語の専攻の方が１人もいらっしゃらないということなのです。","respondent":"熊谷指導課長","answer":"ですので、少なくとも平成２７年度、平成２８年度は英語科の専門の指導主事がおりませんでしたので、区の固有教員を指導主事として配置していた経緯があります。","voiceIndex":280,"id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこで、先ほどお話ありましたけれども、異動の要請のときに品川区のほうが、ぜひ少ないながらもこういった教育をしているので、このような指導主事の方に来てほしいという要望を、具体的にどのような形で出していらっしゃるのでしょうか。","respondent":"熊谷指導課長","answer":"そういったところで、まず本区の力のある固有教員を英語科の指導主事として配置したところですけれども、私は国語科ですが、地教委の指導主事はさまざまな教科を勉強しながら指導、助言はできるようにしていくというところもありますので、今の状況ですと。","voiceIndex":282,"id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"一生懸命やられていることは十分承知しておりまして、それぞれの科目を持ちながらも英語教育のほうでいろいろなリーダーシップを発揮していただいていると思うのですが、英語科の先生方のいろいろな研究会や、こういったことを進めていく中では、どうしてもそういった能力をお持ちの方が必要になると思いますので、今お話あったように。","respondent":"熊谷指導課長","answer":"ですので、例えば朝食を毎日食べていると回答した子どもたちが非常に学力的には高かったですとか、それからお祭りやボランティア活動など地域の行事に参加している、こうした子どもたち、いわゆる正答率の分布を２５％ずつ分けたときに。","voiceIndex":284,"id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひこういったクロス集計を活用して、ほぼ全学年でされているので、学校の指導に役立てていただきたいと思います。そして３つ目、ちょっと時間がないのですが、マイスクールのほうは文部科学省から平成２９年度の、いわゆる不登校関係の調査結果が、つい先月出されました。この全国的な傾向と、品川区における数的な面と、不登校の要因についてお聞きします。","respondent":"大関教育総合支援センター長","answer":"そのようなお子さんになると結果的に学力不振ということも重なってきておりますので、本区では学力の対応という部分もマイスクールのところで重要視するように、今、改善の見直しをしています。","voiceIndex":286,"id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"不登校に関しては、また機会を改めてお伺いしたいと思います。今後の対応にもこういった調査を活かして、指導のほうをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":288,"id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は１８６ページ、クラブ・部活動指導費関係についてお伺いします。スポーツだけでもいいのですけれども、いろいろ顧問の先生、スポーツ経験がない方や、例えばそのスポーツに対する経験がない方、このような方もたくさんいらっしゃると思っていまして、この辺のところの現状というのですか、そのようなところはどうお考えになっているのかお聞かせください。","respondent":"大関教育総合支援センター長","answer":"それでも部活動の顧問をやってもいい、あるいはやりたいという教員もおりますので、そういった教員に部活動の顧問は任せているという状況がありますが、そこを補うために、ぜひスポーツの競技内容に詳しい方。","voiceIndex":290,"id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問","question":"これを今、いろいろな野球連盟でも、必ずチームに１人ぐらい指導者は取ってくださいと。そのような意味でいうと、やはり学校の部分で、意欲があって、先生が「私顧問になって頑張ります」ということはいいのだけれども、やはり部活動という形でやるのなら、それぐらいまで、これはもう全国一律ですから、コーチングの資格をとれというと２００時間ぐらいやらなくてはいけないのです。","respondent":"大関教育総合支援センター長","answer":"地域の資格をお持ちの方などに、例えば講習会の場で講師としてご指導いただくような機会も今後検討すべきかとも思いますし、あるいは部活動指導員という形で、一気に１５校全部とはいきませんが、どのような形で今後充実していけるかも含めまして。","voiceIndex":292,"id":"exchange-131"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、児童のときからそのような地域のスポーツクラブに入っている、それから部活につながっていく、そのようなことを考えるのであれば、できる、できないはありますが、ぜひ年に１回なり２回なり、地域スポーツクラブの指導者も含めた研修のようなもの、それは子どもたちにも体験をさせてあげる、そのような集まりにもっと支援をしてあげるべきだと思うのだけれども。","respondent":"池田スポーツ推進課長","answer":"そのほかに品川独自で指導者を育成するということが重要なことだとは思っております。これにつきましては、今すぐどうということではございませんけれども、ぜひ検討させていただきたいと思います。","voiceIndex":294,"id":"exchange-132"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それからもう１点、１９７ページの学校改築推進経費に関連して校舎改築計画で、先ほどお話がありました。これはちょっとお考えをいただきたいと思うけれども、やはりそうするとどんどん中学は後にしていくというような話になってしまうから、そうもいかないのでやらざるを得ないのでしょうが、その小・中学校がずっと改築中という子どもに対する配慮はどうお考えかというところもお聞かせ願いたいと思います。","respondent":"有馬庶務課長","answer":"学校改築の件ですけれども、毎年１校ずつのペースということで進めているということではあります。ただ、今１校つくるのには６年から７年近くかかってしまいます。","voiceIndex":296,"id":"exchange-133"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそれはお願いだけしておきます。ペースを上げてほしいなと思いますし、小・中学校がずっと改築中という子どもに対する配慮も、やはりお願いしたいと思います。最後に、１９８ページの幼稚園費関連の話をしたいと思います。今そういう新人は多分多いのだろうなと思いますけれども、その辺の点がおわかりになったら、ぜひ教えていただきたいと思います。","respondent":"佐藤保育課長","answer":"保育園、幼稚園の資格の関係ですけれども、保育園に勤めている保育士に関しましては約５割ぐらい、４４％ぐらいの方が両方持っていると把握しております。新人の方に関しましては、委員ご指摘のとおり８割、９割ぐらいは持っているところだと認識しております。","voiceIndex":298,"id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはちょっと、このような言い方がいいのかどうかわからないのだけれども、地域の二、三人の方から言われたので言いますが、今、地域行事に非常に参加をしていただいているではないですか。小学校の校長先生、副校長先生、地域センターの所長から幼稚園の園長、保育園の園長、皆さん本当に地域に参加していただいて、本当にありがたいと思っています。","respondent":"佐藤保育課長","answer":"現在、幼保一体施設がございまして、委員ご指摘のとおり、幼稚園長は管理職ということで、保育園長は係長というところで、一定のそういった関係ができるところではありますけれども、保育課も交えて施設長会等を頻繁に開いておりますので。","voiceIndex":300,"id":"exchange-135"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、成年年齢の引き下げによる教育について、紫外線対策、日焼けどめについて、それと１８６ページ、いじめ防止対策費について、同じく１８６ページの教育指導費になるのかなと思いますが、性教育についてお伺いをいたします。これは、２０２２年からではもう遅いのかなと。もう今から始めなければいけないと思うのですが、その点どのように考えているか教えてください。","respondent":"大関教育総合支援センター長","answer":"基本的には積極的に日焼けどめクリームは可という形は、区としてもまだ学校に対してはお話ししておりません。ただ、これまで個別の対応で、どうしても配慮が必要なケースというものは他区で実例がございましたので、それはもう個別の対応が必要かと思います。","voiceIndex":303,"id":"exchange-136"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えば体を触られたということが１０代で１.９％に対し、５０代だと０.４７％、下着の色が決められていたというものが３０代では１.９％に対し、１０代では１５.８４％、下着の色をチェックされた人は５０代でゼロ％に対して、１０代では２.５３％、このように差が出ている中で、いろいろ今社会で、例えば大学や企業だとハラスメントの専用窓口のようなものが設置されていたりしていますけれども。","respondent":"大関教育総合支援センター長","answer":"あるいは教育総合支援センターの教育相談室のほうに相談があった場合には、とてもナーバスでデリケートな内容ですので、そこはやはり見逃さず、丁寧に対応していきたいと考えております。","voiceIndex":305,"id":"exchange-137"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なので、しっかりとその辺の対応を今後とっていただきたいと思います。性教育についてですが、東京都教育委員会から足立区教育委員会に指導が入って、性教育をどうしていくのかという議論が今、インターネット上でも大きく話題になっています。そのような中で、まず品川区としてこの性教育についてどのような教育をされているのか教えてください。","respondent":"大関教育総合支援センター長","answer":"７年生であれば、さらに思春期の生殖機能が成熟していって、それに伴う適切な行動の必要性という部分まで学んだ上で、９年生になりますとさらに具体的に性感染症、エイズ、あるいは梅毒ですとか、そういったものも教科書にも載ってきておりますので、扱っております。","voiceIndex":307,"id":"exchange-138"},{"speaker":"石田（し）委員","kind":"意見","question":"そういった意味でも、やはりこの性教育というものはしっかりやっていかなければいけないし、例えば全国の公立高校で２０１５年度と２０１６年度で約３,０００人が妊娠をして、そのうちの６７４人が退学をしたと。１５歳以下だと１８９人が出産して８３９件の人工妊娠中絶があり、その選択率というものは８２％になっている現実がある。","respondent":"大関教育総合支援センター長","answer":"「性教育の手引」の改訂を待たざるを得ないのが公教育の現状という部分はありますが、委員からご指摘いただいたように、市民科の中で本区の場合には、例えば男女平等だけでなく、異性の尊重をどのように考えていくのか、さまざまな人との接し方。","voiceIndex":309,"id":"exchange-139"},{"speaker":"南委員","kind":"質問・要望","question":"１８６ページ、教育指導費に関連して不登校問題を取り上げたいと思います。２６年も前の１９９２年、当時の文部省が出した通知には、登校拒否は誰にでも起こり得る。そこで伺いますが、不登校の関係で区の認識を改めて伺いたいし、現在の品川区の小学校・中学校での不登校の実態、具体的な数字を教えていただきたいということ、２０００年から５年置きに教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"先ほどご指摘いただいた学業の不振というものは、結果的に学業不振があるお子さんですと、さらに無気力傾向があったりなどという部分は、クロス集計の中からも分析しておりますので、そういった内容について本区として引き続き対応を充実させてまいりたいと考えています。","voiceIndex":312,"id":"exchange-140"},{"speaker":"南委員","kind":"質問","question":"教育委員会は、対策としてこの間スクールカウンセラーの配置やマイスクールの開設などをしてきました。あるいは対策をとっていても、その対策が不十分ではないか、このように思いますけれども、この点についてどうなのかと。今日はどうなのかということもあわせて伺いたいと思います。そしてこういった対策に対して教育委員会の評価、どのように認識をしているのかも伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"その適応指導教室での、実際の具体的な内容につきましては、先ほど申し上げましたように、本区教育委員会が行う事業としてはまず学校復帰を前提としたものとして考えているところには変化はございません。","voiceIndex":314,"id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"例えば平成２９年度は、小学校が５５人、中学校が１５５人、合わせて２１０人なのです。したがって、数字が、母数は違うといっても数字そのものは微増、増えているわけですから、ここはしっかりと見て必要な対策をきちんととっていただきたいということは強くお願いをしておきたいと思いますが、なくならない原因はどこにあるのかということを伺います。そのような点についてぜひ伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"そのような中でスクールソーシャルワーカーやカウンセラーが子どもたちの気持ちも酌み取りながら、どういった形の支援ができるか、一つひとつ丁寧に対応していることが。","voiceIndex":316,"id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"そのような点について質問したつもりなのです。やはりそのような点でいうと、もっともっと子どもの声をしっかりとつかんで、適切な指導をするべきだと思うのです。そのことによって不登校もどんどん減っていくのではないかと思いますけれども、そのような考え方をぜひとっていただきたいと思いますが、いかがでしょうか、最後に伺います。","respondent":"大関教育総合支援センター長","answer":"子どもたちが学校生活の中で自分の居場所、役割を感じるということは、とても重要なことだと教育委員会も認識しておりますので、今後とも子どもたちの学校生活が実りある豊かなものとなるように、学校を支援してまいりたいと思います。","voiceIndex":318,"id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"一人ひとりの子どもが、その友達と仲よく遊びたい、学校が楽しく行けるような、そのようなところになってほしいという願いは本当に大事にしていただきたいということを強調して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-144"},{"speaker":"こんの委員","kind":"質問","question":"私からは、１８８ページ、日本の伝統・文化発信能力育成事業、１９０ページ、図書館経費、１９３ページ、学校環境整備事業からお伺いしたいと思います。ページ順不同でお聞きいたします。１９０ページの図書館経費ですけれども、本のクリーニングについてお聞きしたいと思います。そこで貸し出しされた本は、返却された際、本の状態がどのような状況がありますでしょうか。","respondent":"横山品川図書館長","answer":"それについては全体で２,０７４件ございまして、その中で免除をしたものが１,３３８件、ご本人にご負担いただいたものが７３６件ございました。","voiceIndex":322,"id":"exchange-145"},{"speaker":"こんの委員","kind":"意見","question":"ものすごく多い数なのだなと思って、そもそも劣化していくのと同時に本がいろいろな方が使われることによって、誤って濡らしてしまったり、汚してしまったりということがある中で、これだけの件数の自己負担、いわゆる自己責任をとっていただいたのが７３６件あったということで、かなり多いのだなという印象を受けました。こうした取り組みは大変に評価をしたいところだと思います。","respondent":"横山品川図書館長","answer":"消毒機の導入の経緯ですが、こちらは平成２７年度に指定管理制度を導入した際に、指定管理事業者からのご提案に基づきまして導入したものです。五反田図書館、荏原図書館、大崎図書館に１台ずつと、品川図書館では購入して１台あります。","voiceIndex":324,"id":"exchange-146"},{"speaker":"こんの委員","kind":"提案","question":"４館でそのような導入をされている、そしてその導入の経緯は指定管理者のご提案によるものということですが、指定管理者のご好意、いわゆるサービスでそれを設置してくれているという認識でいいのでしょうか。その指定管理者と区が契約をするときの契約書にそのようなことも設けられて設置がされているのか、その辺をお聞かせください。","respondent":"横山品川図書館長","answer":"ご好意といいますか、指定管理料の中の一部の使い方として、そちらのご提案をいただいている形ですので、そのような意味では経費は区が負担しています。","voiceIndex":326,"id":"exchange-147"},{"speaker":"こんの委員","kind":"提案","question":"その経費の中で指定管理者が提案をして、導入をしてくださっているということですね。わかりました。そうすると、ほか残り６館のところでは、その指定管理料は、そうした図書の消毒機に使われる、そのようなことにはならないのでしょうか。","respondent":"横山品川図書館長","answer":"ですから、そこは工夫をしないといけないということで、今のところは指定管理館では３館、そして品川図書館に１館という状況になってあります。","voiceIndex":328,"id":"exchange-148"},{"speaker":"こんの委員","kind":"質問・要望","question":"それで、これは指定管理者との契約の中でということなのですが、私が１つ考えたのは、スペースの問題があるのですけれども、区として設置をしていく、いわゆる指定管理者は結局指定管理の契約が終わってしまうと、その備品、そのものは指定管理者が引き上げてしまうのかなと思っていたので、そうだとすると、区できちんと設置をしていただくには、その設置する費用を。","respondent":"横山品川図書館長","answer":"今後につきましては、技術革新に伴っていろいろ新しいものを積極的に取り入れたいと思いますので、コンパクト化が進めば、ほかの館でも導入していきたいと考えております。","voiceIndex":330,"id":"exchange-149"},{"speaker":"こんの委員","kind":"質問","question":"次に参ります。次は学校環境整備事業についてです。こちらは小学校、中学校のプールの設備についてお伺いします。先ほど石田しんご委員からも、紫外線のことについてお話がありましたが、私もその紫外線に絡んで学校のプールの設備というところでお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"学校のプールのひさしについてですけれども、プールは校舎の一体型になっているところと平場になっているところといろいろありますが、現在のところほとんどのプールはそういったひさしというものはついていないというところがほとんどだというふうに認識しております。","voiceIndex":332,"id":"exchange-150"},{"speaker":"こんの委員","kind":"質問","question":"ほとんどのところがついていないという現状はわかりました。この真夏のプールの授業ですね。ですから、こうしたことから考えると、日よけ、ひさし、こうしたものをプールサイドに設置していくということが必要と考えられますが、いかがお考えでしょうか。","respondent":"有馬庶務課長","answer":"場合によっては日陰を探して少し休むとか、そうした工夫はしているとは思いますけれども、今、改築校には日よけをつけているということもありますので、そういった対策も必要ではないかというふうに考えているところです。","voiceIndex":334,"id":"exchange-151"},{"speaker":"こんの委員","kind":"質問・要望","question":"特にプールに入れるお子さんと見学をされるお子さん、特に見学のお子さんの場合は日陰にというように、最初からそういう対策がとられると思いますが、それでもやはりプールサイドで一緒に見られる、見て授業も受けられる、そうしたことがよろしいかなと思うと、プールサイドへの日よけ、ひさしは必然かなと思いますので、どうか今後の検討をしていただきたい、このように思います。次に参ります。","respondent":"大関教育総合支援センター長","answer":"具体的にはその学校ごとに内容は異なりますが、ＪＥＴ青年というように東京都では呼んでいるのですけれども、都立高校に来ているアメリカ人などがさらに区立学校に定期的に来てくれて、そういった方たちと一緒に日本の文化を学んで。","voiceIndex":336,"id":"exchange-152"},{"speaker":"こんの委員","kind":"質問","question":"日本の伝統・文化を子どもたちがその海外の青年たちに伝えていく、大事な取り組みだと思います。どのようにされているのか。私は毎年、土日に開催されている伝統の技と味／しながわ展、専門家が一堂に会する催し物ですので、そうしたことを見学するということも非常に学ぶ機会であると考えますけれども、こうした学ぶ機会の創出はどのようにされていますでしょうか。","respondent":"大関教育総合支援センター長","answer":"平成２９年度は８校が実施いたしまして、浮世絵ずり、江戸すだれ、江戸切子、草木染手織物、東京桐箪笥、あるいは和竿など、区内のたくみの方のわざを実際に学ぶような機会を設けました。","voiceIndex":338,"id":"exchange-153"},{"speaker":"こんの委員","kind":"意見","question":"専門家の方々によるそうした授業、大事だと思います。それはやはり限られた学校、限られた専門家の方の授業でしかないので、そうした方が一堂に会する、この伝統の技と味／しながわ展、こうしたものも活用するとよろしいかなと考えますが、ご検討ください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":340,"id":"exchange-154"},{"speaker":"渡部委員","kind":"質問","question":"現在２４名で、ホームページで今年４名の方が合格をされて、もともと６名採用というようなお話は伺っていたのですが、実際平成３１年４月、どのような体制になるのでしょうかということをお伺いしたいです。","respondent":"熊谷指導課長","answer":"東京学芸大学附属竹早中学校は本区と学芸大学との連携事業で、本区の家庭的に就学が困難な子どもたちに対して、今年は４名の子どもたちが品川区から竹早中学校に入学しておりますので、その子どもたちとの連携ということで、竹早中学校に今年度配置したところです。","voiceIndex":342,"id":"exchange-155"},{"speaker":"渡部委員","kind":"質問・要望","question":"状況を確認させていただきました。私たちは会派としてさまざまな教育活動を、コミュニティ・スクールなどもやっていて、地域と連携を図る中で、品川区の固有教員を各校に１人置いてほしいという要望を出し続けています。後ほど学校給食の話をしますけれども、先ほどの金額を使えるのであれば、このようなところにしっかり使ってほしいと思うのですが、今後の区の固有教員の見通しをお聞かせください。","respondent":"熊谷指導課長","answer":"そういった中で、本来ですと来年度１５中学校区に３０名が達成できるところだったのですが、あともう少しといったところですので、また今後、まずは３０人の配置ということを目指していきたいと考えているところです。","voiceIndex":344,"id":"exchange-156"},{"speaker":"渡部委員","kind":"質問・要望","question":"承知いたしました。ですから、それこそＡＩ先生ではないですけれども、いわゆるホームページ等を活用して、例えば幼稚園の子どもがいて小学校に上がるというときに、住所を入れるとあなたの指定校はどこです、あなたはどこどこが選べますというような形、一目瞭然になるようなシステムを早急に構築して、それを紹介していったほうが早いと思うのですが、そこだけ考え方をお伺いします。","respondent":"若生学校制度担当課長","answer":"確かに経過措置も含めますと複雑な制度になってまいりますので、ご提案いただいた件も参考にさせていただきながら、保護者の皆様等にわかりやすく、また学校等にも負担をかけないような形で、あらゆることを視野に入れて検討してまいる所存です。","voiceIndex":348,"id":"exchange-157"},{"speaker":"渡部委員","kind":"質問・要望","question":"それはみんな家庭で食費は負担して、私たちも子どもを食べさせているときもそうでしたけれども、やっているわけですから、この給食費をただ無料にしろということは暴論だと私は思っています。そのような中で、品川区は平成２０年、食材費の急な高騰などで、たしか年度途中だったと思うのですが、今の２４０円、２６０円、２８０円、３２０円でしょうか、そのようなカテゴリーにて給食費が設定をされました。","respondent":"篠田学務課長","answer":"こういった中で消費税増税となったときに、どういった対応をしていくかということは、動向を見きわめながらきちんと考えていく必要があるものと考えます。","voiceIndex":350,"id":"exchange-158"},{"speaker":"渡部委員","kind":"質問","question":"実際これが適正なのかどうなのかということは、そのときになってみなければわからないのだけれども、今ちょうど課長からもご指摘がございましたように、食材は、やはり天変地異や災害などによって高騰することがありますよね。その辺は今すぐにそれはできる、できないという話ではないと思うのですけれども、検討を少し始めてほしいと思うのですが、いかがでしょうか。","respondent":"篠田学務課長","answer":"子どもたちに安心・安全な給食を提供するために行政としてできることということで、今後ともそういった部分について、きちんと研究してまいりたいと考えているところです。","voiceIndex":352,"id":"exchange-159"},{"speaker":"渡部委員","kind":"質問・要望","question":"最後になります。品川コミュニティ・スクールが全校で始まりました。この事業は、これから先ずっと品川区の中で、この仕組みで行われていくことと思いますが、全校で始まってみて、何か問題点等は生じていますでしょうか。この先、この制度を維持するために何か必要なものがあるとすれば、これからの品川教育ルネサンスの大事な１つですので、お聞かせください。","respondent":"熊谷指導課長","answer":"コミュニティ・スクールフェスタを開催いたします。そこでしながわＣＳＲ推進協議会の会員にも協力していただいて、地域の方々に発信していこうと考えているところです。","voiceIndex":354,"id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":116274,"voices":356}},{"id":"h30-20181116-4","meetingId":"h30-c-settlement","date":"2018年11月16日","dateIso":"2018-11-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時０４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"品川区議会自民党・子ども未来を代表しまして、石田秀男委員とともに総括質疑を行わせていただきます。初めに、ＩＣＴの活用についてお伺いしたいと思います。そこでお聞きいたします。区のアプリケーション配信状況についてお知らせください。","respondent":"中山企画部長","answer":"しながわ巡り」、それから、子育て関係の「しながわパパママ応援アプリ」、予防接種のナビなども含めたアプリケーション、こういったものを配信し、区民サービスの向上、情報伝達に努めているものです。","voiceIndex":2,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そこで次の質問に移ります。渋谷区では、平成２９年２月１５日から、ＬＩＮＥによる情報配信を開始しており、渋谷区ＬＩＮＥ公式アカウントでは、子育てに関するさまざまな情報を、お住まいの地域、あるいはお子様の年齢に合わせてお届けしております。子育てに関するお問い合わせには、ＡＩ、人工知能が２４時間受け付け、個別に回答しています。回答データは約３００件作成されているそうです。","respondent":"中山企画部長","answer":"メリットですけれども、まず、ご質問にもありましたとおり、２４時間３６５日、区民からの問い合わせに対応できるという区民サービス向上の部分、それから、これもご質問ありましたように、若い人を中心に。","voiceIndex":4,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"やはりこのデータベースの向上というのは非常にこれから課題だと考えています。職員の皆さんのスキルの向上ということで、これも推し進めていただきたいと思います。同じくＡＩ、チャットボットの導入についてお伺いします。これは１カ月で１,３５０人から９,８００件の質問があるそうです。そこでお聞きいたします。ＡＩチャットボット導入に向けた今後の区の見解についてお知らせいただきたいと思います。","respondent":"中山企画部長","answer":"今後、まさに品川区の中でどういうものが有効であるか、区民サービスの向上につながり、また効率化にもつながるか、こういう観点で導入の方法、対象業務について積極的に検討を進めてまいりたいと考えているところです。","voiceIndex":6,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひ検討をよろしくお願いいたします。次の質問に移らせていただきます。次は、禁煙対策について質問します。平成３０年７月４日に東京都受動喫煙防止条例が、同年７月２５日、健康増進法の一部を改正する法律が公布されました。たばこ税は、自治体にとっても貴重な財源です。区として、たばこを吸える場所の整備を今後どういうふうにされていくのかという観点から質問します。","respondent":"福内健康推進部長","answer":"これに伴いまして、区では新たに飲食店等からの届出の受理、企業の管理者からの喫煙室設置に関する相談対応、普及啓発等に関する事務などを開始するほか、２０２０年４月からは、法および条例違反者に対する行政処分等も行う予定です。","voiceIndex":8,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"主に屋内の規制が強化されるという認識をさせていただきました。次に、実際に区役所の庁舎内の喫煙所がどうなるのか、今後どのように整備していくのかをお聞きします。","respondent":"榎本総務部長","answer":"今回、先ほど説明があった法と条例の施行を受けまして、総合庁舎内につきましては、来年４月１日より全面禁煙としたいと考えています。そういう予定で動きたいと思っています。それに伴いまして、来庁者用の喫煙所を建物の外に２カ所ほど設置する予定でおります。","voiceIndex":10,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"行政機関の施設においては、室内に喫煙場所の設置ができなくなるのは大変残念ですけれども、区役所に関しましては、屋外に喫煙場所を整備していただけるようご答弁をいただき、少し安心したところです。次に、まち中にある指定喫煙所についてお聞きいたします。今後、屋外の喫煙場所を増やしていただければ大変ありがたいと思います。区としてどういう考えで指定喫煙所の整備をしていくかお聞かせください。","respondent":"堀越地域振興部長","answer":"屋外の喫煙所ですが、委員ご指摘のとおり、適地等の課題がございまして、新たな場所に設置することは大変困難な状況です。しかしながら、今後、都条例施行後の状況を見ながら、できるだけ可能性について検討していきたいと考えております。","voiceIndex":12,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"規制と喫煙場所の整備は表裏一体だと考えています。要望いたしまして、次の質問にいきたいと思います。次は、避難行動要支援者の体制づくりについてお聞きします。そこでお聞きいたします。取組内容の説明会、あるいは各町会・自治会に行くなどして、多くの避難行動要支援者の方が避難できるよう、全ての町会・自治会で具体的な対応がなされていることの確認が必要なのではないかと考えています。","respondent":"曽田災害対策担当部長","answer":"区といたしましては、引き継ぎ、現在の支援事業を継続的に促すとともに、ご指摘のように作成した手引きを使いまして、防災区民組織への丁寧な説明あるいは避難誘導ワークショップの実施などを通じまして、個別計画の作成が進むよう努めてまいりたいと考えているところであります。","voiceIndex":14,"id":"exchange-007","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"在宅の要配慮者には、どういうふうに支援をするのか、具体的に、現在の取り組みはわかっておりますけれども、これからどのように支援をしていくのかお知らせしていただきたいと思います。この自助についての部分で、広報活動、周知活動、今現在も取り組んでおられると思いますけれども、より一層深めていただきたいというところで、今後の展開を教えていただきたいと思います。","respondent":"曽田災害対策担当部長","answer":"しかしながら、現実的には、二次避難所や福祉避難所の収容可能人員、あるいは職員体制、このような制約から、全ての要配慮者をそのようなところに収容することは困難であり、多くの要配慮者はまず区民避難所へ避難せざるを得ないと考えておりまして。","voiceIndex":16,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、スポル品川大井町と区の連携と、ホスピタリティハウスについてお伺いします。スポル品川大井町が本年８月にオープンいたしました。区内にこのようなすばらしい施設が暫定とはいえ設置されたことを喜ばしく思うと同時に、区と連携して東京２０２０大会に向けた機運醸成のためのイベント、そして教室等ができないものか、その可能性についてお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"大井町の新たなスポーツを通した賑わいづくりに非常に貢献されているのではないかと考えております。今後、東京２０２０大会に向けて、機運醸成など、何ができるかＪＲと協議してまいりたいと考えています。","voiceIndex":18,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私も先日、プロサーファーと２０人ほどでサーフィンをスポル品川大井町で体験してきました。その中には、遠方から来ている方々もいて、大井町の賑わい、盛り上がっている、すごいねという言葉もいただいたところで、今の質問をさせていただきました。続いて、ホスピタリティハウスについてお伺いします。ホスピタリティハウスの有意性の現状と今後の見込みについてお知らせください。","respondent":"安藤文化スポーツ振興部長","answer":"現在、誘致国が決定した場合には、敷地の一部を利用いたしましてホスピタリティハウスを開設していきたいと考えています。まだ現在のところは誘致国は決まってございませんけれども、いろいろな方法を通じまして積極的に誘致活動をしてまいりたいと考えています。","voiceIndex":20,"id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ積極的に、あと１年半というところで、これから先が大変重要だと考えていますので、よろしくお願いいたします。次の質問に移らせていただきます。リオデジャネイロ視察報告書によれば、ホスピタリティハウスは、国、地域、企業などさまざまなところが主体として設置し、内容も多彩であると記載されております。本区では、設置した場合、どのような内容になるのかお知らせいただきたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"複数国のものもあろうかと考えています。今後、設置国のＰＲだけではなく、品川区のＰＲも一緒にできたり、また品川との交流都市とも一緒にそこでＰＲできて、区民の皆さんだけに限らず来訪者の方が繰り返し訪れて楽しいようなホスピタリティの内容ということで考えてあります。","voiceIndex":22,"id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。ぜひ品川区のＰＲ、当然、文化プログラムの会社等、ぜひ区民が何度も遊びに行けるような、いつでも楽しめるようなコンテンツを考えていただきたいと思います。以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"高橋伸明委員に引き続きまして、質問をします。私は、都市型観光の中の、まず水辺を活用した賑わいの創出についてお伺いしていきたいと考えています。この件につきましては、我が会派、私も含めてでありますが、２０年来、地域のイベント等の中で関係者の方々とともに行動をし、意見交換も行い、区に対してさまざまな要望を提出してきました。このことについてもお考えをお聞かせいただきたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"今回も区をはじめ実行委員会、公園事務所、それからしながわ観光協会のほうにも１件もクレームは入ってございません。そういうことから、地域の皆さんによる実行委員会の方々の主体的な取り組みによって、観光地域づくりにつながるものができたというふうに考えてあります。","voiceIndex":26,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"意見","question":"そのような中で、このイベント、これだけではなくて、今、春夏秋冬さまざま水辺でイベントが行われるようになってきました。２０２０年にはオリンピック・パラリンピックが開催されます。そう考えると、やっぱり五反田から天王洲エリアが中心になってくるのかと考えていますが、その点についてのお考えもお聞かせください。","respondent":"安藤文化スポーツ振興部長","answer":"その中に水辺の部会もあります。そこでは現状や課題、それから今後の取り組み、プロジェクトについても活発に議論をされているところです。委員ご提案の品川の賑わいの創出については、その専門部会の水辺の部会の皆さんに図って検討していきたいと考えています。","voiceIndex":28,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう意味では、水辺部会中心でも結構です。協議会中心でも結構です。それから、例えば現在は、さまざまな許可がイベントならオーケーだけれども、それが１年とかそういうスパンになってくると、どうしても港湾局だとか国土交通省などから全力でイベントの延長みたいな形で許可をいただいてこないとできない。気合いの問題みたいな話もあるけれども、ここら辺のご見解をお聞かせいただきたい。","respondent":"藤田防災まちづくり部長","answer":"これに加えまして、区といたしましては、橋のライトアップ等についても、これまでの実験から本格実施に向けて準備を進めているところです。水辺の千本桜も含めまして、天王洲や目黒川と中心とした品川区の水辺の魅力をさらに一歩進める計画が進んでいるところです。","voiceIndex":30,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"次にもう１つ質問をしたいのは、都市型観光の中の観光の視点から考えるべきではあると考えていますが、大森貝塚遺跡庭園と品川歴史館について伺っていきたいと考えています。これついての見解をお聞かせいただきたいのと、近接する品川歴史館と連携をして、展示や体験コーナー、ＶＲ映像などを活用して、観光資源としていく。これはやれることだと考えていますので、ご見解をお聞かせください。","respondent":"安藤文化スポーツ振興部長","answer":"それとまた、委員ご指摘のＶＲということが出ましたけれども、バーチャルリアリティーを活用したＣＧによる縄文時代を再現できるような事業も、今後、展開できるような形で検討していきたいと考えています。","voiceIndex":32,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"答えは大体このような感じです。変な話、我々が子どものときに授業で教えてもらったのは、みんな縄文時代とか縄文土器です。これはぜひ、そこら辺を生かすという考え方をもう１回お聞きしたいのと、それから、あとは、オリンピック・パラリンピックがあるのだけれども、大森貝塚の遺跡庭園に、例えば、これぐらいはできるだろうけれども、電車から見えるように大きい横断幕を張ってもいいではないですか。","respondent":"安藤文化スポーツ振興部長","answer":"その中で委員ご指摘の庭園にプレハブを建てて展示ができるようなスペースだとか、また横断幕などはすぐできるとは思いますけれども、そういうものについては、防災まちづくり部公園課と協議をしながら、できるところから早速進めていきたいと考えています。","voiceIndex":34,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"時間がなくなってしまったのですが、最後に１点だけ触れさせてください。北品川駅の立体化についてお伺いします。そのときに、その方は反対と言っているわけでありますが、地域ではそのようなことはなくて、北品川駅、そこについて、要望書も１月４日付で出しました。そこら辺のところだけしっかり答弁していただかないと、違った方向へ行きますので、もう１回お願いします。","respondent":"中村都市環境部長","answer":"この計画、立体化とあわせて行うことにより、踏切の解消など、駅の周辺に３カ所踏切がございまして、そのようなところの解消に伴って、歩行者の安全の確保もされます。地域からの要望も非常に強いというところで、しっかりと区として進めてまいりたいと考えております。","voiceIndex":36,"id":"exchange-018"},{"speaker":"新妻委員","kind":"提案","question":"区民の命を守るための防災対策の推進を求め質問します。これまで公明党は、防災対策の強化を求め、一般質問等でさまざまな提案をしてきました。そこで、款別審査でもお伺いいたしましたが、改めて、５２カ所ある学校避難所のうち何カ所にアドバイザーが派遣されたのか伺います。順次、各町会・自治会ごとにマニュアルの公開を要望しますが、見解を伺います。","respondent":"曽田災害対策担当部長","answer":"避難所運営に関する基本的な考え方を盛り込んだ標準的な避難所運営マニュアルを準備いたしまして、ホームページに掲載することを検討しているところであります。","voiceIndex":39,"id":"exchange-019","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"提案","question":"在宅避難について伺います。これから改訂される「わが家の防災ハンドブック」でも、在宅避難の勧めを入れるよう提案いたしますが見解を伺います。１１月１９日は備蓄の日です。例えば、毎年１１月１９日にはしながわ防災体験館でのイベントの開催や展示などを行い、備蓄を通して在宅避難を広く区民へアピールすることや、東京都と連携した取り組みを要望いたしますが、いかがでしょうか。","respondent":"曽田災害対策担当部長","answer":"今年度、都は、特にイベント等は実施しませんが、区においては、引き続き、しながわ防災体験館や防災学校、防災フェア、あるいは防災ハンドブック、さまざまな機会を捉えまして、備蓄の重要性、あるいは在宅避難の重要性を啓発してまいりたいと考えております。","voiceIndex":41,"id":"exchange-020"},{"speaker":"新妻委員","kind":"提案","question":"ぜひよろしくお願いいたします。次に、トイレについてです。款別審査でもたけうち委員が質問いたしましたが、改めて、災害時に避難所や公園のトイレが使用できるのか、このチェックの必要性と家庭内トイレの使用についての意識啓発のお考えを伺います。そこで、トイレトレーラーもトイレ対策の１つとして視野に入れてはと提案いたしますが、見解を伺います。","respondent":"曽田災害対策担当部長","answer":"ご提案のトイレトレーラーもこれらの対策の１つとなり得る可能性があるものと考えているところであります。いずれにしましても、今後もさまざまな状況を想定いたしましたトイレの充実と啓発に努めまして、発災時の安全安心、清潔なトイレの確保に努めていきたいと考えています。","voiceIndex":43,"id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"それぞれ研究をしていただいて進めていただきたいと思います。最後に、液体ミルクの活用について伺います。ここで、委員長に許可を得て、液体ミルクを紹介いたします。そこで、２点お伺いいたします。品川区が被災した場合、東京都から液体ミルクが提供される仕組みがあるのか伺います。提供された液体ミルクをむだにしないためにも、区の職員への認識を徹底してほしいと要望いたしますが、いかがでしょうか。","respondent":"曽田災害対策担当部長","answer":"したがいまして、液体ミルクも要望すれば来ると考えております。それから、液体ミルクの使用法などにつきましては、避難所運営や、あるいは物資配送、これに携わる職員に徹底することは大変重要なことだと考えております。","voiceIndex":45,"id":"exchange-022"},{"speaker":"新妻委員","kind":"提案","question":"ぜひよろしくお願いいたします。次に、ＬＧＢＴなど多様な生き方を支援するための区の考えを伺います。平成１５年６月の第２回定例会一般質問で、島くに子元区議が性同一性傷害の当事者から直接ご相談を受け、性的マイノリティの理解促進と行政文書のうち性別記載の不要なものは削除するよう提案しています。さらに、いつどの課が責任を持って調査されているのか伺います。見解をお伺いいたします。","respondent":"榎本総務部長","answer":"残り２２３件の様式につきましては、法令等の定めがありまして、まだ性別欄は残っておりますけれども、今後、定期的に調査を行いまして、性別欄の必要性について、削除できるかどうかを検討してまいりたいと思います。","voiceIndex":47,"id":"exchange-023"},{"speaker":"新妻委員","kind":"質問","question":"引き続き、よろしくお願いいたします。次に、テーマごとにお伺いします。そこで、人権啓発の角度から、２点お伺いします。１点目は、ＬＧＢＴに対しての課題全般は、人権問題と考えるべきと思いますが、ご所見を伺います。２点目は、ＬＧＢＴ当事者の置かれている現状をどう捉えているか、また、性的マイノリティの方が抱える困難については、どう認識されているか伺います。","respondent":"榎本総務部長","answer":"１点目につきましては、人権尊重都市品川宣言が今年２５周年目ということでございまして、その説明が宣言文の裏側にＰＲとしてつけておりますけれども、その中におきましても、性的指向や性自認を理由とする偏見や差別をなくそうということを掲げておりまして。","voiceIndex":49,"id":"exchange-024"},{"speaker":"新妻委員","kind":"提案","question":"職員の理解促進について伺います。今年の８月に福岡市の性的マイノリティに関する支援を会派で視察しました。窓口対応の研修を含め、市の職員への研修は当事者などが行っています。そこで、現在、品川区の職員に対しての研修は、誰が、どの職員を対象に行っているのか伺います。今後の研修においては、一層配慮が進むよう、当事者の方が行う研修を提案いたしますが、いかがでしょうか。","respondent":"榎本総務部長","answer":"今年度につきましては、性的マイノリティの方の対応も含めた労働ジャーナリストの方の講演会を１２月に実施する予定です。","voiceIndex":51,"id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"教育について伺います。平成２７年予算特別委員会の款別審査で、つる委員が性的マイノリティの学校教育の取り組みについて質問をしていますが、そのときの答弁は、どのような形で子どもたちに教育をしていくかについて、これから考えていくところと、まだ配慮が進んでいない状況でした。そこで、現状の確認と要望を込めて５点伺います。それぞれお伺いいたします。","respondent":"本城教育次長","answer":"最後に、標準服についてですが、相談内容にもよりますが、例えば、相談のあった際は、ズボンの着用を認めるなど、必要な配慮について個別に対応をしてまいります。","voiceIndex":53,"id":"exchange-026"},{"speaker":"新妻委員","kind":"質問・要望","question":"学校の中にも必ずこのような子たちはいる、そういう思いでまたより一層の配慮をお願いしたいと思います。次に、区民と民間企業、医療関係者への理解促進の取り組みと相談窓口についてです。今年度の参加状況や区民からのお声をお聞かせください。さらに、今後の理解促進の進め方をお伺いします。ご所見を伺います。品川区でも法的な配慮を含めた相談ができるような体制を求めますが、いかがでしょうか。","respondent":"榎本総務部長","answer":"今後の法的配慮を含めた相談ですけれども、今現在、性的マイノリティの方に対しましては、カウンセリング相談の中で対応しております。今後、その状況を見据えながら、女性相談員による法律相談につなげることが可能かどうかなどを検討してまいりたいと考えています。","voiceIndex":55,"id":"exchange-027"},{"speaker":"新妻委員","kind":"提案","question":"最後に、パートナーシップ制度について伺います。私は、提出者である品川区在住の自治体にパートナーシップを求める会の方から、直接ご相談を受けました。品川区でも条例策定も視野に入れた検討委員会の立ち上げを提案いたします。さらに、来年度改訂が予定されている品川区長期基本計画に、ＬＧＢＴをはじめ多様な生き方の支援を位置づけるよう要望いたしますが、それぞれ見解を伺います。","respondent":"榎本総務部長","answer":"その次の長期基本計画における位置づけですけれども、やはり性別にとらわれない人権尊重、多様な生き方への配慮ということで、いわゆるダイバーシティ＆インクルージョンという視点につきましては、長期基本計画の体系の中に位置づける方向で検討してまいりたいと考えています。","voiceIndex":57,"id":"exchange-028"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、さまざまな角度から現状や課題の確認をさせていただきました。制度があることで理解が広がると当事者は言っています。だからこそ、この求める会の方々は、多くの地域で請願・陳情を出されております。品川区が今後、多様性への理解促進が加速されますよう願って、私の総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-029"},{"speaker":"塚本副委員長","kind":"質問","question":"初めに、高齢者の暮らし、その中でも住まいとコミュニティバスについて質問します。高齢者の住まいについてですけれども、区は、平成２９年度予算で、高齢者住宅対策事業に１億２,５５２万円余を計上しておりまして、決算額は６,７４９万円余ということで、執行率が約５４.８％。住宅あっ旋事業の重要性に対する区の認識、それから現状の執行率にとどまっている原因について、初めにお伺いいたします。","respondent":"永尾福祉部長","answer":"そのような中で、区が間に立ってあっ旋をするということで、高齢者の住まいの確保という点では、大変効果がある事業だというふうに認識しているところです。","voiceIndex":61,"id":"exchange-030"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"この事業に対しては、款別審査で対象者の拡大、あるいは一括サービスとなっているところのセパレート化、このような質疑がありましたけれども、改めてこの事業の特徴についてご説明をいただきたいと思います。今ご答弁にもありましたけれども、不動産業者とか、大家、オーナーが、高齢者に物件を貸してもよいという理解を得るために、どのような周知をされているのか、その状況についてお伺いいたします。","respondent":"永尾福祉部長","answer":"８月から始めたということで、現在のところ、実際に契約を締結したのは１件となっておりますけれども、転居をするということになりますと、高齢者の方、いいなというふうに認識しても、すぐに転居まで行う勇気がなかなか出てこないということが現状でありますので。","voiceIndex":63,"id":"exchange-031"},{"speaker":"塚本副委員長","kind":"提案","question":"ご答弁よくわかりました。そのような中、款別審査の中で、住宅確保要配慮者に民間賃貸住宅への円滑な入居を促進するために設けられます居住支援協議会につきまして、区は設置に向けて準備を進めているということが確認できました。このようなものも参考に、品川区においても住宅部門と高齢者支援部門の連携強化のために、データ共有システムの構築を提案したいと思いますけれども、見解を伺います。","respondent":"中村都市環境部長","answer":"そのときにあわせて国のセーフティネット住宅情報提供システムの運用を注視していく必要があると考えますけれども、いずれにいたしましても、オーナー側と利用者双方が活用しやすい制度について、協議会の中で検討してまいります。","voiceIndex":65,"id":"exchange-032"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"平成２９年度に住宅セーフティネット法が改正されました。これは高齢者住宅生活支援サービス事業の預託金と目的が似ているものと感じておりますけれども、国の制度活用や区自身による改善努力によってさまざまな検討を加えていただきながら、高齢者の住宅生活支援サービス事業を推進していただきたいと要望いたしますけれども、これからの取り組みについて区の見解をお伺いしたいと思います。","respondent":"中村都市環境部長","answer":"そのためには、実際に窓口に来られる相談者の方の要望などの声をしっかりと聞き、その内容も踏まえ、しっかりと検討を進めてまいりたい、そのように考えております。","voiceIndex":67,"id":"exchange-033"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"よろしくお願いしたいと思います。次に、コミュニティバスについて質問いたします。コミュニティバスの路線の検討につきましては、区内全域から我が地域にと、このような要望が出てくることが想定されますけれども、路線検討においては、導入目的が何のためというところをできる限りわかりやすく明確にすることが肝要であるかと考えております。あわせて路線検討に当たっての見解もお伺いしたいと思います。","respondent":"中村都市環境部長","answer":"こうした視点のもと、交通の利便性のさらなる向上によりまして、高齢者の方々にももちろん使用していただくことを想定しております。財政負担の側面から、地域の方々、なるべく多くの方に利用していただくよう、そのような方策について、これから具体的な検討を進めてまいります。","voiceIndex":69,"id":"exchange-034"},{"speaker":"塚本副委員長","kind":"提案","question":"我が会派は、荒川区など他区のコミュニティバス導入事例を視察、研究しながら、平成２４年第３回定例会一般質問で、地域公共交通会議の設置と、コミュニティバス導入を提案し、以来、コミュニティバス導入の課題を研究し、導入に向けた提案をしてきました。地域公共交通会議をできるだけ早期に設置することを求めますが、設置のタイミングについて、区の見解を伺います。","respondent":"中村都市環境部長","answer":"ただ、検討を開始する来年度ですが、導入の基本的な考え方を整理しまして、運行ルートの選定のための現状調査、そしてルート選定の方向性を地域交通検討会を開催しながら進めてまいります。","voiceIndex":71,"id":"exchange-035"},{"speaker":"塚本副委員長","kind":"質問","question":"気候の温暖化による猛暑への対策について質問いたします。気象庁のデータによると、この夏、東京で気温３５度を超えた猛暑日は１３日となり、猛暑が区民の生活に与えた影響は大変に大きかったと感じております。この計画策定に至る経緯と計画の概要、さらに計画の中で温暖化問題に対する認識や対策がどのように定められているのか伺います。","respondent":"中村都市環境部長","answer":"区民、事業者の自主性を促す機運をさらに高めていく必要性、このようなところから平成２２年に策定しました品川区地球温暖化対策地域推進計画と、平成２５年に策定いたしました第二次品川区環境計画を統合いたしまして基本方針を定めたものです。","voiceIndex":73,"id":"exchange-036"},{"speaker":"塚本副委員長","kind":"質問","question":"温暖化対策ですけれども、これからも続くであろう猛暑が品川区民に与える影響に対して、区ができる対策が必要であると考えております。これまで区は暑さをやわらげる事業として、道路の遮熱性舗装や保水性舗装、ミストや打ち水など、水を使ったクールスポットの創出、エコ＆バリアフリー住宅改修を実施してきました。暑さ対策として、効果をどのように評価しているかもお聞きします。","respondent":"中村都市環境部長、藤田防災まちづくり部長","answer":"暑さ対策の実績のうち、まずミストにつきましては、平成１８年から２０年にかけて、真夏の暑い時期に戸越銀座商店街においてミストの発生機２台で実施しております。舗装における効果ですが、遮熱性舗装では８度、保水性舗装では、打ち水あるいは雨の降った後といったような条件にはなりますが、１０度程度の温度を下げる効果があるということで認識をしています。","voiceIndex":75,"id":"exchange-037"},{"speaker":"塚本副委員長","kind":"質問","question":"今伺いましたけれども、まず、道路については、遮熱性舗装と保水性舗装という２つの方式がありますが、それぞれの特徴、使い分けの考え方について伺いたいと思います。遮熱性舗装については、２年後のオリンピック・パラリンピック競技大会に向けて、会場周辺の道路に実施が予定されておりますが、オリンピック後も見据えた今後の考えについて伺います。","respondent":"藤田防災まちづくり部長","answer":"現在の計画ですけれども、先ほど委員からもお話がございましたオリンピック会場でもある大井ふ頭中央海浜公園周辺の道路について、遮熱性舗装を行う予定でございまして、こうした舗装を毎年１カ所ずつ進めていくという考えです。","voiceIndex":78,"id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"猛暑の日中は外出を避けるとしても、例えば、暑さのピークが過ぎる午後３時以降に多くの人が商店街に出かけるよう、商店街を涼しくする施策を拡大することは意味があると考えます。その際、東京都のクールスポット創出支援事業によるミスト設置や緑化整備、遮熱性舗装、保水性舗装などの補助制度を活用して施策が展開できるのではないかというふうに考えますが、区の見解を伺います。","respondent":"中村都市環境部長","answer":"区では、打ち水に使用します桶やひしゃく、またバケツ、このようなものの貸し出しを継続しておりますが、それとともに新たな団体への拡充として、例えば民間企業のＣＳＲの一環として実施したり、また、商店街のイベントを通じて、今年度、６商店街で実施されたり。","voiceIndex":80,"id":"exchange-039"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"これらは冷暖房の節電効果を本来の目的としていますが、屋根の遮熱性塗装では、屋根の表面温度を２０度下げるという実験結果もあり、暑さ対策にもなります。エコ＆バリアフリー住宅改修について、平成２９年度実績で、エコ目的の住宅改修が全体に占める割合について教えてください。遮熱性塗装など暑さ対策推進のため、予算全体の拡充を求めたいと思いますが、区の見解をお聞かせください。","respondent":"中村都市環境部長","answer":"ただ、このような案内、知られていないところもまだあると思いますので、周知、案内に努めるとともに、制度の利用者の声を踏まえ、予算についても適切な予算確保に努めてまいります。","voiceIndex":82,"id":"exchange-040"},{"speaker":"塚本副委員長","kind":"質問","question":"よろしくお願いしたいと思います。このような最新技術の公園遊具への活用について、公園に定められている規制との関係も含めて伺います。あわせて、今後は江東区にあるグランチャ東雲のような屋内施設も参考にしつつ、児童センターなど既存施設や今後の区全体の施設のあり方なども含めて、夏場の子どもたちの遊び場について、区としての考え方、見解を伺いたいと思います。","respondent":"藤田防災まちづくり部長、福島子ども未来部長","answer":"さまざまな最新技術等もあります。区としてこれらについても承知をしていますが、先ほど申したとおり、遊具のそばへの設置については慎重に検討をする必要があると考えています。私からは、夏の子どもの遊び場についてお答えいたします。区内には、２５の児童センターがございまして、他区と比較いたしましても、かなり充実していると考えております。","voiceIndex":84,"id":"exchange-041"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"体験型とのコンセプトなので、暑さ対策についても訪れた人が体験し実感できるよう設計されるものと受けとめていますが、どのようなことが考えられるのか、現時点でのご所見を伺います。戸越公園、文庫の森とも池があり、この水辺も生かした周辺一体の自然と生き物に触れながら環境の大切さを学べる場所にしていただきたいと思いますけれども、区のご見解をお伺いいたします。","respondent":"中村都市環境部長","answer":"今まで以上に自然環境を学びやすい環境となるように、環境学習施設の計画を進めてまいりたいと考えております。そして、自然の大切さと環境のかかわりについて、効果的に学習ができるように、そのような検討をしてまいります。","voiceIndex":87,"id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"よろしくお願いします。私からは、２３区で最低の福祉の改善と、高過ぎる国保料の引き下げを求めて質問いたします。かつては福祉の品川と言われたこの品川も、今やどの分野も２３区で最低レベルです。さらに、障害者のサービス利用計画を立てる相談支援事業所は４カ所しかなく、２３区で２３位と最下位。この１２年間で特養ホームと老健施設の整備がどれだけ進んだのか、なぜ成果だと掲げたのか伺います。","respondent":"永尾福祉部長","answer":"区といたしましては、高齢者の状態像や社会資源の状況、また保険料への影響、そのようなものをトータルに考えながら着実に進めているところです。","voiceIndex":91,"id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"なぜ成果と掲げたのか伺ったのですけれども、特養ホームと老健施設の定員増を区長は区長選挙で成果と掲げたのです。要介護５です。こうした実態に胸が痛まないのか伺います。そして、２３区で最も整備がおくれている最低の整備率を改善したいと区は考えているのか伺います。このままでいいと考えているのか、整備率がおくれていることで多くの不安を生み出していることを問題と考えないのか伺います。","respondent":"永尾福祉部長","answer":"ですので、こういう実態、またこのほかにもいろいろな実態がありますので、全てそういうところを利用者のアンケート、また普段のモニタリングでのご意見、そういうものをお聞きしながら。","voiceIndex":93,"id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問","question":"最低の整備率を改善したいと考えていないのか、問題ではないのか伺いましたので、お答えください。","respondent":"永尾福祉部長","answer":"２３区の整備率を見ますと、各区さまざま、片方は進んでいるけれども、片方は少し少ないというところが見られております。ですので、全ての施設についてすばらしく進んでいるというところはなかなか難しいのが現状だと考えています。","voiceIndex":95,"id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、最低の整備率で聞いているのは、特養ホームと老健施設のことです。これを改善させたいと思われているのか、そしてこういう状況が問題ではないのかということを伺いましたので、その件についてお答えください。","respondent":"永尾福祉部長","answer":"特養、老健の問題ですけれども、先ほど申し上げましたように、過去５年間に必要性を感じて整備をしています。それにつきましては、特養、老健のみが高齢者の幸せのための施設とは限りませんので、その他の施設も含めまして改善していきたいというふうに考えております。","voiceIndex":97,"id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"区長が成果として掲げた、それが２３区で最低だということで伺ったのです。２３区で最低の福祉を改善させるためには、必要な整備計画をつくることしかありません。七期は平成３０年から平成３２年度の計画です。２年ありますが、８期まで２３区で最低のままでいくのでしょうか。平成３０年２月締め切りで申し込んだ人の人数、入れた人の人数と割合、待っている間に亡くなった方の人数を教えてください。","respondent":"永尾福祉部長","answer":"平成２９年第２回の特養ホームの入所調整の進捗状況ですけれども、名簿の登録者が４３５人で、入所者が８１人、お亡くなりになった方が５２人というふうになっております。","voiceIndex":99,"id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"何割かということもお伺いしたのですけれども、今お答えいただいたこれが実態だということです。人生の最期にこのようにつらい思いをさせて胸が痛まないでしょうか。改善しなくていいと考えているのか伺います。そして、区がこれから取得する林試の森公園隣の国有地、都有地についても続けて伺います。社会福祉施設や子育て支援等々とあるのですけれども、現在の整備検討内容を教えてください。","respondent":"永尾福祉部長","answer":"国家公務員宿舎、旧小山台住宅の跡地の活用につきましては、現在、平成３１年度以降の用地の取得に向けて協議をしているところでございまして、それを受けまして、内容について、またさらに検討をしていきたいと考えております。","voiceIndex":101,"id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"６割の方がどこかしか入れているという答弁でした。ですので、申し込まれて入れていない方が多くいるという現状をしっかりと認識していただきたいと思いますし、この林試の森公園隣の国有地、都有地についてですけれども、区は地域密着型特養ホーム、そして就労継続支援Ｂ型の施設や小規模多機能などを検討しているというふうに言っていたと思うのですけれども、それでいいのか確認します。","respondent":"永尾福祉部長","answer":"それと、国家公務員宿舎、旧小山台住宅の整備に関してですけれども、現在、予定されておりますのは、保育園と地域密着型特別養護老人ホーム、認知症高齢者グループホーム、看護小規模多機能居宅介護。","voiceIndex":103,"id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問","question":"地域密着型特養ホームは、２９ベッド以下の施設です。現状の数に２９ベッドを足しても、２３区中２３位の最下位は変わりません。そして、この公有地には５階建てまで建設が可能だと思います。近隣住民の理解を得ながら、できる限りの定員数を確保してほしいと思いますが、いかがでしょうか。","respondent":"永尾福祉部長","answer":"ここには看護小規模多機能居宅介護もつくる予定ですので、在宅の方で少し医療的な支援が必要な方についても、通いと泊まり等を組み合わせた介護ができますので、そういうところも総合的に考えて、できるだけ住みなれた地域で生活を送るという意味合いから。","voiceIndex":105,"id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ早急にさらなる増設計画を立てるべきと強く求めて次へ進みたいと思います。次に、国保について伺います。そして、例えば、品川区に住む３０代の夫婦で、夫の年収４００万円、１８歳未満の子ども２人の４人家族で協会健保加入の場合、保険料負担は年１９万８,０００円ですが、同じ年収、家族構成の世帯が国保加入だと保険料は幾らになるのか伺います。","respondent":"福内健康推進部長","answer":"国保の構造的な問題ですが、加入者の年齢構成が高いこと、また、それにより医療費水準が高いこと、そして所得水準が低いことです。品川区の年収４００万円、４人世帯のモデルケースにした場合の国保料ですが、約４２万６,０００円です。","voiceIndex":107,"id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"提案","question":"国保は、協会健保の実に２倍の保険料です。全国知事会、全国市長会、全国町村会なども国庫負担の増額を求めております。２０１４年には、公費を１兆円投入して協会健保並みの負担率にすることを政府与党に求めました。なぜ一般財源、つまり、税金を国保の子どもの均等割無料化に使うことが不公平なのか伺います。区が考える公平な税金の使い方とは何なのか伺います。","respondent":"福内健康推進部長","answer":"国民健康保険料をお支払いしていただいている方が、医療給付を適正に受けていただくことが国民健康保険においての公平性と考えています。","voiceIndex":109,"id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"提案","question":"２３区区長会として、子どもの均等割無料化を求めているはずです。ですので、品川区も求めているということだと思うのですけれども、国の税金も、そして品川区の税金も、どちらも国民の税金です。国の税金なら入れることを求めるのに、区の税金ではできないという意味がわかりません。子育て支援にも大きくつながる子どもの均等割無料化を改めて求めますけれども、いかがでしょうか。","respondent":"福内健康推進部長","answer":"子どもの均等割軽減につきましては、区はこれまでも特別区長会や全国市長会を通して国に求めているものです。国からは、法定外繰入金を解消、縮減するように求められておりまして、子どもの均等割軽減を区が独自に実施するということは困難です。","voiceIndex":111,"id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ子どもの均等割、子どもの多い世帯を救う子育て支援になります。そうした税金の使われ方が社会的にも要請されていますし、品川区も２３区長会で求めていると思います。ぜひこうしたことを進めていただきたいと思います。そして、国保は社会保障です。高過ぎる国保料は引き下げ、そして子どもの均等割は無料化へ、ぜひとも進めていただきたいと思います。それぞれを求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"１年と少しです。さまざまに発生する被害について改めて伺います。落下物です。落下物件数の最新の数字について、国土交通省は昨年１１月から国内の７空港で部品欠落の報告を求めていますが、半年間で何件の部品欠落があったのか伺います。わかれば直近の１０月末までに何件なのかも伺います。それは目黒から五反田、大崎付近に当たりますが、この地域の危険性について国に確認しているのか伺います。","respondent":"中村都市環境部長","answer":"この対策を施したことによって落下物の状況がどうなるかというところでは、国からの説明では、外国の航空機も含めた落下物の予防低減策として、しっかりと進めていくというふうに聞いてあります。","voiceIndex":115,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"このパネルは飛行経路から３km離れたところに落下したと報道でもありました。このほかに氷の固まりも加わります。落下物の危険は広範囲に及び、この間、何度もゼロになるのかと聞いても、今のように国に求めていくというだけで、この対策でゼロになるとも明言できませんでした。次に、騒音です。例えば、大井町上空では何メートル高くなり、またそのことにより音は何デシベル軽減されるのか伺います。","respondent":"中村都市環境部長","answer":"検討に当たってどのように安全を確保するかは国の責任において考えるべきものという考えです。大井町上空では、何メートル高くなり、何デシベル軽減されるのかですが、これも国が安全性も踏まえた上で検討する中で出す結論です。","voiceIndex":117,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"全部国だと、あまりにも無責任ではないでしょうか。ここでｉＰａｄで画像を示します。ここに高度を高く上げるという話が出ていますが、３,０００フィート以下の区間では、高度を引き上げようとすると急降下となってしまうため引き上げができないと書いてあります。国土交通省もできないという対策を区長は求めたのでしょうか。伺いたいと思います。","respondent":"中村都市環境部長","answer":"区としましては、検討に必要な技術がございません。国が検討するべきものに対して、区が検討するということに対して責任も持てるものではございませんので、国に対して求める以外の方法はないものです。","voiceIndex":119,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"これは区長の発言としてあまりにも軽過ぎないでしょうか。このままでいけば、新ルートまであと１年少しです。１０月にはエールフランスが都心を低空飛行、今月の８日にもフランス機が、羽田離陸後ルートを外れ新馬場駅を通過、皇居の上を低空飛行しました。それぞれがどのようなトラブルだったのか、また、原因は何か、品川区は航空会社に抗議したのか伺います。","respondent":"中村都市環境部長","answer":"区としましては、国に対しまして徹底した再発防止と速やかな情報提供を引き続き行うよう、口頭で強く求めたところです。","voiceIndex":121,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"私は、航空会社に抗議したのかと伺いましたが、抗議したという答弁がありません。なぜ抗議をしないのか伺います。事故が起きなければ抗議をしないのか、今からでも抗議をすべきでしょう。伺います。","respondent":"中村都市環境部長","answer":"航空会社を所管するのは国土交通省です。やはりそのような管轄する所管の国の機関に要求をしたほうがより効果的であるといった考えに基づくものです。","voiceIndex":123,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民の不安は既に現実の問題なのです。国はまともに説明責任すら果たしていません。この間、区も議会も教室型説明会を求めてまいりましたが、いまだ開催されていません。なぜ実現しないのか伺います。区はこのような最低限の要求すら対応しない国に抗議したのかしないのか伺います。これはどのような内容なのか伺います。区内の具体的な影響や対策など、説明がされている内容なのでしょうか。伺います。","respondent":"中村都市環境部長","answer":"国の対応のうち教室型の説明会ですけれども、こちらは国が計画を示した当初から、区は国に対して求めているところです。区民の理解を深めるためには、国による教室型説明会を含めましたさまざまな形での説明や情報提供が必要と区でも考えております。","voiceIndex":125,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"全然穏やかといいますか、抗議したのかと伺ったのですが、抗議するそぶりすら見えません。都合のいいコマーシャルを、これは税金を使って国土交通省は一方的に流しながら、住民の疑問には答えない。さらに、地元自治体の声を聞くために、２０２０年計画実施までに開かれる国の協議会、そこに向けて開かれる都の連絡会、設置の目的と品川区は誰が参加することになっているのかご説明ください。","respondent":"中村都市環境部長","answer":"国会での首相発言も含めて、国からは、説明として、計画案が示された当初から地元の理解を深めるための丁寧な説明と情報提供、２０２０年までの目標、こういったものが示されてあります。","voiceIndex":127,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"私は、首相の発言をご紹介くださいと言いましたが、紹介したくないのでしょうか。国もそう言わざるを得ないのです。どういうことでしょうか。区長は、国に会いに行かないのか伺いたいと思います。羽田空港の機能強化に関する都および関係区市連絡会において、副区長が参加するとありましたが、区は計画への反対の意思表明をする考えがあるのかどうか、それぞれ伺います。","respondent":"中村都市環境部長","answer":"区民に対しての説明も十分ではないと考えております。羽田空港の新飛行経路案は、区民の安全安心が最優先です。国に対し、さらなる具体的な対応策を求めていく必要があるというふうに考えてあります。したがいまして、引き続き丁寧な説明と情報提供を国に求めてまいります。","voiceIndex":129,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"そう言い続けてもう何年たっているのでしょうか。もう１年少しで２０２０年です。飛ばされてしまいます。区は、区民の立場に立ち、地元が理解していないということを表明するべきだと私は思います。この点で、品川区民の計画への理解について伺いたいと思います。選挙後、議会で私は、現状で区民の理解は得られていないと区は認めないのかとたびたび伺ってきました。改めて伺いたいと思います。伺います。","respondent":"中村都市環境部長","answer":"区民の方々から、区もいろいろと意見を伺っております。それは理解が得られている、得られていないの２つの選択というところでなくて、区が捉えているのは、理解が十分ではないという捉え方です。","voiceIndex":131,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"理解が十分でないということは、区民の理解は得られていないということでよろしいのか確認させてください。はぐらかすのでしょうか。伺いますけれども、区長選挙では、３人区長選挙に出ましたけれども、撤回を求めた２人の候補者の得票合計は５２％と半数を超えたこと。区民の圧倒的多数が現時点では理解がないことははっきりしているのではないでしょうか。あわせて伺います。","respondent":"中村都市環境部長","answer":"理解が十分でないということについて、一番必要なものは、やはり丁寧な説明だと考えております。","voiceIndex":133,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"どうしても理解がないということをお認めにならない。なぜ住民の反対運動がこれだけ続いているのでしょうか。現時点で区民の理解がないからではないでしょうか。伺います。区が、区民の理解がないことを表明できない理由が何かあるのか伺いたいと思います。","respondent":"中村都市環境部長","answer":"今後も十分な説明会を施していただきたいですし、また落下物対策につきましても、さらなる具体的な提案をしていただくように、今、国に求めているところです。まだ実現はしてございません。","voiceIndex":135,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"現時点で区民の理解がない、このようなことすら認められない。区民の声や不安を何だと思っているのでしょうか。政権忖度区政の極みだと思います。さきの区長選挙では、この羽田新ルート計画の是非が大争点になりました。改めて区長はどのような公約を掲げたのか、選挙広報に何と書いてあるのか伺います。そして、これはどういう意味なのか伺います。","respondent":"中村都市環境部長","answer":"これが根底になければ、その後、どのような対策を立てたとしても全く無意味です。国に対してさまざまな具体策を求めていく根底には、安全安心というものを一番優先した提案をしてくださいというふうに国に対して求めているものです。","voiceIndex":137,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"ここで２つ目の画像をｉＰａｄで示したいと思います。もともとは、区長は、２年以上前に国土交通省に出かけ、国策だから甘受すると容認表明をし、国から感謝もされていました。伺います。この区長選での審判、示された民意を区長はどう考えているのか伺います。区長の区民の安全安心が最優先との公約と、当選後の一自治体が反対するわけにはいかないとの発言は、全く違うのではないですか。伺います。","respondent":"中村都市環境部長","answer":"一自治体だけに提案されたものではないです。そうした中で品川区は品川区民の立場に立って、丁寧な説明と不安の払拭を強く引き続き求めていかなければいけないという考えです。","voiceIndex":139,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長がいらっしゃいますので、ぜひ答弁をしていただきたいのですけれども、複数の自治体にまたがると言いましたが、この品川区が反対しなくてどうするのですかという感情が、今、区民にあふれています。区民の安全安心を最優先と公約に掲げながら、一自治体が反対するわけにはいかないと、計画の容認表明を行ったことは、これは公約違反ではないでしょうか。伺いたいと思います。伺います。","respondent":"中村都市環境部長","answer":"したがいまして、品川区としましては、この複数の自治体にまたがる経路と言いましても、やはり品川区民の立場に立って、寄り添って、国に対してさまざまな求めをしていくという立場で、引き続き、そのような考えで進めてまいりたいというふうに思ってあります。","voiceIndex":141,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"委員長、区長自身の公約なので、区長に伺っているので答弁を求めてもらえますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"非常に残念ですけれども、私たち共産党は、これらの区長公約や発言について質問してきました。しかし、一般質問でも決算特別委員会でも、このように区長は一切答弁に立ちませんでした。今も立っていません。改めて伺いたいと思います。しかし、区長が、一自治体が反対するわけにはいかないと発言し、反対しない意思表示を行ったのは、新ルートの容認表明そのものではないのか伺いたいと思います。","respondent":"中村都市環境部長","answer":"新飛行経路案について、初めて聞いたという意見もあります。したがいまして、やはり今行うべきものは、地域の皆様方への丁寧な説明を国に対してしっかり求めていくというところで、区民の皆様方に理解を深めていただくというところだと考えております。","voiceIndex":145,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"これも全く質問の答えになっていないのです。これ、私は原発問題と根っこは一緒ではないかと思います。先日、茨城県那珂市長が、住民の安全と命にかかわる問題だとして、東海第二原発の再稼働に反対表明しました。区長、このような発言をしてきたのですから、新飛行ルート計画でまさに品川区の上を飛行機が低空飛行しようとしている今、自治体の長として反対を表明するべきではないですか。伺います。","respondent":"中村都市環境部長","answer":"ただ、先ほどから申し上げておりますように、品川区内を通過するということも事実です。そのようなところに対して、環境影響に配慮した方策を具体的にしっかりと示すということが現時点で一番正しいと考えております。","voiceIndex":147,"id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"羽田新ルート計画は、区長と区議会が反対すればとめられます。共産党は、この計画を撤回させるため全力を尽くす決意を述べまして、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-072"},{"speaker":"いながわ委員","kind":"質問","question":"私からは、ＭＩＣＥ誘致等について、新たな集客イベントの誘致について、そして住宅等に対する助成金については、３点お伺いしてまいりたいと思います。国土交通省観光庁の国際観光政策の１つに、ＭＩＣＥの開催誘致の推進があります。日本政府観光局の報道発表では、昨年、世界で開催された国際会議は１万２,５６３件、日本開催は４１４件、世界７位、アジア・太平洋地域で１位となっております。","respondent":"中山企画部長","answer":"品川区ですけれども、羽田空港からの距離、あるいは新幹線、今後、リニアも建設されていく品川駅からのロケーション、このような地の利も考えると、このＭＩＣＥの誘致ということについて、区としても、ある意味でしっかりと受けとめて。","voiceIndex":151,"id":"exchange-073"},{"speaker":"いながわ委員","kind":"質問・要望","question":"前向きな捉え方で本当にありがとうあります。午前中の石田秀男委員の質問や答弁を聞いておりますと、品川においては、都市型観光が徐々に成熟している中でありますが、ぜひショートトリップを充実させ、我が区が持つ都市型観光資源をフルに生かし切って、滞在型の都市型観光の考え方でＭＩＣＥ品川の誘致推進を前向きにお考えいただきたいのですが、本区のご所見をお伺いします。","respondent":"安藤文化スポーツ振興部長","answer":"今後も一般の観光客に加えて、ビジネスイベントで訪れる人々をターゲットに都市型観光を積極的に推進するとともに、ご提案のＭＩＣＥ品川の可能性についても検討していきたいと考えています。","voiceIndex":153,"id":"exchange-074"},{"speaker":"いながわ委員","kind":"質問・要望","question":"非常に前向きなご答弁をありがとうあります。ショートトリップ部会があるということでありますので、外国人観光客のみならず、外から来た外客という観点で、ぜひそれをうまくコラボレーションしていただいて事業を進めていただきたいと思いますが、改めて何かございましたらお願いします。","respondent":"中山企画部長","answer":"そのような点では、今後さまざま、区の中のさらに大きな対応もできるような考え方についても幅広い視点で、区の中でも促進するような視点を入れて考えていきたいと考えております。","voiceIndex":155,"id":"exchange-075"},{"speaker":"いながわ委員","kind":"質問・要望","question":"我が会派としても、ＭＩＣＥに関しては積極的に調査研究を行っております。施設の整備も含めて充実したものにしてまいりたいと思いますので、ぜひよろしくお願いいたします。そして、今後、長期基本計画の策定の時期でもあります。ぜひこうした視点も盛り込んで議論をしていただきたい、そのように思っておるのですが、本区のご所見をお伺いします。","respondent":"中山企画部長","answer":"区の魅力の向上であるとか地域の活性化、こういうものは今後とも区の重要な課題になってくるということで、長期基本計画の中でもしっかり検討していく。","voiceIndex":157,"id":"exchange-076"},{"speaker":"いながわ委員","kind":"質問","question":"それに関連して、次に行きたいと思います。新たな集客イベントの誘致についてお伺いしていきたいと思います。ご存じのように、１１月７日発表の２０１８年ユーキャン新語・流行語大賞に、「ｅスポーツ」がノミネートされました。本区において、このｅスポーツについて、どのようなご認識があるかをお知らせいただければと思います。","respondent":"安藤文化スポーツ振興部長","answer":"主に１０代、２０代、３０代と、高校生や大学生を中心に盛り上がりを見せていると認識しております。アメリカではスポーツとして認められ、また中国や韓国では非常に人気のあるもので、優勝者には高額な賞金を手にする者もいると伺っております。","voiceIndex":159,"id":"exchange-077"},{"speaker":"いながわ委員","kind":"質問・要望","question":"しかしながら、世界の市場規模は約１,０００億円で、アジアの市場規模が最も多く３６％を占めております。誘致に向けた調査や研究を積極的に行っていただきたいと思いますが、区のご所見をお伺いしたいと思います。これは先ほど質問したＭＩＣＥとは多少それるかもしれませんが、こうした誘致が私は必要だと考えていますので、ぜひ前向きなご答弁をお願いいたします。","respondent":"安藤文化スポーツ振興部長","answer":"委員ご提案の世界レベルのｅスポーツの祭典をこの品川で果たして誘致できるかどうか、開催可能かどうかということを、今後しっかり研究調査してまいります。","voiceIndex":161,"id":"exchange-078"},{"speaker":"いながわ委員","kind":"提案","question":"次の質問に移ります。次は、住宅等に対する助成金について、３点お伺いしてまいりたいと思います。私は平成３０年第２回定例会において、パソコンやスマートフォンを使った助成制度の検索や受けられる概算金額の算出などができるインターネットサイトの開設を提案させていただきましたが、現在の取り組みについて、そして現在の状況をお知らせいただきたいと思います。","respondent":"中村都市環境部長","answer":"今現在は、ホームページでの現在の周知に加えまして、一歩進んだ啓発になるという考えのもと、実施に向けました検討を行っているです。","voiceIndex":163,"id":"exchange-079"},{"speaker":"いながわ委員","kind":"確認","question":"区役所に行かずに地元の工務店等に相談する段階で、多岐にわたる助成制度の適用の有無がわかる。制度活用がより一層進むものと考えております。改めての確認になりますが、本区として、そうした地域の方々と連携をして、さらに前へ、助成制度の執行率が上がるためにも、そして地域が安全安心のまちになるためにも、こうした認識は必要だと考えていますが、いかがお考えでしょうか。","respondent":"中村都市環境部長","answer":"そのようなところで、現在、区内の団体等に協力をいただいておりますけれども、このような便利な検索方法があれば、団体の方々、事業者の方々にそれを利用していただいて、さらに商売につなげていただくというところも可能性としてあると思いますので、引き続き。","voiceIndex":165,"id":"exchange-080"},{"speaker":"いながわ委員","kind":"質問・要望","question":"当時は、生け垣助成や防災緑化助成によるブロック塀の除却等の助成しかございませんでしたが、今回の補正予算では、安全安心なまちづくりの実現に向けて、さらに支援が充実することになると考えておりますので、私を含む会派の要望が実現したということであり、本当にこのブロック塀の除去助成の創設に関しては、高く評価するところであります。３点について、それぞれのご所見をお伺いいたします。","respondent":"中村都市環境部長","answer":"このような事業の区民への周知については、まずは広報しながわ１２月１日号でお知らせを予定しております。区のホームページでの紹介も準備中です。","voiceIndex":167,"id":"exchange-081"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ちょっと待てよ、それって、セットバックをしなければいけないんじゃないか」というやりとりから質問させていただきました。先ほど、インターネットサイトのお話しさせていただきましたが、ぜひこのようなブロック塀、同じような３つの助成金があるわけですから、このような内容もしっかりとインターネットサイトに載せていただきたいという思いがありますが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"先ほど申しました各種住宅に関する助成に加えまして、このようなブロック塀の安全化対策につきましても、区民が安心して暮らせる住環境の確保のための重要な事業と捉えております。インターネットを含めたさまざまな周知を行ってまいります。","voiceIndex":169,"id":"exchange-082"},{"speaker":"いながわ委員","kind":"提案","question":"最後に、窓口業務の充実についてお伺いしてまいりたいと思います。先ほど申し上げましたインターネットサービスとあわせて、充実した窓口対応も必要であると私は考えております。そこで、ここは１つ提案です。このワンストップサービス、窓口の設置を強く求めていきたいと思いますが、本区の前向きなご答弁をお願いします。","respondent":"中村都市環境部長","answer":"区役所へ相談や手続においでいただいたお客様の対応につきまして、現在、住まいに関する相談や手続は、都市環境部があります本庁舎６階にほとんどの窓口が集約されているという状況です。","voiceIndex":171,"id":"exchange-083"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それはすごく気遣いだと思うのです。だからこそ、こうしたワンストップサービスがあれば、他課にわたっているものを１つの窓口でやるということが、区民の皆様も安心して受けられる助成金制度になると考えていますので、ぜひこの辺に関しては前向きに調査研究をしながら、実施に向けてやっていただきたいと思いますので、よろしくお願い申し上げます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-084"},{"speaker":"須貝委員","kind":"意見","question":"無所属品川を代表して、総括質疑を行います。今、話題の武蔵小杉駅周辺は、十数本のタワーマンションが建ち、人口が急増しました。この状況についてご見解をお話しください。この地域ほどではありませんが、このような状況は今の品川区やこれからの品川区に当てはまると思いますが、ご見解をお聞かせください。","respondent":"中村都市環境部長","answer":"鉄道事業者に関しましても、計画段階から情報共有、また説明を行いまして、協議を行いながら計画を進めているところです。鉄道事業者も現状は十分に把握しているところであり、区は鉄道事業者にさらに働きかけ、改善を促していきたいと考えております。","voiceIndex":176,"id":"exchange-085"},{"speaker":"須貝委員","kind":"質問","question":"教えてください。そして、いまだに人口流入を抑制するどころか推進していますが、このことは長期間にわたる基本計画が一旦動き出すと、計画の修正が難しいからですか。教えてください。中央区や江東区などは、人口流入の抑制により、一部で住宅の容積率緩和などをやめる方針に転じていますが、区では、長期計画に縛られて方針転換はしないのですか。それともできないのですか。教えてください。","respondent":"中山企画部長","answer":"もちろん行政需要も高めますけれども、労働者人口といいますか、歳入増にもつながる面もありますので、区としてはこういうものを総合的に見ながら、メリットを大きくし、デメリットがあれば、そういうものについては手立てを打っていく。","voiceIndex":178,"id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"今の部長の答弁、魅力を高めるということですが、それよりも先に、私はやっぱり人口流入するという区の方針があって、それでタワーマンションの建設に踏み切ったかと思います。そして、今、歳入増の話がありました。ですが、施設が足りなくなれば、歳出増ということもこれからますます増えてくるわけです。施設を一時的にもつくらなければいけない。そういうことに関して、どのようにお考えでしょうか。","respondent":"中山企画部長","answer":"あるいは、行政需要の変化に対応できるような施設のありようを整備の段階から考えていくとか、将来に向けた負担を少なくしていきながら、ときどきの需要に対応していくというのは、行政として当然のことだというふうに思います。","voiceIndex":180,"id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"ただ、先ほどもお話ししましたけれども、一部の方に通勤・通学も含めて、やはりご迷惑をかけるということがありますので、私は、少し修正ということを考えてほしいと思います。教えてください。このように交通路を確保するため、警察官は足りませんので、災害時の停電に備えて、多くの交差点に非常用電源付信号機を早急に設置するべきではありませんか。そして、今後の対応について教えてください。","respondent":"藤田防災まちづくり部長","answer":"質問が多岐にわたってありますので、漏れが出てしまうかもしれませんけれども、ご容赦いただきたいと思います。台風あるいは大規模な地震等、さまざまな災害の中で停電はやはり想定される災害の１つかと考えています。","voiceIndex":182,"id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"しかし、首都直下大地震発生の被害想定は、冬の１８時、風速８ｍ、風が強く暗い道を移動しているときに、突然、停電が起きましたら、車はそこで立ち往生するのではないですか。もし停電になってしまったら。これ、定めがあるというふうになっていますが、私の調べでは、飛散物が衝突したときの、それに耐えられるかどうかという定めはないように聞いていますけれども、実際、大丈夫なのですか。","respondent":"藤田防災まちづくり部長、中村都市環境部長","answer":"しかしながら、先ほど申したとおり、そこまでに至らないようなケースももちろんあると思いますので、そういった際には、基本的に、全ての信号ではございませんが、主要な交差点の信号については。そのような観点から、品川区でも建物を建てる際には、このような基準以上に飛散防止対策について配慮をお願いするとか、また、区の開発環境指導要綱の中でも、脱落に備えて道路から落下物曲線以上離れた建物にするとか、あるいは。","voiceIndex":184,"id":"exchange-089"},{"speaker":"須貝委員","kind":"質問・要望","question":"私はこれは区民に対してしっかり持ち主、住民もそうですけれども、周知をしていただきたいと思います。私はそこはしっかりこれから対策をしてほしいと思います。では、その車が邪魔だからどけてほしい。教えてください。ということは、今のダンパーを早急に外したほうが、区で別に設置している免震ゴムの性能が生かされるため、建物にとってはより安全になると考えられますが、どうでしょうか。","respondent":"榎本総務部長","answer":"ダンパーを外したほうがという話ですけれども、ダンパーといってもかなり大きなものがついております。建築基準法上の基準は満たしておりますので、まずは構造計算を先に進めていきたいと考えています。","voiceIndex":187,"id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"建築基準法を満たしているということですが、そういうことなのでしょうか。このような不良のダンパーに対して、向こうがそう言ったから大丈夫だからと言って、そのまま鵜呑みにできるのでしょうか。私は、そこは考えなければいけないと思います。実際、いつこれは修繕できるのですか。その辺も考えないといけないのではないですか。その辺についてお考えをお聞かせください。","respondent":"榎本総務部長","answer":"いつ修繕できるかというところでありますけれども、最終的にはＫＹＢ社に不良品の交換をすることを求めていきますけれども、全国的に数が多いということで、見込みは立っていないところです。","voiceIndex":189,"id":"exchange-091"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうふうに考えていないということは、信じるしかないのですが、ただ、ダンパーの現物検査をしていないのです。災害時、区役所内に防災対策本部がつくられますが、不安から多くの区民が助けを求めて集まってくると思いますので、安全な施設になるように、緊急に改善が必要だと思いますが、対応策を教えてください。","respondent":"榎本総務部長","answer":"そのような意味で、災害対策本部機能をどういう形で展開するのか、もちろん総合庁舎、議会棟も使いますので、そのような中でどのような対応をとっていくかというのは、今後検討していかなければいけないと思いますけれども。","voiceIndex":191,"id":"exchange-092"},{"speaker":"須貝委員","kind":"質問・要望","question":"三層に建物がなって渡り廊下でつながっているのです。揺れがそれぞれ違う動きをしたら大変危険なものになると思います。それだけ指摘しておきます。今後きちんと直していただきたいと思います。最後に、見過ごされてきた学びの貧困、公立中学生の低学力層が問題視されていますが、この実態を把握していますか。教えてください。彼らの学力向上に対して、どのような対応をしていますか。教えてください。","respondent":"本城教育次長","answer":"そのような子どもたちにしっかりと学力を身につけていただくために、通常の学校の一般の授業のいろいろな工夫はもちろんのこと、いわゆる補習等を通じて、一人ひとりに対してしっかりとした対応をしていくことが必要だと考えているところです。","voiceIndex":193,"id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"全生徒を調べたら、かなりの人数がいるのでしょうか。どうなっているのですか。区独自で２０名以上の教員を採用してまで教員の配置基準をかなり上回る配置をしていますが、低学力層が実際に１８年前と変わらない、減らない、その成果が出ていないことに対して、一体どうなっているのか教えてください。学校の対応でしょうか。教員の質でしょうか。それとも教育委員会の指導でしょうか。教えてください。","respondent":"本城教育次長","answer":"それとあと、教員について、先ほど、品川区固有の教員についてのご指摘だと思いますが、固有の教員を採用する中で、今、品川区が、例えば英語教育、あるいは市民科教育、さまざまな取り組みをしていますが、このような品川区固有の充実した取り組みができる一端を担っているのが。","voiceIndex":195,"id":"exchange-094"},{"speaker":"須貝委員","kind":"質問","question":"先ほども申し上げましたが、１８年前と同じように、このように低学力層の中学生がいらっしゃる。私からすると、非常に残念です。文部科学省の配置基準より全然多いわけですね。こういうことは教育委員会で実態を把握しているのですか。学校からこういう定期テストのデータなどがきちんと教育委員会に届いているのですか。それについてもう１回教えてください。","respondent":"本城教育次長","answer":"区といたしましては、日常的な定期テスト等は、一次的には各学校が把握して対応すべき問題だと思いますが、ただ、品川区全体の子どもたちの学力を判定するためには、先ほどの全国的な学力調査のほか、品川区独自の学力調査もまたリニューアルして始めているところですが。","voiceIndex":197,"id":"exchange-095"},{"speaker":"須貝委員","kind":"意見","question":"私は、やっぱり１つ１つ学校にきちんと定期テストはどうなっているのか、どのぐらいの学力があるのか、きちんと把握してほしいと思います。先ほどから、学力定着度調査、テストを言いますけれども、これはあくまで品川区のテストを受けた全生徒の平均値です。この中には、ご存じのとおり、無回答もたくさんあります。その辺について、もう１回ご見解をお聞かせください。","respondent":"本城教育次長","answer":"定期テスト等について、ある意味、日常的なものについては、しっかりと各学校が対応し、定期テスト等で十分でないと判断された子どもたちには、一般の授業のほかに補習授業等も通じて個々に対応して、そのようなことで全体的な品川区の学校の全体体制を充実するとともに。","voiceIndex":199,"id":"exchange-096"},{"speaker":"須貝委員","kind":"質問・要望","question":"結局、充実とおっしゃいますけれども、実際こういう子どもたちがいるということは、私はやっぱり真摯に受けとめていただいて考えていただきたいと思います。彼らが社会へ出て働き出したら、社会でみずから生き抜いていける基礎学力は、やっぱり身につけさせてほしいし、これは学校と教育委員会の責務だと思います。これから頑張っていただきたいと思います。","respondent":"米田総務課長","answer":"消防から得られた情報です。先ほど、３時ごろですけれども、大井２－１３のあたりで煙のようなものが上がり、火災ではないかと消防に通報があり、消防自動車が急行したものです。現場を確認したところ、特に火災の事実はなく、細かな状況については、現在も調査中です。","voiceIndex":201,"id":"exchange-097"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初に、権利擁護と苦情処理のための第三者的な機関について伺います。生活者ネットワークは、権利擁護と苦情処理のため、区とは完全に独立した第三者的な機関が必要であるとして設置を求め続けております。その立場で質問をいたします。今回は、子ども、高齢者、障害者に絞り、かつ区の施策に対してということに絞って区に苦情の申し立てがあった場合、どのような手続で第三者的に処理をしているか伺います。","respondent":"福島子ども未来部長、永尾福祉部長","answer":"第三者委員ですけれども、区立保育園では、来年度設置を検討しておりますが、他の児童関連施設につきましては、苦情の数自体も少ないですし、当事者がその場で解決している事例が多いということもありますので。実際の支援サービスにつきましては、直接処遇をしている事業者でまず対応し、その中で解決しない場合は、事業者が設置している第三者委員会にかけて、その中で利用者からの事情をお聞きしたり。","voiceIndex":205,"id":"exchange-098"},{"speaker":"吉田委員","kind":"確認","question":"２０１２年の質問に答えたとおり、基本的には一番最初は当該のサービス事業者ということでよろしいでしょうかという確認と、それから、そういう手順で行われていますということを申し立てがあったときに伝えているのか。それから、どれくらいの目安でと、先ほど、子どものことは大体２週間か数日でというお答えがありましたけれども、高齢者、障害者についてはいかがかお知らせください。","respondent":"永尾福祉部長","answer":"なかなか両者の主張の折り合いがつかなかったりというところで、難しいケースが、件数的にはとても少ないですけれども、あることはあります。","voiceIndex":208,"id":"exchange-099"},{"speaker":"吉田委員","kind":"質問・要望","question":"それについても、それぞれ各所管、ご見解を伺いたいと思います。そのこと自体が、第三者機関としての機能がどうなのかというふうに思います。それはどうなのでしょうか。特に重度の障害者や要介護者にその傾向が強く見られると思います。しかし、そこから完全に独立した人権問題や行政不服申立の制度に詳しい弁護士や学者をメンバーとした第三者機関を求めたいと思いますが、改めてご見解をお願いします。","respondent":"福島子ども未来部長、永尾福祉部長","answer":"苦情を聞く機関としての周知が弱いということではありますけれども、私どもとしましては、苦情も含め、利用者のお声を聞くということは非常に大切なことだと考えておりますので、今後とも周知を図りまして。障害の部分につきましては、周知が弱いというところは先ほど述べたとおりですけれども、ただ、まずは事業者にというのは原則ではありますけれども、重要事項説明書の中には、障害者福祉課でも受け付けておりますとか。","voiceIndex":210,"id":"exchange-100"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう仕事量のことからも、ぜひ完全に独立した第三者的な機関を求めたいと思います。国の協議会にあわせて開かれている部長級の幹事会が既に１５回開かれていて、都としては、２３区５市の意見の確認はできていると都の担当者は言っています。２３区５市の意見の確認ということは、その中に当然品川区の意見が含まれていると思います。続けて、地元の同意の考え方を伺います。伺います。","respondent":"永尾福祉部長、中村都市環境部長","answer":"これまでいろいろな苦情を分析してみますと、利用者やご家族への説明不足だったり、利用者の状態把握の不足だったり、また利用者家族の要望の把握が不十分だったり、また職員間の情報共有、連携が不足しているとか。その際、教室型説明会を含むさまざまな方法を検討するです。この関係区市の連絡会ですけれども、こちらについては、まだ特に連絡を受けとっているということはございません。","voiceIndex":213,"id":"exchange-101"},{"speaker":"吉田委員","kind":"質問・要望","question":"これまでご説明いただいたような意見を繰り返し言っているということでしょうか。それから、今度の連絡会でも、そこまでの発言の内容になると理解してよろしいでしょうか。やっぱりそこでの発言の中で、いまだ地元での同意は得られていないということとか、根強い反対の声があるということは、きちんと言っていただきたいと思うのですが、その点についてはいかがでしょうか。ご見解を伺います。","respondent":"中村都市環境部長","answer":"教室型説明会を含むさまざまな方法を行っていただきたいというところで、あえて単にさまざまな方法というだけではなくて、「教室型説明会を含む」というふうにここに入れております。ただ、これを入れているにもかかわらず、いまだ実現をしていないという状況です。","voiceIndex":216,"id":"exchange-102"},{"speaker":"吉田委員","kind":"質問・要望","question":"現時点では、説明会を求めるまでは先に進めないというようなことで発言していらっしゃると理解してよろしいでしょうか。それから、最後にちょっと気になったのですけれども、この会はまだ未定なので、それ以外の具体的な発言内容についてはこれから検討ということでした。その検討内容をどういう形で決めていこうとされているのか、その辺について改めてご答弁を伺いたいと思います。","respondent":"中村都市環境部長","answer":"現時点におきましては、委員ご指摘のとおり、丁寧な説明と情報提供、またさまざまな方法の説明会です。","voiceIndex":218,"id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"現時点では、教室型の説明会を求め続けているにもかかわらず開かれていない。これからの発言内容についてですけれども、それをどういうふうに、だから内容については未定でわかりました。その中に、ぜひいまだ地元での同意、理解でもいいですが、得られていないということと、根強い反対の声があるということをきちんと言うべきと考えますが、その辺についてもご見解をお尋ねします。","respondent":"中村都市環境部長","answer":"したがいまして、これをあえてまたこの連絡会あるいは協議会の場で言うかどうかについても未定です。どのような内容で決定していくかのプロセスにつきましても、これも今後、発言する内容によって決定のプロセスは変わってまいると考えております。","voiceIndex":220,"id":"exchange-104"},{"speaker":"吉田委員","kind":"質問・要望","question":"決定のプロセスというのは、発言内容の決定のプロセスですか。そのさまざまな意見の中に、ちゃんと根強い反対の声があることを入れてくださっているのかということを確認させていただきたいと思います。それから、この連絡会での発言について、議会や区民が検証できるように、品川区の公文書として残し、かつ、適正に管理した上で公開すべきと考えますが、その点についてもいかがでしょうか。","respondent":"中村都市環境部長","answer":"ただ、この会議については取りまとめの場ですので、このような報告にとどまっております。ただ、区としての意見としては、やはり丁寧な説明、情報提供、そしてさまざまな説明会というところが意見としては申し伝えているところです。","voiceIndex":222,"id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、そのさまざまな意見として、ちゃんと反対意見を伝えてほしいというのが今の質問です。要旨。その中に品川区の発言が適正に記載されるかどうかはわからないと思っています。もちろん議事録確認をしていただいて、異議を言っていただきたいのですが、品川区としてちゃんとその発言内容を検証できるような形で残すべきではないかと申し上げております。その点について改めてお考えをお聞かせください。","respondent":"中村都市環境部長","answer":"ただ、これはやはり区として出席して意見を述べている以上、そこに反映されていないということになりますと、これは必要に応じて修正を求めることはしていかなければいけないというふうに考えております。これは委員のご指摘のとおりです。","voiceIndex":224,"id":"exchange-106"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、それぞれ区民の立場で、どういう発言をこういう場でしてくれているかをきちんと確認できるような形、だからもちろん議事録の中に全部明記されればいいですけれども、品川区としてこういうふうに発言してきたということを記録として残していただきたいと思います。そういう形にしていくべきと思います。それを品川区の例規集の中に掲載すべきと考えますが、いかがでしょうか。","respondent":"榎本総務部長","answer":"年間で２２万５,０００件を超える公文書の数という形で把握しておりますけれども、その中でどのように検討できるかということを進めてまいりたいと考えています。","voiceIndex":226,"id":"exchange-107"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですので、ぜひこれについては、私たちが拝見して、また納得のいく措置報告書が出されることを強く求めたいと思います。それから、文書の保存期間です。他区でも文書取扱規程の中に直接入っているところはあまりありません。公文書の問題はいろいろ不祥事とか出てきますけれども、そういうことを示すこと自体が品川区への区政の信頼につながると考えますが、ご見解を伺います。","respondent":"榎本総務部長","answer":"委員ご指摘の部分もそれぞれあると思いますけれども、全体として大量の文書、それも紙文書と電子文書をそれぞれ管理しているということで、その中で最善の方法を探っていきたいと思います。","voiceIndex":228,"id":"exchange-108"},{"speaker":"吉田委員","kind":"質問・要望","question":"文書の管理について、品川区としての基本的な考え方をお示しいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-109"},{"speaker":"渡部委員","kind":"質問・要望","question":"平成２９年度も日本経済の緩やかな回復基調が続き、実質経済成長率は前年度比で１.６％増となりました。品川区におきましては、引き続き、区民の福祉・生活の向上に努められますことを要望します。一例を挙げます。設備改修補助金について、補助率を２分の１に引き上げていただいた経緯はありますが、引き続き支援を継続いただきたく、さらに補助率をかさ上げできないか検討をいただけないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-110"},{"speaker":"若林委員","kind":"提案","question":"各特別会計においても、収支および執行率の状況などから、健全性が維持され、全体的には適正な運営と認識いたします。最後に、本決算特別委員会で公明党が取り上げた防災対策、ＬＧＢＴ、多様な性への支援、高齢者等住宅生活支援、コミュニティバス、猛暑対策をはじめ、総括質疑、款別審査の中での意見、提案を十分に検討し、来年度の予算編成や改訂される長期基本計画に反映されるよう要望します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":235,"id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この圧倒的多数の区民の声にこたえ、国に撤回を求めるべきです。国が求める３職種配置基準を満たす地域包括支援センターの設置を求めます。知的障害者グループホームや就労継続支援Ｂ型などの施設は２３区で最低レベル、増設計画策定と具体化を急ぐよう求めます。直ちに区独自に踏み出すことを求めます。中止を求めます。２９号線のために地域に愛されてきた大崎図書館解体は今からでもやめるよう求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-112"},{"speaker":"石田（し）委員","kind":"提案","question":"国民民主党・無所属クラブは、平成２９年度品川区一般会計および同国民健康保険事業会計、同後期高齢者医療特別会計、同介護保険特別会計、同災害復旧特別会計の各歳入歳出決算を認定します。本決算特別委員会での我が会派の指摘や提案を、次年度予算をはじめ今後の施策に反映するよう強く要望して、国民民主党・無所属クラブの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":239,"id":"exchange-113"},{"speaker":"須貝委員","kind":"質問・要望","question":"無所属品川は、平成２９年度の品川区一般会計、同国民健康保険事業会計、同後期高齢者医療特別会計、同介護保険特別会計、同災害復旧特別会計の各歳入歳出決算を認定します。中小企業は厳しい経営状況が続く上、跡継ぎ問題や人手不足により、廃業や倒産が続いています。通勤・通学に利用する鉄道の混雑緩和に力を注ぐとともに、公立中学校の低学力層の学力向上に全力で取り組んでいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-114"},{"speaker":"田中委員","kind":"提案","question":"見落としがちなトイレの備えについて、区民をはじめ区内企業への促しと徹底を求めます。このたびの決算特別委員会では、行政情報を積極的に開示し、区政への住民参加を推進すべきという立場で、品川・生活者ネットワークは事務事業の点検と政策提案を行いました。各款別審査で指摘・提案させていただいた意見を、予算編成に生かしていただくことを要望して、品川・生活者ネットワークの意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":243,"id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":100394,"voices":249}},{"id":"h30-20181120-10","meetingId":"h30-cm11","date":"2018年11月20日","dateIso":"2018-11-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年第３回定例会","agenda":"平成３０年第３回定例会","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"固定資産税・都市計画税の軽減措置の継続を求める意見書についてご説明いたします。本意見書は、東京都が現在実施している固定資産税および都市計画税に係る軽減措置を、平成３１年度以降も継続するように求めるものであります。以下、案文を読み上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"区議会防災訓練の実施","agenda":"区議会防災訓練の実施","exchanges":[{"speaker":"石田（し）委員","kind":"確認","question":"２点ありまして、まず１点目が避難所訓練なのですけれども、議員が参加する場合は、どういった服装で行くべきなのか。いわゆる防災服というのが議員には貸与されていて、以前もあくつ委員から、防災服をいつ着るのかという質問があったかと思うのですけれども、その辺の確認が１点。","respondent":"久保田区議会事務局長","answer":"２点目の、報告がなぜ必要かですけれども、これまで合同で訓練というのは、正式な形ではやっていなかったと認識しているのですけれども、区議会としての訓練は区議会としての訓練でやっていて、区内一斉訓練は区内一斉訓練でやっていまして。","voiceIndex":27,"id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問","question":"具体的に今までと違うやり方をやるというのだったら、何が違っているのかというのをしっかりしないと、せっかくこういう訓練をやるのであれば、実際を想定してやられたほうがいいわけで、どうしてあえて一緒にやるみたいなことを言っているのか、僕の中では理解ができないので、何を変更してそういったことになっているのかということだけは、しっかりと各議員が共有しないと、避難所訓練に参加しても。","respondent":"久保田区議会事務局長","answer":"今後、もし議会として、こういう訓練の際に何かを想定して、実際にどうやって動くのかということにつきましては、また委員の間で議論をしていただいて、それを踏まえて、区の防災課等とも連携をしながら、協議しながら、進めていきたいと考えています。","voiceIndex":29,"id":"exchange-003"},{"speaker":"石田（し）委員","kind":"確認","question":"なので、そこを明確にしておいてもらったほうがいいのかなというのは、議員全員がどういうことをやらなければいけないのかというのを共有しておいたほうが、前回何となく皆さんが覚えているものと、若干違っているのかなと思って、もし前回とそんなに変わらないのだったら、前回と変わらないでもいいし、大きく変わっているのだったら、何が変わって。","respondent":"久保田区議会事務局長","answer":"今回なぜこういう形をとったかですけれども、区内一斉防災訓練と合同でやるということになりますので、まず、避難所訓練に参加をするということであれば、本部訓練を同時間で開くということもできるのですけれども、区の訓練の想定が、午前中に１回本部を開いて。","voiceIndex":32,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"確認","question":"防災服の話が出たのですが、以前の議論の中で、あと、町会もそうなのですけれども、多分、これは一斉防災訓練なので、町会の方たちも、いきなり発災したという認識なので、基本的には防災服を着ないで皆さんも参加される。議論して、着ていくというのもありだと思うのですけれども、一応確認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"それだったら、防災服の話ではないけれども、議員が「議員です」といってわざわざ腕章をしていく必要は、私はあまりなくて、訓練にぱっと行くのなら、メールを送るのは別にそのときでなくても、どこかでちょっとメールを送って、それこそ今言った何人かを決めて、誰かそういう状況を送ってと会派で言っておくぐらいの感じで、それは後々、災害対策本部が立ち上がる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"意見","question":"ごもっともなのですけれども、では、そもそもこれの訓練をやる意義がよくわからなくなるけれども、東日本大震災でも、どの震災でもそうなのだけれども、議員が逆に、「俺は議員だ」と、「何かあるか」と騒ぎ立てて、問題になった地域が結構あって、我々としては、どういうふうにやるのがいいのかというのは検証が必要なのかなと思っているのです。多分、そのための防災訓練なのかなと思うので。","respondent":"渡部委員長","answer":"服装については、スーツで行かなければいけないとか、何で行かなければいけないというわけでは全くないので、普通の平服といいましょうか、普通の格好でいいのかなとも考えていますが、とりあえずそれでやってみるというのはいかがでしょうか。","voiceIndex":40,"id":"exchange-007"}]},{"id":"topic-03","title":"議長会等の報告","agenda":"議長会等の報告","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"今の法務局のところの話なのだけれども、あそこは基本的には、完全に仕分けされているのですか。一回、法務局の中みたいなところを通るのではなくて。","respondent":"久保田区議会事務局長","answer":"右側のほうに行ってしまいますと、法務局の中に入ってしまいます。法務局の職員用の出入口になりますが、左側は法務局の中は通らないで、昔でいうメール室があったところを通っていきますので、法務局とは分かれていますので、大丈夫です。","voiceIndex":55,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"あそこは入ってはいけないと私は思っていたのですけれども、特別にその期間だけ大丈夫ということでいいのですか。","respondent":"久保田区議会事務局長","answer":"張り紙されていて、「関係者以外入ってはいけない」となっていますけれども、議員の皆様は区の関係者ですから、入っても構いませんし、今回はエレベーターが使えない状態になっていますから、ご利用は問題ありません。経理課にも確認しています。","voiceIndex":57,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5306#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":14576,"voices":59}},{"id":"h30-20181205-10","meetingId":"h30-cm12","date":"2018年12月5日","dateIso":"2018-12-05","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":4276,"voices":18}}]);
